window.HB_TR["2-kings"]["ks"]=["1. اَمہِ پتہٕ کٔر موآبَن اَہاب سٕندِ مرنہٕ پتہٕ اِسرٲیلِس خٕلاف بغاوت۔\n2.\\tتہٕ احزیاہ پیوٚو پننِس پیٹھمہِ کمرس مَنٛز أکِس جالہٕ سٍتـ̡ یُس سامریاہس مَنٛز اوس، تہٕ اوسُس بٮ۪مار، تہٕ تٔمۍ سوٗزۍ قاصد تہٕ وونُن تِمن گٔژھِو، گژھِو عکرون کِس دیوتا بعلزبوب نِش پرژھہٕ زِ کیا بہٕ گژھہٕ امہِ بیمارِ نِش ٹھیٖک۔\n3.\\tمگر خداوند سٕندِ فرشتن ووٚن ایلیاہ تِشبیتس زِ وۅتھ، وُچھِو سامریہ کِس بادشاہ سٕندِس رسولن نِش تہٕ تِمن وَنُن، {کیا یہ} کیازِ {چُھنہ} اسرٲیلِس مَنٛز چُھہ نہٕ کانہہ خدا، {یُس} تُہۍ چھِو عقرون سٕندِس دیوتا بعلزیبوب سٕندِس پرژھہٕ گٲر کرنہٕ خٲطرٕ گٔژھان۔\n4. تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ ونان زِ تُہۍ گژھ نہٕ تتھ بسترس پیٹھٕ بۄن یُس تہٕ ژے کھسنہٕ آمُت چُھ، بلکہ گژھ یقینا مرُن۔ تہٕ ایلیاہ دراو درٛاو۔ {ژے کرُن...: ہیب۔ بسترس ییتہِ تہِ ژیہ تھوٚد کھسۍ، تتہِ گژھہِ نہ اتہِ منزہ وسُن}\n5.\\tییلہ رسول أمِس کُن واپس گٔیہ، تٔمۍ ووٚن تِمن زِ وُنۍ کیازِ چھِو واپس پھیرِمٕتۍ۔\n6. تہٕ تِمو ووٚن أمِس زِ اَکھ شخٕص آو اسہِ مِلنہٕ خٲطرٕ، تہٕ وونُن اسہِ ، گژھِ، دُبارٕ تُہۍ سوزمٕتِس بادشاہس کُن پھیُر، تہٕ وَنُن خداوند چُھ، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، {کیا یہ} چُھنہٕ امہِ مۅکھٕ زِ {اِسرٲیلِس مَنٛز چُھنہٕ کانہہ خدا}، {یُس} تہٕ ژے چُھہ عکرون سٕندِس دیوتا بعلزیبوب سٕندِس پرژھہٕ گٲر کرنہٕ خٲطرٕ سوزان۔ تَمہِ مۄکھٕ گژھِ نہٕ تَمہِ بسترہ پٮ۪ٹھٕ یَتھ پٮ۪ٹھ ژےٚ کھٔسِتھ ووٚتھ، بٔلکہِ گژھِ یٔقیٖنی طور مَرُن۔\n7.\\tتہٕ تٔمۍ ووٚن تِمن کُس انسان یُس تۅہہِ سمکھنہٕ خٲطرٕ آو تہٕ یِم لفظ وَنُن تہٕ وَنُن تۅہہِ کُنہِ شخصس سٍتـ̡ ۔ {کیا...: ہیب۔ مرد سُند طریقہ کیا اوس}\n8.\\tتہٕ تِمو دِژ أمِس جواب، {سُہ اوس} اکھ مَس دار نفر، تہٕ أمِس لٔگِس لٔگِتھ چُھس دالُک گٔنڈِتھ۔ تہٕ تٔمۍ ووٚن، یہِ چھُ ایلیاہ دِ تشبِٹ۔\n9. پتہٕ سوٗز بادشاہن پنژاہ پنژاہ ہُند کپتان أمِس نِش۔ تہٕ سُہ ووت أمِس نِش: تہٕ وُچھ، سُہ بِہتھ أکِس بالہٕ تھزرس پیٹھ۔ تہٕ تٔمۍ ووٚن أمِس سٍتۍ، اے خدایہ سُند انسان، بادشاہن ووٚنمُت، بۄن وُن۔\n10.\\tتہٕ ایلیاہ ہن دیُت جواب تہٕ وونُن پنژاہن ہٕندِس کپتانس، یێلہِ بہٕ خدایہ سُند انسان آسہِ، تیلہِ گژھہِ اسمانہٕ سٍتـ̡ نار وسُن، تہٕ ژے تہٕ تُہند پنژاہ کھالُن۔ تہٕ آسمانہٕ پیٹھہٕ آو نار تہٕ تٔمۍ سٕندِ پنژاہ کھٲلۍ۔\n11.\\tبییہِ تہِ سوُز تٔمۍ پنژاہ پنژاہ ہُند بیاکھ کپتان۔ تہٕ تٔمۍ دیُت جواب تہٕ وونُن أمِس خدایہِ سٕندِس انسانس یِتھٕ پٲٹھۍ ووٚن بادشاہن زِ جلدی گژھ بۄن وسُن۔\n12.\\tتہٕ ایلیاہ ہن دیُت جواب تہٕ وونُن تِمن زِ اگر بہٕ خدایہِ سُند انسان بٔنِتھ، اسمانہٕ سٍتـ̡ گژھہِ نار وسُن، تہٕ ژے تہٕ تُہند پنژاہ کھٲلِتھ گژھہِ۔ تہٕ خدایہِ سُند نار آو آسمانہٕ پیٹھٕ تہٕ تٔمِس تہٕ تٔمۍ سٕندِس پنژاہ سٍتـ̡ زٲلِتھ ۔\n13.\\tتہٕ تٔمۍ سوٗز بییہ تریمہِ نصف سنچرُک کپتان پنٕنۍ نصف سنچر۔ تہٕ پنژاہ ہُند تریم کپتان ووت تہٕ آو ایلیاہ برونہہ کُن کۅٹھن پیٹھ بٔرتھ، تہٕ تٔمِس کٔرٕن التجا تہٕ وونُن، اے خدایہِ سٕندِس انسان، بہٕ چھُس ژے دُعا کران زِ میون زُو تہٕ یِمن پنژاہ خادمَن ہٕنز زُو گژھہِ ژے نظرِ خٲطرٕ قیمتی روزُن۔ {فیل: ہیب۔ جھکُن}\n14.\\tوُچھ اسمانہٕ سٍتـ̡ نار ووٚتھ، تہٕ پٔتِمِس پنژاہن ہٕندِس دٔہلِس ہٕندِس دۅشوٕے کپتانن زٲلِتھ زٲلِتھ: تێلہِ گژھہِ میانہِ زُو ژے نظرِ تل قیمتی ۔\n15. تہٕ خداوند سٕندِ فرشتن ووٚن ایلیاہ سٕندِس سٍتـ̡ تہٕ گژھ نہٕ أمِس سٍتـ̡ خوف۔ تہٕ سُہ ووٚتھ، تہٕ ووت أمِس سٍتۍ بادشاہس نِش۔\n16.\\tتہٕ تٔمۍ ووٚن أمِس یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، یێلہِ تہٕ ژے چھُے پیغمبر سوزمٕتۍ، یێلہِ چُھہ نہٕ اِسرٲیلس مَنٛز کانہہ خدا یُس تٔمۍ سٕندِس کلامَس مُتلق پرژھہٕ گٲر کٔرِتھ؟ تَمہِ کِنۍ گژھِو نہٕ تَمہِ بسترہ پٮ۪ٹھٕ بۄن یُتھ تہٕ ژےٚ کھٔسِتھ چھِو، مگر یٔقیٖنی طور گژھِ مَرُن۔\n17.\\tتێلہِ گۆو سُہ خداوند سٕندِ کلامَس مُطٲبق یُس ایلیاہ ہن کتھ کورمُت اوس۔ تہٕ یہورام کٔر یہوداہ کِس بادشاہ یہوشافت سٕندِس نیچوِس یہورام سٕندِس دٔیمِس ؤریس مَنٛز أمۍ سٕنزِ جایہِ حکوٗمت۔ تکیازِ تس اوس نہ کانہہ نیچو۔\n18.\\tوۅنۍ یِم باقٕے اَحزیاہ سٕندِ اعمال یِم تٔمۍ کٔرۍ، کیا تِم چھِنہٕ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟","1.\\tتہٕ سپُد ییلہ خداوند ایلیاہ سٍتـ̡ طوفہٕ سٍتـ̡ اسمانس مَنٛز تُلِتھ ، ایلیاہ گۆو گلگل پیٹھٕ الیشاہس سٍتـ̡ ۔\n2. تہٕ ایلیاہ ہن ووٚن الیشاہَس یَتہِ روزُن، بہٕ چُھس ژےٚ دُعا کران تکیازِ خداوند چھہ میہ بیت القدس سوزمُت۔ تہٕ الیشاہن ووٚن تٔمِس {یێلہِ} خداوند زندٕ چُھ، تہٕ {یێلہِ} تُہند روح زندٕ چُھ، بہٕ تراوٕ نہٕ ژے ۔ چنانچہ گٔیہِ تِم بیتھل کُن۔\n3.\\tتہٕ بیتھلس مَنٛز یِم پیغمبرن ہٕندۍ نیچو آیہِ الیشعس نِش تہٕ وونُن زِ ژیہ چھے پتاہ زِ خداوند کرِ تُہند آقا از تہٕ تُہٕندِس کلہٕ نِش نِنہٕ؟ تہٕ تٔمۍ ووٚن، آ، مےٚ چھِ پتاہ {یہ}؛ پَنُن رٔٹِو پَنُن سکون۔\n4.\\tتہٕ ایلیاہ ہن ووٚن أمِس، الیشا، یَتہِ روزُن، بہٕ چُھس ژےٚ دُعا کران۔ کیازِ خداوند چُھ مے یریحو سوزمُت۔ تہٕ تٔمۍ ووٚن، {یێتھ} خداوند زندٕ چُھ، تہٕ {یێتھ} تُہند روح زندٕ چُھ، بہٕ تراوٕ نہٕ ژے تراوُن۔ چنانچہ آیہ تِم جیریکو۔\n5.\\tتہٕ یِریحہس مَنٛز یِمن پیغمبرن ہٕندِ نیچو آیہ، تہٕ وونُکھ تٔمِس زِ کیا ژیہ پتاہ زِ خداوند کرِ تُہُند آقا تُہٕندِس کلہٕ نِش نِنہٕ؟ تہٕ تٔمۍ دیُت جواب، آ، مے چھے پتاہ {یہ}؛ پَنُن رٔٹِو پَنُن سکون۔\n6. تہٕ ایلیاہ ہن ووٚن أمِس ، تاری، بہٕ چُھس ژےٚ یتہِ دُعا کران۔ تکیازِ خداوند چھہ میہ اردن سوزمُت۔ تہٕ تٔمۍ ووٚن، {یێتھ} خداوند زندٕ چُھ، تہٕ {یێتھ} تُہند روح زندٕ چُھ، بہٕ تراوٕ نہٕ ژے تراوُن۔ تہٕ تِم دۅشوے گٔیہِ برونہہ کُن۔\n7.\\tتہٕ پیغمبرن ہٕندِس نیچویو منزٕ گٔیہِ پنژاہ نفر تہٕ گٔیہِ دوٗر وُچھِتھ تہٕ تِم دۅشوے گٔیہِ اردنس نِش کھڑا۔ {وچھنہٕ خٲطرٕ: ہیب۔ نظرِ منز، یا، اوور خلاف}\n8.\\tتہٕ ایلیاہ ہن روٚٹ پنُن پوشہٕ، تہٕ لٔگِتھ لٔگِتھ آبس سٍتـ̡ تہٕ یِم گٔیہِ یور تہٕ تتہِ بٲگراونہٕ، یێلہِ گٔیہِ تِم دۅشوے خشک زمینس پیٹھ۔\n9. تہٕ ییلہ تِم نیرِ، ایلیاہ ہن ووٚن الیشاہس زِ بہٕ کیا کرٕ ژے خٲطرٕ، ژے نِش نِنہٕ برونہہ۔ تہٕ الیشاہن ووٚن، بہٕ چُھس ژےٚ دُعا کران، چانہِ روحُک دۄگنہٕ حصہٕ گژھہِ میٲنس پیٹھ۔\n10.\\tتہٕ ووٚن ژے اکھ مشکل کتھ پرژھمٕژ: {بہرحال}، اگر ژے مے وُچھِتھ {ییلہ بہٕ ژے نِش} نِش نِنہٕ ییہِ، سُہ گژھہِ تۅہہِ خٲطرٕ۔ مگر اگر نہٕ تیلہِ گژھِ نہٕ یہِ {تَتہِ}۔ {ژے ہاسٹ...: ہیب۔ ژے چھکھ پرژھنس منز سختی کٔرمٕژ}\n11.\\tتہ سپد یہ سپدان، ییلہ تم وُنہِ تہِ پکان ٲسۍ، تہ کتھ کران ٲسۍ، وُچھتھ گٔیہ نارُک اکھ رتھ تہٕ نارکۍ گُرۍ، تہٕ یِم دۅشوے الگ الگ کٔرۍ۔ تہٕ ایلیاہ ووت آسمانس مَنٛز۔\n12.\\tتہٕ الیشاہن وُچھ تہٕ وُچھُن میون مول، میون مول، اسرٲیلُک رتھ تہٕ تٔمِس سٍتـ̡ گُرِ سوار۔ تہٕ تٔمۍ وُچھ نہٕ سُہ بییہ کیٚنٛہہ: تہٕ تٔمۍ رٔٹۍ پنٕنۍ پَلَو، تہٕ تِم رٔٹۍ دۄن ٹُکرَن منٛز۔\n13.\\tتٔمۍ تُل ایلیاہ سُند پوشہٕ تہِ یُس أمِس نِش پیوٚو، تہٕ ووت واپس تہٕ ووت اردن کِس بٔٹھِس نِش۔ {بینک: ہیب۔ لپ}\n14.\\tتہٕ تٔمۍ تُل ایلیاہ سُند پوشہٕ یُس أمِس نِش پیوٚو، تہٕ لوٚگُن آبس سٍتـ̡ تہٕ وونُن، کتہِ چُھہ ایلیاہ سُند خدا۔ تہٕ ییلہ تٔمۍ تہِ آبس ٹاس دِژ، تِم گٔیہِ یور تہٕ تتہِ الگ تہٕ الیشع گٔیہِ۔\n15.\\tتہٕ ییلہ پیغمبرن ہٕندیو نیچویو یُس یریحاہس مَنٛز وُچھان اوس، تمو ووٚن زِ ایلیاہ سُند روح چُھ الیشاہس پیٹھ آرام کران۔ تہٕ تِم آیہِ أمِس سمکھنہِ، تہٕ گٔیہِ أمِس برونہہ کُن نمُن۔\n16.\\tتہٕ تِمو ووٚن أمِس زِ وُچھِو تہندٮ۪ن خادمَن سٍتـ̡ پنژاہ مضبوٗط نفر۔ تِم گژھن تراوُن، أسۍ چھِ ژےٚ دُعا کران، تہٕ پنُن آقا ژھانڈُن: نتہٕ یِم خداوند سٕندِ روحن تُلِتھ تہٕ کُنہِ پہاڑس پیٹھ، یا کُنہِ وادی مَنٛز تراوُن۔ تہٕ تٔمۍ ووٚن، تم سوز نہٕ۔ {مضبوط...: ہیب۔ سنز آف اسٹرینتھ} {کینہہ پہاڑ: ہیب۔ پہاڑو منزٕ اکھ}\n17.\\tتہٕ ییلہ تِمو أمِس زور دِتھ یوٚت تام أمِس شرم گوو، تٔمۍ ووٚن سوزُن۔ لہذا سوٗزۍ تمو پنژاہ نفر۔ تہٕ تمو ژھانڈ تریہ دۅہہ، مگر لوٚب نہ۔\n18.\\tتہٕ ییلہ تِم دُبارٕ أمِس نِش آیہ، (تکیازِ سُہ اوس یریکوہس مَنٛز روزان)، تٔمۍ ووٚن تِمَن، کیا مےٚ ووٚن نہٕ ژےٚ گژھُن؟\n19.\\tتہٕ شہرٕکۍ لوکو ووٚن الیشاہس زِ وُچھ، بہٕ چھُس ژےٚ دُعا کران زِ یَتھ شہرٕچ حالت چھِ خۄشگوار، یُتھ زن میون آقا وُچھان چُھ، مگر آب چُھ نہٕ کُنہِ تہٕ زمین بنجر ۔ {بیرن: ہیب۔ اسقاط حمل کرنُک سبب بنن}\n20. تہٕ تٔمۍ ووٚن، مے أنِو اکھ نوٚو صلیب، تہٕ اَتھ منٛز ترٛاوُن نوٗن۔ تہٕ تِمو أنۍ أمِس نِش۔\n21. تہٕ سُہ دراو آبہٕ کِس چشمس کُن، تہٕ ترووُن نوٗن، تہٕ وونُن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ مے چُھ یِم آبہٕ شفا دِژمٕتۍ۔ تتہِ گژھہِ نہ بییہ کانہہ موت یا بنجر {زمین}۔\n22.\\tیێلہِ چُھہ از تام آب شفا دِنہٕ آمُت، یُس الیشع سٕندِ قولہٕ مُطٲبق اوس۔\n23.\\tتہٕ سُہ ووت تتہِ پیٹھہٕ بیتھلس کُن، تہٕ ییلہ سُہ وتہِ ہیوٚر نیران اوس، تتہِ دراو لۅکٹۍ شُرۍ شہرٕ منز، تہٕ کوٚرُن أمِس ٹھٹھہٕ تہٕ وونُن، ہیوٚر کھٔسِو، اے گنج کلہٕ۔ ہیوٚر کھس، ژیہ گنج کل۔\n24. تہٕ سُہ پھیُر تہٕ تِمن کُن نظر تہٕ کٔرٕن خداوند سٕندِ ناوٕ سٍتـ̡ یِمن پیٹھ لعنت۔ تہٕ تتہِ دراو أمِس لٔکرِ منزٕ زٕ تہٕ تِمو منزٕ ژتٲجی تہٕ زٕ شُرۍ۔\n25.\\tتہٕ سُہ گۆو اتہِ پیٹھہٕ کارمل کِس پہاڑس تام، تہٕ تتہِ پۯاوُن سُہ سامریہ واپس۔","1. وۅنۍ کٔر یہورام سٕندِس نیچو یہوداہ کِس بادشاہ یہوشفات سٕندِس اردٲہمہِ ؤریس منز سامریہِ مَنٛز اسرٲیلِس پیٹھ حکومت کرٕنـ̡ شروع تہٕ کٔرٕن بہن ؤرین ہٕنز حکومت۔\n2. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس مَنٛز بُرٲے کٔرِتھ۔ مگر نہ پننس مٲلس پٲٹھۍ، تہٕ ماجہ ہٕندۍ پٲٹھۍ: تکیازِ تٔمۍ ترٲو بعل سُند شبیہہ یُس تٔمۍ سٕندِس مٲلس بنٲومُت اوس۔ {تصویر: ہیب۔ مجسمہٕ}\n3. بہر حال سپُد سُہ نیبت سٕندِس نیچوِس یربعام سٕندِس گۅنہٕ سٍتـ̡ ژٔٹِھتھ یێمہِ سٍتـ̡ اسرٲیلـ̡ گۅنہٕ گۅنہٕ بنیوو۔ سُہ گوٚو نہٕ تَمہِ نِش نیران۔\n4.\\tتہٕ موآبُک بادشاہ میشا اوس اَکھ کۅکرِ مالک، تہٕ دِتُن اسرٲیلِکِس بادشاہس اکھ لچھ کٹہٕ تہٕ اکھ لچھ کۅکرٕ یُس ییرٕ سٍتـ̡ دِنہٕ۔\n5.\\tمگر ییلہ احاب مرُن اوس تہ موآب کِس بادشاہن کٔر اسرٲیلِس بادشاہس خلاف بغاوت کرنہٕ۔\n6.\\tتہٕ بادشاہ یہورام دراو امی سامریہ منز، تہٕ کورُن سارِنٕے اسرٲیلِس شُمار۔\n7. تہٕ سُہ گوٚو یہوداہ کِس بادشاہ یہوشافتس نِش یہِ وَنُن زِ موآبُک بادشاہ چُھ میانہِ خلاف بغاوت کٔرمٕژ: کیا ژٕ گژھِکھ میہ سٍتـ̡ موآبس خلاف جنگہٕ خٲطرٕ؟ تہٕ تٔمۍ ووٚن، بہٕ گژھہٕ تھوٚد: بہٕ چُھس ژے ہٕندۍ پٲٹھۍ، میٲنۍ لوٗکھ تہٕ میٲنۍ گُرِ تہٕ پنٕنۍ گُرۍ۔\n8.\\tتہِ ووٚن اسہِ کمہِ وتہِ ہیوٚر پکان؟ تہٕ تٔمۍ دیُت جواب، ادوم کِس بیابانس مٔنزۍ وتھ۔\n9. یِتھٕ پٲٹھـ̡ گٔیہِ اسرٲیلُک بادشاہ تہٕ یہوداہُک بادشاہ تہٕ ادومک بادشاہ، تہٕ تِمو ہیوٚت ستن دۅہن ہُند سفرُک کمپاس۔ تہٕ میزبانس تہٕ یِمن پتہٕ یِنہٕ والٮ۪ن چارواین خٲطرٕ اوس نہٕ آب آسان۔ {یہ...: ہیب۔ تہندِس قدمن پیٹھ}\n10. تہٕ اسرائیلٕکۍ بادشاہن ووٚن، ہا! زِ خداوند چُھ یِم تریہ بادشاہ یکوٹہٕ بُلٲومٕتۍ، یُس تِم موآب کِس اتھس مَنٛز واتناوُن!\n11.\\tمگر یہوشافتن ووٚن، {کیا یتہِ} چُھنہٕ یتہِ خداوند سُند کانہہ پیغمبَر، یُتھ أسۍ خداوند سٕندِ سٍتـ̡ پرژھہٕ گٲر کٔرِتھ؟ تہٕ اِسرٲیلِکۍ بادشاہ سٕندِس أکِس خادمَن دِیُت جواب تہٕ وونُن، یێلہِ چُھ شافات سُند نیچو الیشع، یُس ایلیاہ سٕندِس اتھس پیٹھ آب ترووُن۔\n12. تہٕ یہوشافتن ووٚن خداوند سُند کلام أمِس سٍتـ̡ ۔ چنانچہ گٔیہِ اسرٲیلُک بادشاہ تہٕ یہوشفات تہٕ ادومک بادشاہ أمِس نِش۔\n13. تہٕ الیشاہن ووٚن اسرٲیلِس بادشاہس زِ مےٚ کیا چُھ ژےٚ سٍتـ̡ وابستہٕ؟ تہٕ پنہٕ نِس مٲلہِ سٕندِس پیغمبرن نِش تہٕ پننہِ ماجہ ہٕندِس پیغمبرن نِش گژھِ۔ تہٕ اسرٲیلٕکۍ بادشاہن ووٚن أمِس نہ، نہ، کیازِ خداوند چُھ یِم تریہ بادشاہ یکوٹہٕ بُلٲومٕتۍ، تاکہ تِم موآب کِس اتھس منز حوالہٕ کرنہٕ۔\n14.\\tتہٕ الیشاع ووٚن زِ یێلہِ بہٕ یہوداہ کِس بادشاہ یہوشافت سٕندِس حضورس سٍتـ̡ چُھس نہٕ بہٕ ژے کُن نظرِ تھاوان تہٕ نہ چُھہ ژے وُچھان۔\n15.\\tمگر وۅنۍ اَن میہ اکھ منسٹرل۔ تہٕ سپُد، ییلہ منسٹرل وایو، خداوند سُند اتھہ آو تس پیٹھ۔\n16.\\tتہٕ تٔمۍ ووٚن، خداوند چُھ یِتھٕ پٲٹھۍ ونان زِ یہِ وادی بناو کھۄلہٕ سٍتـ̡ بٔرِتھ۔\n17. یِتھٕ پٲٹھۍ چُھ خداوند ونان زِ واو وُچھِو نہٕ تہٕ وُچھِو نہٕ روٗد وُچھِو۔ توتہِ گژھہِ سۅ وادی آبہٕ سٍتۍ بٔرِتھ، یُتھ تۅہہِ تہٕ پنٕنۍ چارواے تہٕ پنٕنۍ جانور چیٚو۔\n18.\\tتہٕ یہِ چُھ خداوند سٕندِس نظرس مَنٛز اکھ ہلکہٕ چیز: سُہ کرِ موابی تہِ تُہندس اتھس مَنٛز۔\n19.\\tتہٕ تُہۍ کرِو پرٮ۪تھ کُنہِ تارٕ وٲلِس شہرس تہٕ پرٮ۪تھ کُنہِ ژٲرِس شہرس تہٕ پرٮ۪تھ أکِس اصل کُلِس ؤسِتھ تہٕ آبٕکۍ سارِنٕے کُلہٕ بند کٔرِو، تہٕ پرٮ۪تھ أکِس اصل زمینس کٔرِو کٔنِو سٍتـ̡ کٔنـ̡ ۔ {مار: ہیب۔ غم}\n20. تہٕ صُبحہ سپُد ییلہ ماز نذرانہ پیش کرنہٕ آو تہ وُچھِتھ آو ادوم کِس وتہِ آب تہٕ دیس آو آبہٕ سٍتـ̡ بٔرِتھ۔\n21.\\tتہٕ ییلہ سارِوٕے موآبیو بوٗز زِ بادشاہ چھِ تِمن خلاف لڑنہٕ خٲطرٕ آمٕتۍ، تِمو کٔر سٲری جمع یُس ہتھیار لاگنس لایق اوس، تہٕ ہیوٚر کُن تہٕ کھڑا سرحدس پیٹھ۔ {جمع: ہیب۔ اَکہٕ وَٹہٕ وَننہٕ آمُت} {پَلٲوِو...: ہیب۔ پانس کٔرِو گرڈل سٍتۍ}\n22. تہٕ تِم وُچھ صُبحس سُلہِ تہٕ آفتاب دراو آبس پیٹھ، تہٕ موآبیو وُچھ دوٚیمہِ طرفہٕ آب {یِتھ} خونٕکۍ پٲٹھۍ وۄزل۔\n23.\\tتہٕ تِمو ووٚن، یہِ چُھ خون: بادشاہ چھِ پٔزۍ پٲٹھۍ مارنہٕ آمٕتۍ، تہٕ تِمو چُھ اکھ أکِس مارمُت، تَمہِ مۅکھہٕ چُھہ موآب، غنیمتس سٍتـ̡ ۔ {قتل: ہیب۔ تباہ}\n24.\\tییلہ تِم اسرٲیلِس کِس خٲمس مَنٛز وٲتۍ، اسرٲیلِیو ووٚتھ تہٕ موآبین لٔگِتھ ژٔلِتھ تہٕ تِمو ہٕندِس ملکس مَنٛز تہِ لٔگِتھ لٔگۍ۔ {تِم گٔیہِ...: یا، تِمو دِژ اَتھ منز مارٕ تہِ}\n25.\\tتہٕ تِمو لٔٹِتھ شہر، تہٕ پرٮ۪تھ أکِس اصل زمینس پیٹھ ترٛٲوِکھ پرٮ۪تھ أکِس انسانس پَنُن کٔنہِ، تہٕ بٔرِتھ بٔرِتھ۔ تہٕ تِمو رُکٲوِکھ آبٕکۍ سٲری کۄرٕ، تہٕ ژٔٹِکھ سٲری اصل کُلۍ: صرف کرہارسیتھس منز ترٲوۍ تِمو اَمہ کِنۍ کٔنہِ۔ بہرحال گٔیہِ گُلۍ، تہٕ لٔگِتھ لٔگۍ۔ {صرف منز...: ہیب۔ یوتام نہٕ تٔمۍ امکۍ کٔنۍ کرہاراستھس منٛز ترٛٲوۍ}\n26. تہٕ ییلہ موآب کِس بادشاہن وُچھ زِ جنگ چُھ أمِس خٲطرٕ سٮ۪ٹھاہ درد، تٔمۍ نِیہِ پانس سٍتـ̡ سَتھ ہتھ نفر یِمو تلوار تُلِتھ تہٕ ادوم کِس بادشاہس تام واتنہٕ مۅکھہٕ، مگر تِم ہیوٚک نہٕ۔\n27.\\tتمہِ پتہٕ نیو تٔمۍ پنُن زِٹھہِ نیچو یُس أمِس بدلہٕ حُکوٗمت کرُن آسہِ، تہٕ دیتُن دیوارس پیٹھ دزنہٕ آمُت نذرانہ پیش کرنہٕ۔ تہٕ اسرٲیلِس سٍتـ̡ گۆو سٮ۪ٹھاہ غصہٕ، تہٕ تِمو گٔیہِ أمِس نِش تہٕ گٔیہِ پننِس زمینس کُن واپس۔","1.\\tتێلہِ وۆن پیغمبرن ہٕندٮ۪ن نیٚچوٮ۪ن ہٕنزِ زنانہِ ہٕنزِ زنانہٕ ہٕنزِ زنانہٕ ہٕنزِ زنانہٕ الیشعس نِش وۆن، تێہُند خانٛدار چُھس مٔرۍمُت۔ تہٕ ژے چھے پتاہ زِ تُہند خادم اوس خداوند سُند خوف تہٕ قرض دِنہٕ وول آو میٲنۍ زٕ نیچوۍ أمِس نِنہٕ خٲطرٕ۔\n2. تہٕ الیشاہن ووٚن أمِس زِ بہٕ کیا کٔرٕ ژےٚ خٲطرٕ؟ میہ وَن، ژیہ کیا چُھس گرس منز؟ تہٕ ووٚن تۅہہِ ہٕنزِ دٲیرِ ہٕندِس گرس منز چُھنہٕ کانہہ چیز، تیٖلہٕ ورٲے چھُنہٕ کانہہ چیز۔\n3.\\tاَمہِ پتہٕ ووٚن تٔمۍ سٍتـ̡ پنہٕ نِس سارِنٕے ہمساین ہٕندِس نِش نِش نِنہٕ یِنہٕ وٲلِس بانہٕ، {حتیٰ کہ} خٲلی بانہٕ۔ کینہہ نہ قرضہٕ۔ {ادھار نہٕ...: یا، کم نہٕ}\n4.\\tتہٕ ییلہ ژیہ اژِو، تہٕ ژے گژھ پانس تہٕ پننین نیچوین پیٹھ دروازٕ بند کرُن، تہٕ یِمن سارِنٕے بانن مَنٛز تراوُن تہٕ یُس بٔرِتھ آسہِ۔\n5.\\tتہ سۅ گٔیہِ أمِس نِش تہٕ دروازٕ بند کٔرِتھ أمِس تہٕ پننین نیچوین پیٹھ، یِم أمِس نِش اَننہٕ آمٕتۍ۔ تہٕ سۅ دِژ نیبر۔\n6.\\tتہٕ ییلہ بانہٕ بٔرِتھ گٔیہ، تٔمۍ ووٚن پننِس نیچوِس زِ مے أنِن اکھ بانہٕ۔ تہٕ تٔمۍ ووٚن أمِس {اَمہِ علاوٕ چھُنہٕ کانہہ برتن}۔ تہٕ تیٖل روٗد روٗد۔\n7.\\tتمہِ پتہ آیہ سۅ خدایہ سٕندِس مردس وونُن۔ تہٕ تٔمۍ ووٚن، گژھ تیٖل کٕنُن، تہٕ پنُن قرضہٕ ادا کرُن، تہٕ تُہۍ تہٕ باقین ہٕندِس شُرِس روزُن۔ {قرض: یا، قرض دِنہٕ}\n8.\\tتہٕ سُہ پیوٚو اَکہِ دۅہہٕ یُس الیشع شونیمس کُن گٔیہِ، یتہِ {اَکھ بٔڈ زنانہٕ} ٲس۔ تہٕ تٔمۍ کوٚر سُہ روٹی کھٮ۪نہٕ خٲطرٕ مجبور۔ تہٕ {یِتھ} اوس یہِ، {یہ} ییلہ سُہ اتہِ پکان اوس، سُہ اوس تتہِ روٹی کھٮ۪نہِ۔ {یہ پیوٚو اکہ دۅہہ: ہیب۔ اَکھ دۅہ اوس {مجبور: ہیب۔ تھپھ کٔرِتھ تھپھ کٔرِتھ}\n9. تہٕ تٔمۍ ووٚن پننِس خاندارس زِ وُچھو وُن، بہٕ چُھس سمجھان زِ یہِ چُھ خدایہِ سُند اکھ مقدس انسان، یُس اسہِ نِش مسلسل گزران چُھ۔\n10. بہٕ چُھس دیوارس پیٹھ اکھ لۄکُٹ کمرٕ بناوُن؛ تہٕ أسۍ تھاوو تٔمِس خٲطرٕ اَتہِ اکھ بستر، تہٕ اکھ میز، تہٕ اکھ سٹول تہٕ اکھ شمعدان: تہٕ ییلہ سُہ اسہِ نِش یِیہ، سُہ گژھہِ تتہِ پھیرِ۔\n11.\\tتہٕ سُہ آو اَکہِ دۅہہ یُس سُہ تتہِ آو تہٕ سُہ گوٚو کمرس مَنٛز، تہٕ لوٚگ اَتہِ لوٚگ۔\n12.\\tتہٕ تٔمۍ ووٚن پننِس خادمَس گِہازی یَس وَنُن یَتھ شُنَمِٹَس وَنُن۔ تہٕ ییلہ تٔمۍ أمس بلاو، سۄ ٲس أمس برونہہ کنہِ کھڑا۔\n13.\\tتہٕ تٔمۍ ووٚن أمِس وَنُن، وُچھ، ژے چھُکھ سانہِ خٲطرٕ یِتھٕ سارِوٕے احتیاط کٔرِتھ۔ تۅہہِ خٲطرٕ کیا گژھہِ کرنہٕ؟ کیا تۅہہ کٔرِو بادشاہس سٍتۍ کتھ کرنہٕ، یا میزبانہٕ کِس کپتانس سٍتۍ؟ تہٕ تٔمۍ دیُت جواب، بہٕ چُھس پننین لوکن منز روزان۔\n14.\\tتہٕ ووٚن تٔمۍ سٕندِ خٲطرٕ کیا کرُن؟ تہٕ گیہازین دیت جواب، پزۍ پاٹھۍ چھہ نہ أمس کانہہ شُر، تہٕ تہند خاوند چھہ بُزرگ۔\n15. تہٕ تٔمۍ ووٚن، أمِس فون کٔرِو۔ تہٕ ییٚلہ تٔمۍ أمس فون کوٚر، سۄ کھڑی دروازس منٛز۔\n16.\\tتہٕ وۆنُن زِ یَتھ موسمس مُطٲبِق، زندگی ہٕندِس وقتس مُطٲبق گژھ ژے نیچو رٔٹِتھ۔ تہٕ تٔمۍ ووٚن، نہ، میانہِ مالک، خدایہ سُند انسان، پننہ خادمہ سٍتۍ مہ کٔر اپُز۔ {سیزن: ہیب۔ ٹایِم سیٹ کٔرِو}\n17.\\tتہٕ زنانہِ ہٕندِس زمانس مُطٲبق زاے ہُند نیچو زاو تہٕ زیٚوُن تٔمِس سٍتـ̡ یُس الیشاہن أمِس وونُن اوس ۔\n18.\\tتہٕ ییلہ شُر بوٚڈ گوٚو، سُہ پیوٚو أکِس دۅہہٕ زِ سُہ گوٚو مٲلِس نِش ریپرَن نِش۔\n19. تہٕ تٔمۍ ووٚن پننِس مٲلِس ، میون کلہ، میون کلہٕ۔ تہٕ تٔمۍ ووٚن أکِس لڑکَس نِش نِش نِنہٕ أمِس ماجہِ نِش۔\n20. تہٕ ییلہ أمِس نِتھ ماجہ نِش أنِتھ، سُہ بِہتھ دُپہرس تام کۅٹھن پیٹھ بِہتھ تہٕ {پتہٕ} موٗد۔\n21.\\tتہٕ سۅ گٔیہِ تھوٚد تہٕ لوٚگ سُہ خدایہ سٕندِس بسترس پیٹھ، تہٕ دروازٕ بند کٔرِتھ دِژٕن نٮ۪بر۔\n22.\\tتہٕ تٔمۍ بُلوو پننِس خاوندس تہٕ وونُن، بہٕ سوز ژے، اکھ جوان تہٕ گَرٕ منزٕ اکھ، یُتھ بہٕ ژلہٕ خدایہ سٕندِس انسانس نِش ژلِتھ تہٕ دُبارٕ یِتھ۔\n23.\\tتہٕ تٔمۍ ووٚن، ژٕ کیازِ چُھکھ از تس نِش گژھُن؟ {یہِ} چُھ نہٕ نٔو زوٗنہٕ تہٕ نہ سبت ۔ تہٕ تٔمۍ ووٚن، {یہ گژھہِ} ٹھیٖک۔ {پٲٹھۍ: ہیب۔ امن}\n24.\\tتمہِ پتہ لوٚگ اَکھ گَرٕ تہٕ وونُن پننِس خادمس تہٕ وونُن پٔرِتھ برونہہ کُن۔ میانہِ خاطرہ گژھ نہ سوارِ سوارِ سٍتۍ، بہ چھس ژیہ وُچھان۔ {سلیک ...: ہیب۔ رُکٲوِو نہٕ مےٚ سوارِ خٲطرٕ}\n25. تہٕ سۄ گٔیہِ تہٕ خدایہ سٕندِس انسانس نِش آیہ کارملس پیٹھ کھسنہٕ خٲطرٕ۔ تہٕ سپد ییلہ خدایہ سٕندِ مردس أمِس دوٗر وُچھ، تٔمۍ ووٚن پننِس خادمس گیہازِس وُچھ، وُچھ، {یُس چھُ} زِ شُنمِٹ:\n26.\\tژلہِ ژلہِ ژیہ ژیہ دُعا زِ تس سمکھنہٕ خٲطرٕ تہٕ ونُن، {کیا چُھہ ژے ٹھیٖک؟ {چانہِ خاندارس چھا ٹھیٖک ٹھیٖک؟ {کیا یہ} چھَا شُرِس ٹھیٖک ٹھیٖک؟ تہٕ تٔمۍ دیُت جواب، {یہٕ چُھ} ٹھیٖک۔\n27.\\tتہٕ ییلہ سۅ خدایہ سٕندِس مردس نِش بالس پیٹھ آیہ، تٔمۍ رٔٹۍ أمِس کھۅرن تھپھ کٔرِتھ، مگر گیہازی آو أمِس نِش دِنہٕ خٲطرٕ۔ تہٕ خدایہِ سٕندِ مردَن ووٚن، أمِس گژھ کُنہِ کُنہِ۔ تکیازِ تٔمۍ سُند روح چُھ پانس اندر پریشان گومُت: تہٕ خداوند چُھ میہ نِش ژوٗرِ تھوومُت، تہٕ چُھنہٕ مے وونُن۔ {ہم...: ہیب۔ تٔمۍ سٕندِس قدمن سٍتۍ} {پریشان: ہیب۔ تلخ}\n28.\\tاَمہِ پتہٕ ووٚن تٔمِس زِ بہٕ اوسُس پننِس آقا سُند نیچو یژھان؟ میہ کیا ووٚن نہ، میہ کٔر نہ دھوکہٕ؟\n29.\\tاَمہِ پتہٕ ووٚن تٔمۍ گیحازی زِ پَنٕنۍ کمر رٔٹِتھ میٲنۍ لٔرِتھ رٔٹِتھ تہٕ گژھ پننہِ وتہِ: اگر ژٕ کٲنٛسہِ نفرس مِلِتھ تہٕ تٔمِس کٔرِو نہٕ سلام۔ تہٕ اگر کانہہ ژےٚ سلام کرِ، تیٚلہِ کٔرِو نہٕ أمِس دُبارٕ جواب: تہٕ تھووُن میون لُٹھ شُرۍ سٕندِس بُتھِس پیٹھ۔\n30. تہٕ بچہٕ سٕنزِ ماجہ ووٚن، {یێلہِ} خداوند زندٕ چُھ، تہٕ {یێلہ} تُہند روح زندٕ چُھ، بہٕ تراوٕ نہٕ ژے تراوُن۔ تہٕ سُہ ووٚتھ تہٕ أمِس پتہٕ۔\n31.\\tتہٕ گیہازی پیوٚو تِمن برونہہ کُن تہٕ تھووُن شُرِ سٕندِس بُتھِس پیٹھ لٔٹھ۔ مگر {اتہِ} ٲس نہ آواز، نہ بوز۔ اَمہِ مۄکھٕ گوٚو سُہ دُبارٕ أمِس سمکھنہِ، تہٕ وونُن أمِس زِ شُر چُھ نہٕ بیدار۔ {بوزن: ہیب۔ توجہ}\n32.\\tییلہ الیشع گرس منز آو، وُچھ شُر اوس موٗدمُت، تہٕ اوسُس بسترس پیٹھ لوٚگمُت۔\n33.\\tسُہ گۆو اژُن، تہٕ دروازٕ بند کٔرِتھ کٔرٕن خداہس سٍتـ̡ دُعا۔\n34.\\tتہٕ سُہ ووت تھوٚد تہٕ شُرِس پیٹھ لوٚگ، تہٕ تھووُن ٲسس پیٹھ، تہٕ أچھ أچھن پیٹھ، تہٕ اتھہٕ تھووُن شُرِس پیٹھ۔ تہٕ شُرۍ سُند ماز اوس گرم گٔمُت۔\n35.\\tامہ پتہ آو سُہ واپس، تہٕ گٔژھ گرس منز یور یور پکان۔ تہٕ ووت تھوٚد، تہٕ لوٚگ پانس پانس کُن، تہٕ شُرۍ کٔر سَتھ لٹہِ نۄچھ، تہٕ شُرۍ کٔر أچھ کھول۔ {ٹو اینڈ فرو: ہیب۔ اکہ لٹہِ یور تہٕ اکہ لٹہِ تتہِ}\n36.\\tتہٕ تٔمۍ بُلوو گیہازی تہٕ وونُن، یَتھ شُنمِیت وَنُن۔ چنانچہ تٔمۍ کوٚر أمس فون۔ تہٕ ییٚلہِ سۄ أمِس نِش آیہ، تٔمۍ ووٚن، پنُن نیچو رٔٹِو۔\n37.\\tتمہِ پتہ گٔیہِ سۅ اندر تہ پیوٚو تٔمۍ سٕندِس قدمن پیٹھ، تہٕ گٔیہِ پنُن نیچو تُلِتھ نٮ۪بر۔\n38.\\tتہٕ الیشع آو دُبارٕ گلگلس کُن: تہٕ زمینس مَنٛز ٲس کمی ۔ تہٕ پیغمبرن ہٕندِ نیچو ٲسۍ أمِس برونہہ کنہِ بِہتھ تہٕ تٔمۍ ووٚن پننِس خادمس زِ بٔڈِس بانس پیٹھ تھووُن تہٕ پیغمبرن ہٕندِس فرزندن ہٕندِ خٲطرٕ وُچھِو۔\n39.\\tتہٕ اَکھ دراو کھاہس منز جڑی بوٹی جمع کرنہٕ خٲطرٕ، تہٕ لوٚب اکھ جنگلی بیل، تہٕ تٔمِس کٔرِن جنگلی لولہٕ بٔرِتھ تہٕ آو تہٕ ژٔٹِتھ ژٔٹِتھ کٔرِن پوٹیج کِس بانس منز، تکیازِ تِمن ٲس نہٕ خبر۔\n40. تہٕ تِمو دِژ مردن کھٮ۪نہٕ خٲطرٕ۔ تہٕ یہ سپد ییلہ تم برتن کھیوان ٲسۍ، تمو کٔر کرٛٮ۪کھ تہٕ وونُن، اے خدایہ سٕندِس انسانس منز چُھ موت۔ تہٕ تِم ہیوٚک نہٕ کھٮ۪تھ۔\n41.\\tمگر تمۍ ووٚن، تیلہ انۍ کھٮ۪ن۔ تہٕ تٔمۍ ترٛٲو بانس منٛز۔ تہٕ تٔمۍ ووٚن، لُکن ہٕندِ خٲطرٕ تراوُن تاکہ تِم کھٮ۪ن۔ تہٕ برتن منٛز اوس نہٕ کانٛہہ نقصان۔ {نقصان: ہیب۔ بد چیز}\n42.\\tتہٕ اَکھ شخٕص آو بعلشلیشہٕ پیٹھ، تہٕ اوٚن خدایہ سٕندِس انسانس گۅڈنِکِس پھلُک روٹ، وُہ روٹ، تہٕ اَتھ کِس کُلِس مَنٛز پوٗرٕ کٔرِتھ۔ تہٕ تٔمۍ ووٚن، لُکن دِیُن تاکہ تِم کھٮ۪ن۔ {ہُسک...: یا، تٔمۍ سُند سکرپ، یا، لباس}\n43.\\tتہٕ تٔمۍ سٕندِس خادمَن ووٚن، کیا بہٕ کیا یہ ہتن نفرن برونہہ کنہِ تھاوُن؟ تٔمۍ ووٚن دُبارٕ، لُکن دِیُن یُتھ تِم کھٮ۪ن، تِکیازِ خداوند چُھ یِتھٕ پٲٹھۍ ونان زِ تِم گژھن کھٮ۪ن، تہٕ نیرن نیرن۔\n44.\\tتێلہِ تھوو تِمن برونہہ کنہِ، تہٕ تِمو کھیوٚو تہٕ دِژ خداوند سٕندِ کلامٕ مُطٲبق۔","1.\\tوُنہِ اوس نعمان، یُس شامُک بادشاہ سٕندِس لشکرُک کپتان، اوس پننِس آقا سٍتـ̡ اکھ بٔڈ شخٕص تہٕ عزت، تکیازِ تٔمِس سٍتـ̡ اوس خداوند شامس نجات دِژمُت، سُہ اوس بہادر تہِ اکھ طاقتور انسان، {مگر سُہ اوس کوڑھ ہُند۔ {سۭتۍ: ہیب۔ برٛونٛہہ} {عزت: یا، مہربانی: ہیب۔ تُلِتھ، یا، بُتھِس منز قبول} {نجات: یا، فتح}\n2.\\tتہٕ شامٕکۍ ٲسۍ کمپنیو سٍتـ̡ نٮ۪بر نیران، تہٕ ٲسٕکھ اِسرٲیلِچ سرزمینہٕ منزٕ اکھ لۄکٕٹ دٲر نِتھ نِمٕژ۔ تہٕ سۅ ٲس نعمان سنزِ زنانہِ ہُند پیاران۔ {انتظار...: ہیب۔ امہ برونہہ اوس}\n3.\\tتہٕ تٔمۍ ووٚن پننہِ مالکن زِ کاش خدایہ آسہ ہا تٔمِس پیغمبرس سٍتـ̡ یُس سامریاہس مَنٛز چُھہ! تکیازِ سُہ کرِ أمِس کوڑھ نِش صحتیاب ۔ {سۭتۍ: ہیب۔ برٛونٛہہ} {recover: Heb. جمع کٔرِو}\n4.\\tتہٕ {اَکہ} ژاو اژان تہٕ وونُن پننِس مالکَس تہٕ یِتھٕ پٲٹھۍ وونُن دٲرِ یُس اسرٲیلِچ سرزمینُک {چُھ}۔\n5. تہٕ شامٕکۍ بادشاہن ووٚن، گژھ گژھ، گژھ تہٕ بہٕ سوزٕ اسرائیلٕکِس بادشاہس اکھ چِٹھۍ۔ تہٕ سُہ دراو تہٕ پانس سٍتۍ نِن داہ ٹیلنٹ رۄپہٕ، تہٕ شیہ ساس سۄنہٕ تہٕ داہ بدلاوٕ۔ {with...: Heb. تٔمۍ سٕنٛدس اتھس منٛز}\n6.\\tتہٕ تٔمۍ دِژ یہِ چِٹھۍ اِسرٲیلِس نِش یِتھ، یێلہِ یہِ چِٹھہِ ژےٚ نِش واتہِ، وُچھِو مے سُہ نَمان پنُن نوکر ژے نِش سوزمُت، یُتھ ژٕ تٔمِس کوڑھ نِش نجات دِنہٕ۔\n7.\\tتہٕ سپُد ییلہ اسرائیلٕکۍ بادشاہن یہ چِٹھۍ پٔرۍ، تٔمۍ کٔر پَنٕنۍ پلو ژٔٹِتھ تہٕ وونُن، {کیا بہٕ چھُس} خدا، مارُن تہٕ زِندٕ دِنہٕ خٲطرٕ، زِ یہِ شخٕص چُھس میٲنِس نِش أکِس کوڑھ نِش بازیافت کرنہٕ خٲطرٕ سوزان۔ لہٰذا غور کرُن، بہٕ چھُس ژےٚ دُعا کران، تہٕ وُچھان زِ سُہ کِتھہ کٔنۍ چُھ میانہِ خلاف جھگڑٕ ژھاران۔\n8.\\tتہٕ یێلہِ یێلہِ خدایہِ سٕندِس انسانس الیشاع بوٗز زِ اسرٲیلٕکۍ بادشاہن چُھہ پَنُن پلو ژٔٹِمُت، تٔمۍ سُہ سوزُن بادشاہس نِش تہٕ وونُن زِ ژے کیازِ چُھکھ پَنٕنۍ پلو پھٔٹۍمٕتۍ۔ سُہ گژھہِ وۅنۍ میانہِ نِش یِن، تہٕ تس گژھہِ معلوم زِ اسرٲیلِس مَنٛز چُھ اکھ پیغمبر۔\n9.\\tتہٕ آو نعمان پنٕنۍ گُرِ تہٕ رَتھ ہٮ۪تھ، تہٕ ووت الیشا سٕندِس گرٕ کِس دروازس پیٹھ کھڑا۔\n10. تہٕ الیشاہن سوٗز أمِس نِش اکھ قاصد یُس ووٚنمُت، سَتھ لٹہِ گژھ اردنس مَنٛز واش کرُن، تہٕ تُہند ماز گژھہِ توے نِش دُبارٕ یِنہٕ، تہٕ ژٕ گژھہِ پاک روزُن۔\n11.\\tمگر نعمان گوٚو شرارت تہٕ ژاو تہٕ ووٚنُن، وُچھمُت سُہ یِہ یٔقیٖنی طور میانہِ نِش نِش نیرِ، تہٕ کھڑا گژھہِ تہٕ خداوند سٕندِس خدایہ سٕندِس ناوَس پکار، تہٕ تٔمۍ سٕندِس اتھس پیٹھ تھپھ کٔرِتھ کوڑھ بٔرِتھ۔ {میہ سونچ: ہیب۔ میہ ووٚن} {میہ سونچ...: یا، میہ ووٚن پانس سٍتۍ، سہ گژھہِ یقینا نیبر، وغیرہ: ہیب۔ میہ ووٚن} {strike: Heb. ہیوٚر تہٕ بۄن کٔرِو}\n12.\\tکیا ابانا تہٕ فرپار، دمشقک دریاو چھہِ نہ اسرائیلکۍ تمام آبو کھوتہ بہتر؟ بہٕ ہیکہٕ نہٕ یِمن منٛز چھلنہٕ تہٕ صاف روزُن؟ چنانچہ گوٚو سہ پھیُر تہٕ ژوٚل شرارتس منز۔ {ابانا: یا، امانہ}\n13.\\tتہٕ تٔمۍ سٕندِس نوکر آیہِ نِش تہٕ أمِس سٍتـ̡ کتھ کٔرِتھ وونُن، میانہِ بابا، اگر نبی صلی اللہ علیہ وآلہ وسلم تۅہہِ کانہہ بٔڈ کٲم کرنُک حکم دِیُت، کیا ژیہ ہا نہٕ یہِ کٔرِتھ؟ تیلہِ کوتاہ چھہ تیلہِ ییلہ سہ ژیہ واش کرُن تہ پاک روزُن۔\n14. پَتہٕ ووت سُہ بۄن تہٕ خدایہ سٕندِ انسان سٕندِ قولہٕ مُطٲبق گۆو سَتھ لٹہِ اردنس مَنٛز۔ تہٕ تٔمۍ سُند ماز آو لۄکٹِس شُرۍ سٕندِس مازس ہٕندۍ پٲٹھۍ، تہٕ سُہ گوٚو پاک۔\n15.\\tتہٕ سُہ آو خدایہ سٕندِس انسانس نِش واپس، سُہ تہٕ تٔمۍ سٕنز سٲری صحبت، تہٕ آو أمِس برونہہ کُن کھڑا تہٕ وۆنُن، وُچھ، وُنہِ چُھس بہٕ پتاہ زِ سارِنٕے زمینس مَنٛز چُھنہٕ کانہہ خدا، مگر اسرٲیلِس مَنٛز۔\n16. مگر تٔمۍ ووٚن، {یێلہِ} خداوند زندٕ چُھ، یێمِس برونہہ کنہِ بہٕ کھڑا چُھس، بہٕ میلہٕ نہٕ کانہہ تہِ۔ تہٕ تٔمۍ دِژ أمِس نِنہٕ خٲطرٕ زور۔ مگر تٔمۍ کوٚر انکار۔\n17.\\tتہٕ نعمانن ووٚن زِ تیلہِ گژھہِ نہٕ پننِس خادمس زٕ خچرن ہُند زٕ بوج۔ تِکیازِ تُہُند خادم کرِ نہٕ اَمہِ پتہٕ دِیہِ نہٕ دزنہٕ نِش نِش تہٕ باقین دیوتاہن خٲطرٕ قربانی دِنہٕ، بٔلکہِ خداوند سٕندِ خٲطرٕ۔\n18.\\tاَتھ چیزس مَنٛز چُھہ خداوند تُہٕندِس خادمس معاف، {یہ} ییلہ میون آقا رِمون سٕندِس گرس مَنٛز عبادت کرنہٕ خٲطرٕ گژھان چُھ، تہٕ سُہ چُھس میٲنس اتھس پیٹھ تھپھ کٔرِتھ، تہٕ بہٕ چُھس رِمون سٕندِس گرس مَنٛز نمان۔\n19. تہٕ تٔمۍ ووٚن أمِس سُہ کرُن۔ چنانچہ ژاو تس نِش رژھ کھنڈ دور۔ {تھوڑا ...: ہیب۔ زمینُک اکھ لۄکُٹ ٹُکر}\n20.\\tمگر خدایہ سٕندِس بندس الیشع سٕندِس خادمَس وۆن، وۆنُن زِ میانہِ آقا چُھس نعمانس یُس شامُک شُمار دِنہٕ آمُت چھُ، یُس نہٕ أمِس اَننہٕ آمُت چھُ، مگر، یُس خداوند زندٕ چُھ، بہٕ ژلہٕ أمِس پَتہٕ تہٕ نِش کینہہ نِنہٕ۔\n21.\\tتہ گحازی آو نعمانس پتہٕ پتہٕ۔ تہٕ ییلہ نعمانن وُچھ أمِس پَتہٕ پَتہٕ ژلان وُچھ، سُہ ووٚتھ رَتھٕ پٮ۪ٹھٕ أمِس مِلنہٕ خٲطرٕ، تہٕ وونُن، {چھَا} ٹھیٖک ٹھیٖک؟ {یہ...: ہیب۔ کیا امن چھا؟}\n22.\\tتہٕ تٔمۍ ووٚن، سورُے {چُھ} ٹھیٖک۔ میانہِ آقا چھہ میہ سوزمُت زِ وُنہِ تہِ آو کوہ افرائیم پیٹھہ پیغمبرن ہندین نیچوین ہندۍ زٕ جوان میہ نِش۔\n23.\\tتہٕ نعمانن ووٚن زِ مطمئن روزُن، زٕ ٹیلنٹ رٔٹِو۔ تہٕ تٔمۍ کٔر أمِس زور دِتھ، تہٕ رۄپہٕ ہٕندۍ زٕ ٹیلنٹ لٲگِتھ دۄن ٹھیلن منٛز، تہٕ تھووُن پننٮ۪ن دۄن نوکرَن پیٹھ۔ تہٕ تِم چھِ أمِس برونہہ کنہِ نِش دِوان۔\n24.\\tتہٕ ییلہ سُہ مینارس پیٹھ ووت، تٔمۍ نِش تِمن ہٕندِس اتھہٕ نِش تہٕ دِژُن گرس مَنٛز، تہٕ تٔمۍ دِژ نفرن یلہٕ تہٕ تِم دِژٕ۔ {ٹاور: یا، خفیہ جاے}\n25.\\tمگر سُہ گوٚو اندر تہٕ کھڑا پننِس آقا برونہہ کُن۔ تہٕ الیشاہن ووٚن أمِس زِ ژیہ کتہِ کتہِ چُھہ آمُت، گیہازی؟ تہٕ تٔمۍ ووٚن، تُہند خادم ووت نہٕ کُنہِ تہِ۔ {کتہِ نہ: ہیب۔ یور تہٕ تتہٕ نہٕ}\n26.\\tتہٕ تٔمۍ ووٚن أمِس زِ میون دِل گۆو نہٕ ژے سٍتۍ، ییلہ یہِ نفر ژےٚ سمکھنہٕ خٲطرٕ پننہِ رتھٕ پیٹھٕ پھیُر؟ {کیا یہٕ چُھ}پونسہٕ وصول کرنُک وق، تہٕ پلو، تہٕ زیتون، تہٕ انگور، تہٕ کٹہٕ، تہٕ دان، تہٕ نوکر تہٕ نوکر حٲصل کرنُک؟\n27.\\tتَمہِ کِنۍ گژھہِ نعمان سُند کوڑھ ژٔٹِتھ تہٕ تُہٕندِس بُلِس سٍتـ̡ ہمیشہٕ خٲطرٕ۔ تہٕ سُہ دراو پننہِ موجودگی منزٕ اکھ کوڑھ {یُتھ شینہٕ ہیوٗ سفید}۔","1. تہٕ پیغمبرن ہٕندِس نیچویو ووٚن الیشاہس زِ وُچھو وُن، سُہ جاے ییتہِ أسۍ ژے سٍتـ̡ روزان چُھ، سُہ چُھ سانہِ خٲطرٕ واریاہ سخت۔\n2. أسۍ گژھو ژے اردنس کُن، تہٕ تتہِ نِو پرٮ۪تھ أکِس انسانس اکھ بیمہٕ، تہٕ اسہِ بناوو تتہِ اکھ جاے، ییتہِ أسۍ روزِو۔ تہٕ تٔمۍ دیُت جواب، گژھ یےٚ۔\n3. تہٕ أکۍ ووٚن، مطمئن گژھُن، بہٕ چھُس ژےٚ دُعا کٔرِتھ، تہٕ گژھ پننین خادمَن سٍتـ̡ ۔ تہٕ تٔمۍ دیُت جواب، بہٕ نیرٕ بہٕ۔\n4. تہٕ سُہ گوٚو تمن سۭتۍ۔ تہٕ ییلہ تم اردن آیہ، تمو ژٹۍ لٔکر۔\n5.\\tمگر ییلہ اکھ شہتیر لوٚگ، کلہٕ کلہٕ پیوٚو آبس منز، تہٕ تٔمۍ ووٚن کٔرِتھ وۆنُن، ہاے مالک! تکیازِ یہ اوس مستعار نِنہٕ آمُت۔ {کلہاڑی ہیڈ: ہیب۔ ششتٕر}\n6.\\tتہٕ خدایہِ سٕندِ انسانس ووٚن، یہِ کتہِ پیوٚو؟ تہٕ تٔمۍ ہٲو أمس جاے ہٲو۔ تہٕ تٔمۍ ژٔٹۍ اکھ لور، تہٕ ترٛٲوٕن تتہِ منٛز۔ تہٕ ششتٕر اوس ژھانٛٹھ وایان۔\n7.\\tتَمہِ کِنۍ ووٚن تٔمِس نِش نِنہٕ۔ تہٕ تٔمۍ تروو پنُن اتھہٕ تہٕ رٔٹ۔\n8.\\tشامُک بادشاہ کٔر اسرٲیلِس سٍتـ̡ جنگ تہٕ پننین خادمَن سٍتـ̡ مشورٕ کٔرِتھ وونُن زِ اَتھ جایہِ آسہِ میون خٲمہٕ۔ {کیمپ: یا، انکیمپنگ}\n9.\\tتہٕ خدایہِ سٕندِس انسانس سوزُن اسرٲیلِکِس بادشاہس نِش یہِ وَنُن زِ تُہۍ گژھِہ نہٕ یِتھٕ جایہِ نیرِتھ۔ تتہِ چھِ شامٕکۍ بۄن آمٕتۍ۔\n10. تہٕ اسرائیلٕکۍ بادشاہن سوٗز تتھ جایہِ یُس خدایہِ سٕندِ انسانن أمِس ووٚنمُت تہٕ تمِس خبردار کورمُت، تہٕ تتہِ بچٲوُن پان اکہِ لٹہِ تہٕ دۄیہِ لٹہِ۔\n11.\\tلہذا گۆو شامک بادشاہ سُند دِل امہِ کتھہِ مۅکھہ پریشان۔ تہٕ تٔمۍ بُلوو پننین خادمَن تہٕ تِمن ووٚنُن، کیا تُہۍ ہٲوِو نہٕ مےٚ ہٲوِتھ زِ اسہِ منزٕ کُس چُھ اسرٲیلِکِس بادشاہس خٲطرٕ؟\n12.\\tتہٕ تٔمۍ سٕندِس أکۍ خادمَن ووٚن نہٕ، اے بادشاہ، مگر الیشع، یُس پیغمبر یُس اسرٲیلِس مَنٛز چُھ، چُھ تِم لفظ وَنان۔ {نہٕ: ہیب۔ نہ}\n13.\\tتہٕ ووٚن زِ گژھ تہٕ جاسوسی کٔرِتھ یُس سُہ {چُھ}، تاکہ بہٕ سوزِتھ تہٕ أنِتھ۔ تہٕ أمِس وَننہٕ آمُت زِ وُچھِو سُہ چھُ دوتھنس مَنٛز۔\n14.\\tلہذا سوٗزۍ تٔمۍ تتہِ گُرۍ، رتھ، تہٕ اکھ بٔڈ لشکر، تہٕ تِم آیہِ رٲژ تہٕ شہرس اندۍ پکھۍ گٔیہِ۔ {عظیم: ہیب۔ گوٚب}\n15.\\tتہٕ ییلہ خدایہ سُند خادم سُلہٕ سُلہٕ وُتھ، تہٕ درٛاو درٛاو، وُچھ اَکھ لشکر گُرِ تہٕ رتھَو سٍتـ̡ شہرس گھیرِ۔ تہٕ تٔمۍ سٕندِس خادمن ووٚن أمِس ، ہاے ، میانہِ مالک! أسۍ کِتھٕ کٔنۍ کٔرِو؟ {خادم: یا، وزیر}\n16.\\tتہٕ تٔمۍ دِژ جواب، خوفہٕ نہٕ گژھُن، تکیازِ یِم اسہِ سٍتـ̡ چِھہ تِمن سٍتـ̡ زیادٕ آسان۔\n17. تہٕ الیشاہن کٔر دُعا تہٕ وونُن، خداوند، بہٕ چُھس ژے دُعا کٔرِتھ، تٔمۍ سٕنزِ أچھ کھولٕن، یُتھ سُہ وُچھِ۔ تہٕ خداوند کٔر جوان سٕنزِ أچھ کھول۔ تہٕ وُچھ تہٕ وُچھ، پہاڑ اوس الیشعس اندۍ اندۍ گُرٮ۪و تہٕ نارٕکۍ رتھ بٔرِتھ۔\n18.\\tتہٕ ییلہ تِم أمِس نِش وٲتۍ، الیشاہن کٔر خداوند نِش دُعا تہٕ وونُن، یِمن لُکن ہُند دُعا کرُن، بہٕ چُھس ژےٚ انہِ سٍتـ̡ دُعا کران۔ تہٕ یِمو دِژ الیشع سٕندِ کلامَس مُطٲبِق یِمن انہِ گٹہِ سٍتـ̡ دِنہٕ۔\n19.\\tتہٕ الیشاع ووٚن تِمن زِ یہِ چُھنہٕ وَتھ تہٕ نہٕ چُھہ یہِ شہر: میانہِ پٲٹھۍ، تہٕ بہٕ اَنِہ ژے تٔمِس شخصس نِش یُس تُہۍ ژھاران چھِو۔ مگر سُہ نیو تِم سامریاہس کُن۔ {فالو...: ہیب۔ یِمو پَتہٕ یِنہٕ پتہٕ}\n20. تہٕ ییلہ تم سامریاہس منز وٲتۍ، الیشاع ووٚن زِ خداوند، یِمن انسانن ہٕنزِ أچھ کھولٕن، یُتھ تِم وُچھن۔ تہٕ خداوند کٔر تِہٕنزِ أچھ تہٕ تِمو وُچھ؛ تہٕ وُچھِو، {تِم} ٲسۍ سامریاہس منز۔\n21.\\tتہٕ اسرائیلٕکۍ بادشاہن ووٚن الیشاہس ییلہ تِم وُچھ، میانہِ بابا، کیا بہٕ کرٕ تمن مارٕ؟ کیا بہٕ کٔرٕ تمن مارٕ؟\n22. تہٕ تٔمۍ دیُت جواب، تہٕ تٔمۍ دِیُت نہٕ تِمن ہُند وار یِمن ژے پننہِ تلوار تہٕ کمانہٕ سٍتۍ رٔٹِتھ رٔٹۍمٕتۍ؟ تِمن برونہہ کنہِ تھٲوِو روٹی تہٕ آب تاکہ تِم کھٮ۪ن تہٕ چیٚنہٕ تہٕ پننِس مٲلکَس نِش گژھن۔\n23.\\tتہٕ تٔمۍ کٔر تِمن ہٕندِ خٲطرٕ واریاہ رزق تیار، تہٕ ییلہ تِمو کھٮ۪تھ تہٕ شراب، تٔمۍ سوٗزۍ تِم تہٕ تِم گٔیہِ پننِس مٲلکَس نِش۔ چنانچہ شامکۍ جمٲژ آیہ نہٕ اسرٲیلِچ سرزمینس مَنٛز۔\n24.\\tتہٕ امہ پتہ سپد یہ زِ شامک بادشاہ بن ہاداد پنُن لشکر جمع کٔرِتھ ووت سامریاہس محاصرٕ۔\n25.\\tتہٕ سامریاہس مَنٛز آو سٮ۪ٹھاہ قحط، تہٕ وُچھ تِمو اَتھ گیرٕ کٔرِتھ، یوٚت تام أکِس گَردٕ سُند کلہٕ ژۅن رۄپہٕ رۄپہٕ تہٕ کۅتر سٕندِ گُرُک ژوٗرِم حصہٕ پانژھ رۄپہٕ رۄپہٕ کٕننہٕ آو۔\n26.\\tییلہ اسرائیلُک بادشاہ دیوارس پیٹھ نیران اوس، اَکھ زنانہٕ وون أمِس نِش کٔرِتھ وونُن، اے بادشاہ، مدد۔\n27. تہٕ ووٚن یێلہِ نہٕ خداوند تۅہہِ مدد کرِ، بہٕ کتہِ کَرٕ ژےٚ مدد؟ بارن فلور نیبر، یا شراب پریسہٕ نیبر؟ {اگر...: یا، خداوند کرِ نہ توے بچاو}\n28. تہٕ بادشاہن ووٚن أمِس کیا چُھ؟ تہٕ تٔمۍ دیُت جواب، أمۍ زنانہِ ووٚن مےٚ پنُن نیچو دِیُن، یُتھ أسۍ از تہِ کھٮ۪وان تہٕ أسۍ پگہہ پنُن نیچو کھٮ۪وان۔\n29.\\tیێمہِ دۅہہ وۆن اسہِ پنُن نیچو تہٕ کھیوٚو سُہ تہٕ میہ ووٚن أمِس دۆیمہِ دۅہہ پنُن نیچو دِن، یُتھ أسۍ کھٮ۪وان تہٕ تٔمۍ کٔر پنُن نیچو ژوٗر۔ {اَمہِ پتہٕ: ہیب۔ باقی}\n30.\\tتہٕ ییلہ بادشاہن زنانہِ ہٕنز کتھ بوٗز، تٔمۍ کٔر پَنٕنۍ پَلو پھٔٹِتھ۔ تہٕ سُہ پوٚک دیوارس پیٹھ، تہٕ لوکو وُچھ، تہٕ وُچھ، {أمِس} اوس پننِس مازس پیٹھ بۄٹہٕ پلو لٲگتھ۔\n31. اَمہِ پتہٕ ووٚن خدایہِ تہٕ میانہِ سٍتـ̡ تہِ کرُن، یێلہِ اَز شَفعت سُند نیچو الیشع سُند کلہٕ یێلہِ أمِس سٍتـ̡ کھڑا آسہِ۔\n32.\\tمگر الیشع بیوٹھ پننِس گرس منز، تہٕ بٔڈۍ بِہتھ أمِس سٍتـ̡ ۔ تہٕ {بادشاہن} سوٗز أمِس برونہہ کُن اکھ نفر، مگر امہ برونہہ زِ رسول أمِس نِش یِنہٕ، تٔمۍ ووٚن زِٹھٮ۪ن زِٹھۍ، وُچھِو أکِس قاتل سٕندِ نیچِوِ کِتھہ کٔنۍ چھُ میون کلہٕ نِنہٕ خٲطرٕ سوزمُت۔ وچھ ییلہ قاصد یِیہ، دروازہ بند کٔرِتھ تھپھ کٔرِتھ تھپھ کٔرِتھ: {کیا چھُنہ} تس پتھ کُن آقا سٕندٮ۪ن قدمن ہٕنز آواز؟\n33.\\tتہٕ یێلہِ تِمن سٍتـ̡ کتھ کٔرِتھ، وُچھِتھ آو رسول أمِس نِش۔ میہ کیا پزِ وۅنۍ رب سُند انتظار کرُن؟","1. اَمہِ پَتہٕ ووٚن الیشاع زِ خداوند سُند کلام بوزو۔ یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ پگہہ امہِ وقتہٕ ییہ سامریہ کِس دروازس مَنٛز اکھ شیکل تہٕ شیکل بدلہٕ زٕ پیمانہٕ بارٕے کٕننہٕ۔\n2.\\tتێلہِ یێمہِ سٕندِس اتھس پیٹھ بادشاہ دِژ خدایہ سٕندِس انسانس جواب تہٕ وونُن، وُچھِو، {یێلہ} خداوند اسمانس مَنٛز دارِ بناوِ، کیا یہِ چیز ٲسِتھ؟ تہٕ تٔمۍ ووٚن، وُچھ، ژے وُچھِو یہِ پننہِ أچھو سٍتـ̡ وُچھان، مگر یہِ گژھ نہٕ کھٮ۪نہٕ۔ {اکھ لارڈ...: ہیب۔ اکھ لارڈ یُس بادشاہ سُند اوس، یُس تٔمۍ سٕندِس اتھس پیٹھ ٹٲٹھ اوس}\n3.\\tتہٕ دروازس منز اژنہٕ وِزِ ٲسۍ ژور کوڑھ نفر: تہٕ تِمو ووٚن اکھ أکِس زِ أسۍ کیازِ بِہِتھ یُس نہ أسۍ مران چھُ۔\n4. اگر أسۍ ونو زِ أسۍ شہرس مَنٛز اژِو، تیلہِ چُھ قحط شہرس مَنٛز، تہٕ أسۍ مرو تتہِ: تہٕ اگر أسۍ یتہِ بِہتھ روزو، أسۍ تہِ مران چھِ۔ تَمہِ کِنۍ یِمو اسہِ شامٕکۍ لشکرس نِش: اگر تِم اسہِ زِندٕ بچٲوِن، أسۍ زِندٕ روزِ۔ تہٕ اگر تِم اسہِ مارن تیلہِ گژھہِ أسۍ مرُن۔\n5.\\tتہٕ تِم ووٚتھ شامٕکِس خٲمس مَنٛز گژنہٕ خٲطرٕ، تہٕ ییلہ تِم شام کِس خٲمہٕ کِس اندِس حصس منز وٲتِتھ، وُچھِتھ اوس نہٕ اَتہِ کانہہ انسان۔\n6.\\tکیازِ خداوند اوس شامِک لشکر رتھن ہُند شور تہٕ گُرٮ۪ن ہُند شور بوزنہٕ خٲطرٕ بنوومُت، تہٕ تِمو ووٚن اَکھ أکِس أکِس سٍتـ̡ ، لو، اسرٲیلٕکۍ بادشاہن چُھ اسہِ خٕلاف حِتِین ہٕندِ بادشاہ تہٕ مصرٕکۍ بادشاہ اسہِ پیٹھ یِنہٕ خٲطرٕ رٔٹمٕتۍ۔\n7. اَمہِ مۄکھٕ ژٔلِتھ ژٔلِتھ تہٕ ژٔلِتھ پَنٕنہِ خیمہ تہٕ گُرِ تہٕ گُرِ تہٕ خٲمہٕ تہٕ خٲمہٕ تہٕ ژٔلِتھ ژٔلِتھ پننہِ زِندٕ خٲطرٕ۔\n8.\\tییلہ یم کوڑھ کیمپ کس اندس حصس منز وٲتۍ، تم گٔیہ اکس خیمس منز، کھیوٚن تہ کھیوٚن تہ تتہِ رۅپہ، سون تہ پلو نِتھ ژٔلِتھ ژٔرۍ۔ تہٕ آو دُبارٕ تہٕ بیٚیِس خیمس منٛز ژاو تہٕ تتہِ نِتھ {تہِ} تہٕ گٔیہِ ژوٗرِ تہٕ ژوٗر۔\n9.\\tاَمہ پتہٕ ووٚن تِمو اَکھ أکِس أکِس سٍتـ̡، أسـ̡ چُھہ نہٕ رُکُن: یہِ دۅہ چُھہ خوشخبری ہُند دۅہ، تہٕ أسـ̡ چُھہ پنُن خاموش روزان: اگر أسۍ صُبحٕچ گاشس تام روزو تیلہِ گژھہِ اسہِ کانہہ مصیبت واتہِ: تێلہِ یێلہِ یێلہِ أسۍ گژھِو بادشاہ سٕندِس گرس ؤنِتھ۔ {کینٛہہ...: ہیب۔ اسہِ میلہِ سزا}\n10.\\tتہٕ تِمو آیہِ تہٕ شہرٕکِس قُلِس بُلٲوِتھ تہٕ تِمو ووٚنُن زِ أسۍ وٲتِتھ شامٕکۍ خٲمس منز، تہٕ وُچھِتھ اوس نہٕ اَتہِ کانہہ نَفر، نہ اِنسان سٕنز آواز، مگر گُرِ بٔنِتھ تہٕ گَرٕ بٔنِتھ تہٕ خیمہ یِتھے پٲٹھۍ ٲسۍ۔\n11.\\tتہٕ تٔمۍ بُلٲوِتھ قُلۍ۔ تہٕ تِمو ووٚن بادشاہ سٕندِس گرس منز۔\n12.\\tتہٕ بادشاہ ووت رٲژ تہٕ ووٚنُن پننین خدمتگارن زِ بہٕ ہاوٕ وۅنۍ ژےٚ ہٲوِتھ شامیو کیا کوٚر اسہِ سٍتۍ۔ تِم چھِ زانان زِ أسۍ چھِ فاقہٕ کٔرِتھ۔ تَمہِ کِنۍ چھِ تِم خٲمہٕ منٛزٕ نٮ۪بر کھہَس منٛز ژوٗرِ روزنہٕ خٲطرٕ، یہِ ونان زِ ییٚلہِ تِم شہرٕ منٛزٕ نٮ۪بر نیرن، أسۍ رٔٹِو تِم زِنٛدٕ رٔٹِتھ شہرس منٛز۔\n13.\\tتہٕ تٔمۍ سٕندِس أکۍ خادمَن دِیُت جواب تہٕ وونُن، بہٕ چُھس ژےٚ دُعا کٔرِتھ، یِم شہرس مَنٛز باقٕے گُرِ باقٕے چھِ، (وُچھِو، تِم {چھِ} یِتھٕ پٲٹھۍ، یِم سارِنٕے اسرٲیلِچ بٔڈِتھ باقٕے چھِ: ) تہٕ سوزو تہٕ وُچھو۔ {شہرس منز: ہیب۔ اتھ منز}\n14.\\tتِمو رٔٹۍ زٕ رتھٕکۍ گُرۍ۔ تہٕ بادشاہن سوٗز شامٕکۍ لشکرس پتہٕ، وونُن گژھ تہٕ وُچھ۔\n15.\\tتہٕ تِم گٔیہِ تِمن پَتہٕ اردن کُن، تہٕ وَتہٕ ٲس سٲرۍسٕے وتہِ پلوو تہٕ بانو سٍتـ̡ بٔرِتھ، یِم شامیو جلدی کٔرِتھ ترٛٲومٕتۍ ٲسۍ۔ تہٕ قاصد آو واپس، تہٕ ووٚن بادشاہس ۔\n16.\\tتہٕ لُکھ درٛاو نیٚبر، تہٕ کٔرٕکھ شامٕکۍ خیمہ بِگاڑ۔ چنانچہ خداوند سٕندِ کلامٕ مطٲبق آو اکھ شیکل خٲطرٕ اکھ بارٕ آٹا {کٕننہٕ}، تہٕ زٕ پیمانہٕ آو شیکل بدلہٕ زٕ پیمانہٕ۔\n17.\\tتہٕ بادشاہن کوٚر سُہ مٲلک مقرر یٔمۍ سٕندِس اتھس پیٹھ سُہ دروازُک ذمہ دار رٹنہٕ خٲطرٕ اوس، تہٕ لوکھ لٔج تس دروازس پیٹھ لٔگِتھ تہٕ سُہ موٗد، یِتھ کٔنۍ خدایہ سُند انسان اوس ووٚنمُت، یُس بادشاہ أمِس نِش بۄن وُن اوس کتھ کٔرمٕژ۔\n18.\\tتہٕ سپُد یِتھٕ پٲٹھۍ خدایہِ سٕندِس انسانس بادشاہس سٍتـ̡ کتھ کٔرِتھ وونُن زِ أکِس شیکل بدلہٕ زٕ پیمانہٕ جوہٕ تہٕ أکِس شیکل بدلہٕ اکھ عمدہ آٹُک پیمانہٕ، پَتہٕ گژھہِ سامریہ کِس دروازس مَنٛز۔\n19.\\tتہٕ تٔمۍ خداوند دِیُت خدایہ سٕندِس انسانس جواب تہٕ وونُن، وُچھِو، {یێلہِ} خداوند آسمانس مَنٛز دٲر بناوِ، تیلہِ ہیکہِ یِژھ چیز ٲسِتھ؟ تہٕ تٔمۍ ووٚن، وچھ ژے یہ پننہ أچھو سۭتۍ وچھان، مگر یہ گژھ نہٕ کھٮ۪ن۔\n20. تہٕ یِتھٕ پٲٹھۍ آو أمِس نِش تہٕ لُکھ گٔیہِ دروازس منز أمِس پٲٹھۍ، تہٕ سُہ موٗد۔","1.\\tاَمہِ پتہٕ ووٚن الیشاہن زنانہِ سٍتۍ، یٔمۍ سُند نیچو أمِس زِندٕ دِنہٕ آمُت اوس، وَنُن زِ وۅتھٕ وُتھ، تہٕ گژھ تہٕ پنُن گرٕ تہٕ ییتہِ تہِ روزِ، یێلہِ تہِ روزُن، تکیازِ خداوند چُھ قحطُک بُلوومُت۔ تہٕ یہ تہِ گژھہِ زمینس پیٹھ ستن ؤرین پیٹھ۔\n2.\\tتہٕ زنانہٕ ووٚتھ، تہٕ خدایہ سٕندِس مردٕ سٕندِس کُننہٕ مُطٲبِق گٔیہِ تہٕ سُہ گٔیہِ پننِس گرس سٍتـ̡ تہٕ سَتن ؤرین فلسطینن ہٕندِس ملکس مَنٛز روزنہٕ۔\n3. تہٕ سَتن ؤرین ہٕندِس ٲخرس پیٹھ سپد یہِ زِ زنانہٕ گٔیہِ فلسطینن ہٕندِ سرزمینہٕ منزٕ واپس۔ تہٕ سُہ گٔیہِ بادشاہس نِش پننہِ گرٕ تہٕ پننہِ زمینہٕ خٲطرٕ فریاد کرنہٕ خٲطرٕ۔\n4.\\tتہٕ بادشاہن کٔر خدایہ سٕندِس خادمَس گیہازی سٍتـ̡ کتھ تہٕ وونُن زِ بہٕ چُھس ژے دُعا کٔرِتھ، تِم سٲری بٔڈ کامہٕ یِم الیشاہن کٔرۍ۔\n5. تہٕ سپُد یہِ سپُد، یێلہِ سُہ بادشاہس ونان اوس زِ تٔمۍ کِتھہ کٔنۍ اوس اکھ مردہ لاش زندٕ کٔرمٕژ، زِ وُچھِتھ ٲس زنانہٕ، یٔمۍ سُند نیچو أمِس زندٕ کورمُت، کٔر بادشاہس پننہِ گرٕ تہٕ زمینہٕ خٲطرٕ وُنُن۔ تہٕ گیہازی ووٚن، اے بادشاہ، یہِ چھُ زنانہٕ تہٕ یہِ چھُ أمۍ سُنٛد نیٚچُو، یُس الیشاہن زندٕ کوٚر۔\n6.\\tتہٕ ییلہ بادشاہن زنانہِ پرژھ، تٔمۍ ووٚن أمِس ۔ چنانچہ بادشاہن کوٚر أمِس خٲطرٕ اکھ خاص افسر مقرر، یہِ وونُن زِ تمہِ دۅہہ پیٹھٕ یُس أمِس زمینہٕ نیرِ، تہٕ کھہٕکۍ سٲری مٮ۪وٕ دِیُن بحال کٔرِتھ۔ {افسر: یا، خواجہ سرا}\n7. تہٕ الیشع آو دمشق۔ تہٕ شامُک بادشاہ بن حداد اوس بیمار۔ تہٕ أمِس آو وننہٕ، خدایہِ سُند انسان آو یور آمُت۔\n8.\\tتہٕ بادشاہن ووٚن حزایلس زِ پانس اتھس منز رٔٹِتھ رٔٹِتھ گژھ خدایہ سٕندِس انسانس سمکھُن، تہٕ پرژھہٕ رٔسِس سٍتـ̡ خدایہ سٕندِس سٍتـ̡ پرژھہٕ تہٕ وونُن زِ بہٕ گژھا یێمہِ بیمارِ نِش ٹھیٖک گٔژھِتھ؟\n9.\\tتہ ہزایل گۆو أمس سمکھنہِ تہ پانس سٍتۍ نِتھ دمشقُک پرٮ۪تھ کانہہ اصل چیز تہٕ ژتٲجی اونٹٮ۪ن ہُند بوجھ، تہٕ آو أمِس برونہہ کُن کھڑا تہٕ وونُن، تُہند نیچو شامُک بادشاہ بن ہداد چُھس مے ژے نِش سوزمُت تہٕ وونُن زِ بہٕ گژھا یہ بیمارِ ٹھیٖک؟ {with...: Heb. تٔمۍ سٕنٛدس اتھس منٛز}\n10.\\tتہٕ الیشاہن ووٚن أمِس گژھِ، وَنُن زِ تُہہِ گژھِہ یٔقیٖنی طور صحت یاب گژھُن، یێلہِ تہِ چُھہ خداوند مےٚ ہٲومُت زِ سُہ گژھہِ یٔقیٖنی طور مَرُن۔\n11.\\tتہٕ تٔمۍ کٔر پنُن بُتھ ٹھہراونہٕ، یوٚت تام أمِس شرم گوو، تہٕ خدایہ سُند انسان رووُن۔ {سٹیڈفاسٹلی: ہیب۔ تہٕ سیٹ کٔرِو}\n12.\\tتہٕ حزائیل ووٚن میانہِ آقا کیازِ چُھ روُن؟ تہٕ تٔمۍ دیُت جواب، تکیازِ بہٕ چُھس پتاہ زِ ژے کٔرِکھ بنی اسرٲیلس سٍتـ̡ یُس بُرکار کٔرِو، تِہٕندِس قلعس دِیُکھ تہٕ تِہٕندِس جوان ژٔٹِھکھ تلوار سٍتـ̡ تہٕ تِہٕنزِ زنانہٕ ژٔٹِتھ ژٔٹِھکھ تہٕ تِہٕنزِ زنانہٕ ژٔٹِتھ ژٔٹِھکھ ۔\n13.\\tتہٕ حزعلن ووٚن، مگر کیا چُھہ تُہند خادم ہوُن، یُس یہِ بٔڈ کٲم کرُن؟ تہٕ الیشاہن دیُت جواب، خداوند چُھ مے ہٲومُت زِ ژٕ گژھ شامُک بادشاہ۔\n14. تہٕ سُہ دراو الیشع نِش تہٕ آو پننِس مٲلکَس نِش۔ کٔمۍ ووٚن أمِس زِ الیشاہن کیا ووٚن ژےٚ؟ تہٕ تٔمۍ دیُت جواب، تٔمۍ ووٚن مے {زِ} ژٕ پزِ پزِ صحت یاب گژھُن۔\n15.\\tتہٕ پَگہہ گۆو یہِ زِ تٔمۍ تُل اکھ موٚٹ پلو تہٕ آبس مَنٛز ڈبٲوِتھ پھیُرُن تہٕ پھیُرُن بُتھِس پیٹھ، تہٕ سُہ موٗد تہٕ حزایل کٔر أمِس بدلہٕ بادشاہ۔\n16.\\tتہٕ پوٗنٛژمہِ ؤریس مَنٛز، یُس اسرٲیلُک بادشاہ اہاب سُند نیچو یہوشافاط، یہوداہ کِس بادشاہ یہورام سُند نیچو یہورام کٔر حکومت۔ {شروع...: ہیب۔ راج کٔر}\n17. سُہ اوس ترٕہ تہٕ زٕ وُہُر وٲنسہِ ییلہ تٔمۍ بادشاہی شروع کٔر۔ تہٕ تٔمۍ کٔر یروشلمس منٛز ٲٹھن ؤرین حکومت۔\n18.\\tتہٕ سُہ پوٚک اسرٲیلِکۍ بادشاہن ہٕنزِ وتہِ پٲٹھۍ، یِتھے پٲٹھۍ اوس احاب سٕندِس گرس سٍتـ̡ تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز بدکار ۔\n19. توتہِ کرِ نہٕ خداوند یہوداہ پننِس خادم سٕندِ خٲطرٕ تباہ کٔرِتھ، یِتھ کٔنۍ تٔمۍ أمِس وعدٕ کورمُت زِ سُہ دِیہِ أمِس ہمیشہٕ گاش دِنہٕ۔ {گاش: ہیب۔ موم بتی، یا، شمع}\n20. پننِس دۅہَس مَنٛز کٔر ایڈومَن یہوداہ سٕندِس اتھہٕ تل بغاوت تہٕ بنووُن پانس پیٹھ بادشاہ۔\n21.\\tیَتھ ووت جورم زیٖرس نِش تہٕ أمِس سٍتـ̡ سارِنٕے رتھ، تہٕ سُہ ووت رٲژ وُتھ، تہٕ لُکھ ژٔلِتھ اَدومی یِم أمِس اندۍ پٔکھۍ ٲسۍ، تہٕ لُکھ ژٔلِتھ پننین خیمن منز۔\n22. توتہِ کٔر ادوم از تام یہوداہ سٕندِس اتھہٕ تل بغاوت ۔ پتہٕ کٔر لبناہن امی وقتہٕ بغاوت۔\n23.\\tتہٕ یُس باقی یُس یہوداہ کین بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمُت چھُ؟\n24.\\tتہٕ یورام گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ آو پننین مٲلن سٍتـ̡ داؤد شہرس مَنٛز دفن کرنہٕ۔ {احزیہ: یتھ عزریاہ تہٕ یہوہاز تہِ ونان چھِ}\n25.\\tبٔہمہِ ؤریس مَنٛز آو یہوداہ کِس بادشاہ یہورام سٕندِس نیچوِس اَحزیاہ سٕندِس نیچو یُس یہوداہ کِس بادشاہ یہورام سٕندِس نیچوِس حزیاہ سٕندِس بادشاہس سٍتـ̡ حکومت کرُن شروع گوو۔\n26.\\tزٕ وُہُن وُہُر اوس احزیاہ ییلہ تٔمِس بادشاہی شروع گٔیہ۔ تہٕ تٔمۍ کٔر یروشلمس مَنٛز أکِس ؤریس پیٹھ حکومت۔ تہٕ تٔمۍ سٕنٛزِ ماجہِ ہُنٛد ناو اوس اتھلیاہ، یۄس اسرٲیلِک بادشاہ عمری سٕنٛز کوٗر ٲس۔ {کور: یا، پوت}\n27.\\tتہٕ سُہ پوٚک اَحاب سٕندِس گرس مَنٛز تہٕ کٔرٕن خداوند سٕندِس نظرس مَنٛز بُرٕ کٔرِتھ، یِتھ کٔنۍ زِ سُہ اوس اہاب سٕندِس گرُک زامتُر۔\n28.\\tتہٕ سُہ گۆو احاب سٕندِس نیچوِس جورامس سٍتـ̡ شامٕکِس بادشاہ حزائیل سٍتـ̡ راموتگلعادس مَنٛز جنگس مَنٛز۔ تہٕ شامی کٔر جورام زخمی۔\n29.\\tتہٕ بادشاہ جورم گۆو یزریلَس مَنٛز تِم زخم ٹھیک گژھنہٕ خٲطرٕ واپس یِم شامٕکۍ باشندو أمِس راماہس مَنٛز دِژمٕتۍ ٲسۍ، ییٚلہِ تٔمۍ شام کِس بادشاہ حزائلس خلاف جنگ لوٚڑ۔ تہٕ یہوداہ کِس بادشاہ یہورام سُند نیچو آحزیاہ گۆو یِزریلس مَنٛز اخاب سُند نیچو یورامس وچھنہٕ خٲطرٕ، کیازِ سُہ اوس بیمار۔ {کُس...: ہیب۔ یَتھ سٍتـ̡ شامٕکۍ لٔگۍ زخمی} {رامہ: وَننہٕ آمُت راموت} {بیمار: ہیب۔ زخمی}","1. تہٕ الیشع پیغمبرن بُلوو پیغمبرن ہٕندِس أکِس شُرِس تہٕ وونُن زِ پَنٕنۍ کمر رٔٹِتھ تہٕ تیٖلُک یہ ڈبہٕ رٔٹِتھ رٔٹِتھ رموتھ گیلاد کُن گژھُن:\n2. تہٕ ییلہ تُہۍ تتہِ وٲتِو، نِمشی سُند نیچو یہوشافت سُند نیچو یہوُ، تہٕ اژُن تہٕ نِیُن أمِس پننین باین منزٕ تھوٚد تہٕ نِیُن أنٛدرِمِس کمرس مَنٛز۔ {اندرم...: ہیب۔ چیمبرس منز چیمبر}\n3. تیلُک ڈبہٕ رٔٹِتھ تٔمۍ سٕندِس کلس پیٹھ تراوُن تہٕ ونُن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ مے چُھہ ژے اسرٲیلِس پیٹھ بادشاہ مسح کورمُت۔ پتہٕ کھولِو دروازٕ تہٕ ژٔلِتھ ژٔلِتھ تہٕ ژٔلِتھ نہٕ پٔرِتھ۔\n4.\\tیێمہِ سٍتـ̡ گۆو نوجوان، یێمہِ سٍتـ̡ پیغمبر تہِ گۆو راموتگیلاد کُن۔\n5. تہٕ ییلہ سُہ آو ، وُچھِتھ میزبانہٕ سٕندِ کپتان بِہِتھ ۔ تہٕ تٔمۍ ووٚن، اے کپتان۔ تہٕ یہوَن ووٚن، اسہِ سارِنٕے منٛزٕ کُس کُس؟ تہٕ تٔمۍ ووٚن، اے کپتان۔\n6.\\tتہٕ سُہ ووٚتھ تہٕ گٔیہِ گرس منز۔ تہٕ تٔمۍ ترووُن تیٖل پننِس کلس پیٹھ، تہٕ وونُن تٔمِس یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند خدا، مے چُھ ژے خداوند کِس لوکن پیٹھ بادشاہ مقرر کورمُت، {حتیٰ کہ} اسرٲیلِس پیٹھ۔\n7. تہٕ ژے کرٕ پننِس آقا احاب سٕندِس گرس پیٹھ حملہٕ، یُتھ بہٕ پننین خادمَن، پیغمبرن ہٕندِس خونس تہٕ خداوند سٕندِس سارِنٕے خادمَن ہٕندِس خونُک انتقام ہُند انتقام ہُند نِنہٕ۔\n8.\\tیِکیازِ احابس سُند سورُے گرٕ گژھہِ ختم تہٕ بہٕ ژٹِتھ یُس دیوارس سٍتـ̡ رٔٹِتھ تہٕ یُس اسرٲیلِس مَنٛز بند آسہِ۔\n9. تہٕ بہٕ بناوٕ اہاب سُند گرٕ نیباطُک نیچو یربعام سٕندِس گرس ہیوٗ تہٕ احیجہ سُند نیچو بعشہٕ سُند گرٕ پٲٹھۍ:\n10.\\tتہٕ ہونۍ گژھن ییزبیل یزریل کِس حصس مَنٛز کھٮ۪ن، تہٕ {تتہِ} گژھِ نہٕ کانہہ تہِ دفن کرنہٕ خٲطرٕ۔ تہٕ تٔمۍ کھول دروازٕ، تہٕ ژوٚل۔\n11. تێمہِ پَتہٕ آو یہو پننِس آقا سٕندِس خادمن نِش تہٕ وۆنُن أمِس {چُھ} ٹھیٖک ٹھیٖک؟ یہِ پاگل کیازِ آو ژےٚ نِش؟ تہٕ تٔمۍ ووٚن تِمَن زِ تُہۍ چھِو أمِس نفرس تہٕ تٔمۍ سٕنٛز کتھ باتھ زانان۔\n12.\\tتہ تمو ووٚن {یہ} چھہ اپُز۔ وَن وَن اسہِ۔ تہٕ تٔمۍ ووٚن یِتھٕ پٲٹھۍ تہٕ یِتھٕ پٲٹھۍ وونُن میہ سٍتـ̡ تہٕ وونُن زِ خداوند چُھہ یِتھٕ پٲٹھۍ ونان زِ مے چُھہ ژے اسرٲیلِس پیٹھ بادشاہ مسح کورمُت۔\n13.\\tپَتہٕ تِمو جلدی کٔرِتھ تہٕ پرٮ۪تھ أکِس شخصس پَلَو نِتھ تھٲوِکھ ہیرن ہٕندِس تھزرس پیٹھ، تہٕ وَنُن زِ یہو چُھ بادشاہ۔ {چُھ بادشاہ: ہیب۔ Reigneth}\n14.\\tیێلہِ کٔر نِمشی سٕندِس نیچِوِ یہوشافت سٕندِس نیچِوِ یہوُن جورمس خلاف سٲزِش۔ (وۅنۍ اوس جورمن شامک بادشاہ حزائیل سٕندِ وجہ سٍتـ̡ راموتگیلیڈ تہٕ سارِنٕے اسرٲیلـ̡ تھوومُت۔\n15.\\tمگر بادشاہ جورم آو یِزریلَس مَنٛز تِم زخم ٹھیک کرنہٕ خٲطرٕ واپس یِم شامٕکۍ بادشاہ حزایلس سٍتۍ لوٚڑمٕتۍ ٲسۍ۔ تہٕ یہوَن ووٚن، یێلہِ تُہُند ذہن، {تیلہِ} گژھہِ نہٕ کانہہ تہِ نیرُن {تہٕ نہ} ژٔلِتھ یِزریلس مَنٛز {یہ} وننہٕ خٲطرٕ۔ {جورم: ہیب۔ یہورام مگر شُراہ شعرس منز نہٕ} {اوس دِتمُت: حب۔ smote} {let cane...: Heb. کانہہ فرار گژھن وغیرہ}\n16.\\tیێلہِ ژاو یہو أکِس رتھَس سٍتـ̡ سوار، تہٕ گۆو یزریلس کُن۔ تکیازِ جورم اوس تتہِ لوٚگمت۔ تہٕ یہوداہُک بادشاہ احزیاہ آو جورامس وچھنہٕ خٲطرٕ۔\n17.\\tتہٕ یزریلَس مَنٛز اوس اَکھ چوکیدار کھڑا تہٕ تٔمۍ وُچھُن یہو سٕندِس صحبتس ہٕنز جاسوسی تہٕ وونُن، بہٕ چُھس اَکھ صحبت۔ تہٕ جورمن ووٚن، اکھ گُرۍ سوار رٔٹِتھ تہٕ سوزُن تِمن سمکھنہٕ خٲطرٕ، تہٕ سُہ وَنُن، {یہِ چھا امن}؟\n18.\\tتێلہِ گۆو اَکھ گُرِ سٍتـ̡ أمِس سمکھنہٕ خٲطرٕ، تہٕ وونُن، یِتھٕ پٲٹھۍ چُھ بادشاہ وَنُن، {یہِ چھا امن}؟ تہٕ یہوَن ووٚن، ژےٚ کیا چُھ امنَس سٍتـ̡ وابستہٕ؟ پتھ کُن پھیرُن۔ تہٕ چوکیدارن ووٚن زِ رسول آو تِمن نِش، مگر سُہ آو نہٕ دُبارٕ۔\n19.\\tتمہ پتہ سوز دویم گُرس پیٹھ یُس تِمن نِش آو تہٕ وونُن، یِتھے پٲٹھۍ چُھ بادشاہ ونان، {کیا یہ} امن چھُ؟ تہٕ یہوَن دیُت جواب، ژےٚ کیا چُھہ امنَس سٍتـ̡ وابستہٕ؟ پتھ کُن پھیرُن۔\n20.\\tتہٕ چوکیدارن ووٚن زِ سُہ آو تِمن نِش تہِ، تہٕ دُبارٕ آو نہٕ: تہٕ چُھہ نِمشی سٕندِس نیچوِس یہو سٕندِس چلاونٕکۍ پٲٹھۍ۔ تکیازِ سُہ چُھ غصہٕ سان گٲڑۍ چلاوان۔ {ڈرایوِنگ: یا، مارچنگ} {غصہٕ سان: ہیب۔ پاگل پن منز}\n21.\\tتہٕ جورمن ووٚن تیار کرُن۔ تہٕ أمۍ سُنٛد رتھ آو تیار۔ تہٕ اسرائیلُک بادشاہ جورم تہٕ یہوداہُک بادشاہ احزیاہ دراو پرٮ۪تھ أکِس پننِس رتھ سٍتـ̡ تہٕ تِم گٔیہِ یہوہس خلاف تہٕ گٔیہِ تٔمِس نِبوتھ یزریلی کِس حصس مَنٛز۔ {تیار کرو: ہیب۔ Bind} {met: Heb. لٔب}\n22.\\tتہ ییلہ جورمن یہو وُچھ، تٔمۍ ووٚن، {یہِ} چھا امن یہو؟ تہٕ تٔمۍ دیُت جواب، کیا امن، یوتام نہٕ چانہِ ماجہ جیزبیل تہٕ تٔمۍ سٕنزِ جادوگری ہٕنز طوائف واریاہ آسہِ۔\n23.\\tتہٕ جورامن پھیُر اتھہٕ تہٕ ژوٚل تہٕ وونُن احزیاہ سٍتـ̡ غداری، اے احزیہ۔\n24.\\tتہٕ یہوُن پَنٕنہِ پوٗرٕ طاقتہٕ سٍتـ̡ کمان، تہٕ لوٚگُن یہورام پننِس نرِ منز، تہٕ تیر دراو تٔمۍ سٕندِس دِلس کُن، تہٕ سُہ پنہٕ نِس رتھس منز ڈوب۔ {ڈریو...: ہیب۔ پنن اتھہ بٔرِتھ کمان} {ڈوب: ہیب۔ جھکُن}\n25.\\tپتہٕ ووٚن {یہو} پننِس کپتانس بِدکرس تُل، تُلُن، {تہٕ} تراوُن نبوتھ یزرِلِیت کِس میدانس مَنٛز، تکیازِ یاد تھاوُن زِ ییلہ میہ تہٕ ژے پننِس مٲلِس احاب سٕندِس مٲلِس پتہٕ اِکہٕ وٹہٕ سوار گٔیہِ، خداوند تروو أمِس پیٹھ یہِ بوجھ۔\n26. یێلہِ چُھہ میہ راتھ نابوتُک خون تہٕ تٔمۍ سٕندِس نیچوین ہُند خوُن وُچھمُت، خداوند چُھ فرماوان۔ تہٕ بہٕ کَرٕ ژےٚ اَتھ پلاٹَس مَنٛز بدلہٕ، خداوند چُھ فرماوان۔ تێمہِ مۅکھہٕ رٔٹِو سُہ خداوند سٕندِ کلامٕ مُطٲبق {تہٕ} پٔرِتھ {زمینہٕ} مَنٛز تراوُن۔ {خون: ہیب۔ خون} {پلاٹ: یا، حصہٕ}\n27.\\tمگر ییلہ یہوداہُک بادشاہ احزیاہ وُچھ، سُہ ژوٚل باغ کِس وتہِ کِنۍ۔ تہٕ یہو ووٚن أمِس پَتہٕ پَتہٕ، تہٕ ووٚنُن أمِس تہِ رتھَس مَنٛز۔ {تہٕ تِمو کٔر یہِ} گُر تام گَژھنہٕ وِزِ، یُس {چھُ} اِبلام سُند۔ تہٕ سُہ ژوٚل میگیڈو کُن، تہٕ تتہِ موٗد۔\n28.\\tتہٕ تٔمۍ سٕندِس خادمَو نِیہِ سُہ أکِس رتھَس مَنٛز یروشلم تہٕ دفنُکھ پننِس مٲلِس سٍتـ̡ داؤد شہرس مَنٛز۔\n29.\\tتہٕ کٔہمہِ ؤریس مَنٛز کٔر یُہاب سٕندِس نیچِوِ اَحزیاہ یہوداہَس پیٹھ حکوٗمت کرنہٕ خٲطرٕ۔\n30. تہٕ ییلہ یہو یِزریلس نِش آو، یِزبیلن بوز یہِ۔ تہٕ تٔمۍ کٔر پنن بُتھ رنٛگ تہٕ تھوٚکُن کلہٕ تہٕ دٲرِ کُن نظر۔ {پینٹڈ...: ہیب۔ پینٹنگز منز ترٲو امۍ سنزِ اچھ\n31.\\tتہٕ یێلہِ یہو دروازس پیٹھ اژِتھ، تٔمۍ ووٚن، {ہد} زِمری امن، یُس پنُن آقا مٲرِتھ مٲرِو؟\n32.\\tتہٕ تٔمۍ تُل دارِ کُن بُتھ تہٕ وونُن، میانہِ طرفہٕ کُس چُھ؟ کُس؟ تہٕ تتہِ وُچھ أمِس کُن زٕ یا تریہ خواجہ سرا۔ {خواجہ سرا: یا، چیمبرلین}\n33.\\tتہٕ ووٚن أمِس ترٛاوُن۔ تہٕ تِمو ترٛٲو سُہ بۄن: تہٕ تٔمۍ سُنٛد کیٚنٛہہ خوُن آو دیوارس تہٕ گُرٮ۪ن پٮ۪ٹھ چھُکاونہٕ: تہٕ تٔمۍ لٔج أمِس کھۄرَن تل۔\n34.\\tتہٕ ییلہ سُہ اژُن، تٔمِس کھیوٚن تہٕ چیوٚو، تہٕ وونُن، گژھ وُچھِتھ یہِ ملعون {زنانہ}، تہٕ دفن کٔرِن، کیازِ سۄ چھے بادشاہ سٕنز کور۔\n35.\\tتہٕ تِمو گٔیہِ أمِس دفن کرنہِ، مگر تِمو لٔب نہٕ أمِس کھۄپٕرِ کھورِ تہٕ کھورِ تہٕ اتھہٕ کھۅتہٕ زیادٕ۔\n36. اَمہِ مۄکھٕ آیہِ تِم دُبارٕ تہٕ وونُن أمِس۔ تہٕ تٔمۍ ووٚن، یہِ چُھ خداوند سُند کلام، یُس تٔمۍ پننِس خادم ایلیاہ تِشبیتس سٍتـ̡ وونُن چُھ، یِزریل کِس حصس مَنٛز گژھن ہونۍ ییزبیل سُند ماز کھٮ۪وان: {by: Heb. اتھہٕ سٍتۍ }\n37.\\tتہٕ ییزبیل سُند لاش گژھہِ یزریل کِس حصس مَنٛز کھہٕ کِس بُتھِس پیٹھ گوبر ہیوٗ آسُن۔ {تَمہِ مۄکھہٕ﴾ زِ تِم وَنَن نہٕ یہِ {چُھ} یِزبیل۔","1. تہٕ احاب سٕندِس سامریہ مَنٛز زاے ستتھ نیچوۍ۔ تہٕ یہوُن لیکھِتھ چِٹھہِ تہٕ سوُزُن سامریاہس منز، یزرعیل کین حکمرانن، بزرگن تہٕ تِمن خٲطرٕ یِمو احاب سٕندِس {شُرۍ} پرورش کٔرۍ، تہٕ وونُن {تِم...: حب۔ پرورش کَرنہٕ والے}\n2.\\tوۅنۍ ییلہ یہ چِٹھۍ ژے وُچھِتھ تہٕ تۅہہِ سٍتۍ چھِ رتھٕ تہٕ گُرۍ، اکھ تار لٔگِتھ شہر تہٕ ہتھیار تہِ۔\n3.\\tپننِس آقا سٕندِس نیچوِس تہِ وُچھِو، تہٕ بِہٲوِو مٲلہِ سٕندِس تختس پیٹھ، تہٕ لڑٲے پننِس آقا سٕندِس گرٕ خٲطرٕ۔\n4.\\tمگر تِم گٔیہِ سٮ۪ٹھاہ کھوژِتھ تہٕ وونُن، وُچھِو زٕ بادشاہ أمِس برونہہ کُن کھڑا نہٕ: تیلہِ کِتھہٕ پٲٹھۍ؟\n5.\\tیُس یُس گرس پیٹھ اوس، تہٕ یُس شہرس پیٹھ اوس، بڈۍ تہِ تہٕ شُرین ہٕندِس اننہٕ وٲلۍ، یہِ وونُن زِ أسۍ چھِ تُہند خادم، تہٕ یُس ژے اسہِ ہُند حکم دِیُن، سُہ کرو تہٕ یُس ژے اسہِ حکم دِیُن۔ أسۍ بناوو نہٕ کانٛہہ تہِ بادشاہ: ژٕ کٔرِو تُہۍ یُس پننہِ نظرِ منٛز اصل چھُ۔\n6.\\tتمہِ پتہ لیوکھ تِمن دوٚیمہِ لٹہِ اکھ چِٹھہِ، یتھ منز وونُن زِ اگر تہۍ میٲنۍ آواز بوزِو، تہٕ یێلہِ میانہِ کُنہِ لٹہِ یِمن ہٕندِس نیچوِس کلہٕ نِن، تہٕ یێمہِ لٹہِ یێمہِ لٹہِ یِنہٕ یِنہٕ وٲلِس یِزریلس نِش یِنہٕ۔ وۅنۍ ٲسۍ بادشاہ سٕندۍ نیچوۍ، {ستتھ نفر}، {ٲسۍ} شہر کین بٔڈٮ۪ن نفرن سٍتۍ، یِمو تِمن پرورش کٔر۔ {میانۍ: ہیب۔ میانہِ خاطرہ}\n7. تہٕ ییلہ تِمن نِش چِٹھہِ آیہ، تِمو نِش بادشاہ سٕندِ نیچوۍ، تہٕ ستتھ نفر مارِکھ تہٕ تِمن ہٕندِس کلہٕ کٔرِکھ ٹوٗکرِس منز، تہٕ سوٗزُکھ سُہ یزریلس نِش۔\n8.\\tتہٕ اَکھ قاصد آو تہٕ ووٚنُن تِم چھِ بادشاہ سٕندٮ۪ن نیچوٮ۪ن ہٕندِ کلہٕ أنِمٕتۍ۔ تہٕ تٔمۍ ووٚن، دروازٕ کس اژنہٕ وِزِ ترٲو تم صبحس تام دۄن ڈھیرن منٛز۔\n9.\\tتہٕ صُبحے سپُد سُہ نٮبر تہٕ کھڑا تہٕ وونُن سارِنٕے لُکن زِ اے نیک بٔنِتھ، وُچھ، مے کٔر پننِس آقا سٕندِس خلاف سٲزِش تہٕ مارُن، مگر یِم سارِنٕے کٔمۍ مٲرۍ؟\n10.\\tوۅنۍ زان زِ خداوند سٕندِ کلامُک کانہہ تہِ یُس خداوند احاب سٕندِس گرس مُتلق کتھ کورمُت چھُ، یُس خداوند سٕندِس گرس مُتلق کتھ کورمُت چھُ، تکیازِ خداوند چھُ سُہ کٔرمُت یُس تٔمۍ پننِس خادم ایلیاہ سٕندِ دٔسۍ کتھ کٔرمٕژ۔ {by: Heb. اتھہٕ سٍتۍ }\n11.\\tیێلہِ مٲرِتھ یێلہِ یێلہِ ہٕندِس گَرَس مَنٛز یێلہِ ہٕندِس سارِنٕے بٔڈِس نفر، تہٕ تٔمِس سٕندِس رِشتہٕ دار تہٕ پٔنِس پادٕرۍ، یوتام نہٕ أمِس کانہہ تہِ باقٕے روٗد۔ {رشتہ دار: یا، واقفیت}\n12. تہٕ سُہ ووٚتھ تہٕ ووت سامریاہس کُن۔ {تہٕ} یُتھ زن سُہ {اوس} وتہِ منز شیئرنگ ہاوس منز، {شیئرنگ...: ہیب۔ گٔندِتھ گٔژھ\n13.\\tیہوُن یہوداہ کِس بادشاہ احزیاہ سٕندِس باین سٍتـ̡ سمکھہٕ تہٕ وونُن، تُہۍ کُس چھِو؟ تہٕ تِمو دِژ جواب، أسۍ چھِ احزیاہ سٕندِ بٲے ۔ تہٕ أسۍ چھِ بادشاہ سٕنٛدٮ۪ن شُرین تہٕ ملکہ ہٕنٛدٮ۪ن شُرین سلام کرنہٕ خٲطرٕ بۄن گژھان۔ {ملاقات: ہیب۔ لٔب} {سلامی کرنہٕ خٲطرٕ...: ہیب۔ امن، وغیرہ}\n14.\\tتہٕ تٔمۍ ووٚن، تِم زِندٕ رٔٹِو۔ تہٕ تِمو رٔٹۍ تِم زِندٕے تہٕ مارِکھ ژٔٹِتھ نہ تروو تمن منز کانہہ تہِ۔\n15.\\tتہٕ ییلہ سُہ اَتہِ نیرِ، تٔمۍ کٔر رِچاب سٕندِس نیچوِس یَہوندابس سٍتـ̡ أمِس سمکھنہٕ خٲطرٕ، تہٕ تٔمِس کٔرٕن سلام، تہٕ وونُن تُہند دِل چُھہ صحیح، یِتھٕ پٲٹھـ̡ میون دِل چُھہ تہندِس دِلس سٍتـ̡ چُھہ؟ تہٕ جہوندابن دیُت جواب، یہٕ چُھ۔ اگر تہِ آسہِ، تیٚلہِ دِیِو پَنُن اَتھٕ دِیُن۔ تہٕ تٔمۍ دِژ پنُن اتھہٕ۔ تہٕ سُہ نیو سُہ پانس نِش رتھن منٛز۔ {گاش دِنہٕ آمُت: ہیب۔ لبنہٕ آمُت} {سلام: ہیب۔ بابرکت }\n16.\\tتہٕ ووٚن میہ سٍتـ̡ تہٕ وُچھِو خداوند سٕندِ خٲطرٕ میون جوش۔ چنانچہ بنوو تمو سُہ پننِس رتھن منز سوار۔\n17.\\tتہٕ ییلہ سُہ سامریاہس مَنٛز آو، تٔمۍ مارۍ سُہ سٲری یُس سامریاہس مَنٛز اہابس سٍتـ̡ باقٕے روٗدمُت، یوتام تٔمۍ سُہ خداوند سٕندِ کلامَس مُطٲبق تباہ کوٚر، یُس تٔمۍ ایلیاہ سٕندِ کتھ مُطٲبق کٔر۔\n18. تہٕ یہوَن کٔر سارِنٕے لُکھ جمع تہٕ تِمن وونُن زِ اہابن کٔر بعلٕچ خدمت رژھ کھنڈ ۔ {مگر} یہو کرِ أمِس سٮ۪ٹھاہ خدمت۔\n19. تێمہِ کِنۍ کٔرِو بعلٕکۍ سارِنٕے پیغمبرن، تٔمۍ سٕندِس سارِنٕے خادمَن تہٕ تٔمۍ سٕندِس سارِنٕے پادٕرَن بُلاونہٕ۔ کٲنسہِ گژھہِ نہ کانہہ تہِ محتاج: تکیازِ میہ چھیہ بعلس اکھ بٔڈ قربانی دِنہٕ۔ یُس تہِ محتاج آسہِ، سُہ روزِ نہٕ زندٕ۔ مگر یہِ کٔر یہِ باریکی سٍتـ̡ زِ سُہ کرِ بعلٕچ عبادت کرن وٲلـ̡ تباہ کرنہٕ۔\n20. تہٕ یہوَن ووٚن، بعل خٲطرٕ کٔرِو اکھ سنجیدہ مجلسُک اعلان۔ تہٕ تِمو کوٚر اعلان {یہ}۔ {اعلان: ہیب۔ تقدس کٔرِو}\n21. تہٕ یہوُن سٲرۍسٕے اسرٲیلِس مَنٛز سوزمُت، تہٕ بعلٕکۍ سٲری عبادت گزار آیہ، یُتھ نہٕ کانہہ تہِ نفر روٗد یُس نہٕ آو نہٕ۔ تہٕ تِم آیہِ بعل کِس گرس مَنٛز۔ تہٕ بعلُک گرٕ اوس اَکہِ اندٕ پیٹھٕ بییِس اندس تام بٔرِتھ۔ {پور...: یا، تیوت بھرتھ زِ تم ٲس ٲسس پیٹھ ٲسۍ}\n22.\\tتہٕ تٔمۍ ووٚن أمِس زِ پوشہٕ پیٹھ، بعلٕکۍ سارِنٕے عبادت گزارن ہٕندِ خٲطرٕ أنِو پوشاک۔ تہٕ تٔمۍ أنۍ تمن پلو نیبر۔\n23.\\tتہٕ یہوُن تہٕ یہوناڈاب رِچاب سُند نیچو بعل کِس گرس مَنٛز، تہٕ وونُن بعل کِس عبادت گارن تہٕ وُچھُن زِ یَتہِ گژھہِ نہٕ خداوند سٕندِس بندس منزٕ کانہہ تہِ، مگر صرف بعلٕکۍ عبادت گزار۔\n24. تہٕ ییٚلہِ تِم قربانی تہٕ زٲلِتھ نذرانہ پیش کرنہٕ خٲطرٕ اژٕن، یہوَن کٔر ژور نفر مقرر تہٕ وونُن، {یِمَن نفرَن یُس مےٚ تُہنٛدِس اتھس منٛز انمُت چُھ}، {یُس أمِس نیرُن دِیہ}، تٔمۍ سٕنٛز زُو روزِ أمۍ سٕنزِ زُوٕ۔\n25. تہٕ یێلہِ تٔمۍ دزنہٕ نذرانہٕ دِنہٕ ختم کٔرِتھ، یہِ ووٚن رٲچھ دارس تہٕ کپتانس، اژِو اژُن، تہٕ مارُن تِم ۔ کانہہ تہِ گژھہِ نہ برونہہ کُن۔ تہٕ تِمو دِژ تِمن تلوار ہٕندِس اندس سٍتۍ۔ تہٕ رٲچھ دِنہٕ والیو تہٕ کپتانو کٔرِتھ گٔیہِ بعل کِس شہرس کُن۔ {کنارٕ: ہیب۔ ٲس}\n26.\\tتہٕ تِمو کٔر بعل سٕندِ گرٕ منزٕ مجسمہٕ نیبر تہٕ زٲلِتھ زٲلِتھ۔ {تصویر: ہیب۔ مجسمہٕ}\n27.\\tتہٕ تِمو کٔرِکھ بعل سُند مجسمہٕ تہٕ بعل سُند گرٕ ژٔٹِتھ تہٕ بنووُکھ از تام اکھ ڈرافٹ ہاؤس۔\n28.\\tیِتھٕ پٲٹھـ̡ کٔر یہوُن بعل اسرٲیلـ̡ نِش تباہ ۔\n29. یێمہِ سٍتـ̡ نیبت سٕندِس نیچو یربعام سٕندِس گۅنہٕ سٍتـ̡ یێمہِ اسرٲیلـ̡ گۅنہٕ بنوومُت، یہو گۆو نہٕ تِمن پَتہٕ سٍتـ̡ یێلہِ سٍتـ̡ سٍتـ̡ بێیہِ سٍتـ̡ گۅنہٕ پى۪ٹھـ̡\n30.\\tتہٕ خداوند ووٚن یہوُس زِ ژے چُھہ میانہِ نظرِ منز یُس صحیح چُھ، تہٕ یُس میانہِ دِلس مَنٛز چُھہ یُس {اوس} تہٕ یێمہِ سٍتـ̡ تہٕ یێمہِ سٍتـ̡ بێیہِ تُہٕندِس دِلس مُطٲبق تہٕ ژوٗرمہِ پٔرِس سٍتـ̡ بِہنہٕ یِنہٕ وٲلِس تختس پیٹھ۔\n31.\\tمگر یہوُن ہیوٚت نہٕ سارِوٕے دِلہٕ سٍتـ̡ اسرٲیلِکِس خدایہِ سٕندِس شریعتس مَنٛز پکنُک کانہہ دھیاں، تکیازِ سُہ ہیوٚت نہٕ یربعام سٕندِس گۅنہٕ نِشہِ دور، یِمو سٍتـ̡ اسرٲیلِس گۅنہٕ گۅنہٕ بنیوو۔ {ٹُک...: ہیب۔ مشاہدٕ نہٕ}\n32.\\tتِمن دۅہن ہیوٚتُن خداوند اسرٲیلِس ژھٹُن ہیوٚتُن، تہٕ حزایلن دِژ تِمن سارِنٕے بٔٹھِس سٍتـ̡ مار۔ {ژٹنہٕ خٲطرٕ: ہیب۔ اند ژٹنہٕ خٲطرٕ}\n33.\\tاردن پیٹھہٕ مشرقس کُن گٔیہِ گلعادٕچ سارِنٕے سرزمین، گادِس تہٕ روبینِس تہٕ ماناسیٹس پیٹھ، یُس دریائے ارنون کِس نِش تہٕ گلعاد تہٕ باشان تہِ چھُ۔ {مشرقس کُن: ہیب۔ آفتاب کس طلوع گژھنس کُن} {حتیٰ کہ...: یا گلعاد تہٕ باشانس تام تہِ}\n34.\\tوۅنۍ چھُنہٕ یہو سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕندِ سارِنٕے کامہِ تہٕ تٔمۍ سٕندِ سارِوٕے طاقتہٕ سٍتـ̡ چُھنہٕ یِم اسرٲیلِکۍ بادشاہن ہٕندِس تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n35.\\tتہٕ یہو گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ، تہٕ تِمو کٔر سُہ سامریاہس مَنٛز دفن۔ تہٕ تٔمۍ سٕندِس نیچوِس یہواہزن کٔر أمۍ سٕنزِ جایہ حکومت۔\n36.\\tتہٕ یێلہِ سُہ زمانہٕ اوس سامریہِ مَنٛز اسرٲیلس پیٹھ حکومت کٔرِتھ اَٹھہٕ وُہُن۔ {وقت: ہیب۔ دۅہ ٲسۍ}","1. تہٕ ییلہ اَحزیاہ سٕنزِ ماجہ اَتھالیہ وُچھ زِ تٔمۍ سُند نیچو چُھ موٗدمُت، سُہ وُچھ تہٕ سُہ گٔیہِ سارِنٕے شٲہی بیول تباہ۔ {بیج...: ہیب۔ بادشٲہی ہُند بیج}\n2. مگر یہوشبع، بادشاہ یورام سٕنزِ کورِ، یُس احزیاہ سٕنز بینہِ اوس، نِیوُن یُس احزیاہ سُند نیچو تہٕ ژوٗرِ نِش بادشاہ سٕندِس نیچویو منزٕ یِم مارنہٕ آمٕتۍ ٲسۍ۔ تہٕ تِمو تھووُکھ سُہ تہٕ تٔمۍ سٕنز نٔرِس اتھالیہ کِس بسترس منز، تاکہ سُہ گژھہِ نہٕ مارنہٕ۔ {یہوشبع: یتھ تہِ ونان چھِ، یہوشبعت} {جواش: یہواش تہِ ونان چھِ}\n3. تہٕ سُہ اوس أمِس سٍتـ̡ شیٚن ؤرین خداوند سٕندِس گرس مَنٛز ژوٗرِ روزان۔ تہٕ اتھالیاہ کٔر زمینس پیٹھ حکومت۔\n4. تہٕ سٔتِم ؤری یہویاداہن سوٗزۍ تہٕ ہتہٕ بٔدۍ حُکُمران تہٕ رٲچھ دارَن سٍتۍ، تہٕ أنِن تِم خداوند سٕندِس گرس مَنٛز، تہٕ تِمن سٍتـ̡ کوٚرُن تِمن سٍتـ̡ عہد تہٕ کٔرٕن خداوند سٕندِس گرس مَنٛز تِمن ہُند حلف، تہٕ ہٲوُن بادشاہ سُند نیچو۔\n5. تہٕ تٔمۍ دِیُت تِمن حُکُم تہٕ وونُن زِ یہِ چُھ سُہ سُہ کٲم یُس تُہۍ کرِو۔ یُس سبت دۅہس منز اژان چُھ، تُہند تریم حصہ گژھہِ بادشاہ سٕندِس گرس پیٹھ نظر تھاون وول تہِ۔\n6. تہٕ تریم حصہ {گژھہ} سور کس دروازس پیٹھ۔ تہٕ تریم حصہٕ چُھس چوکیدارس پٔتۍ کُن دروازس پیٹھ: یِتھٕ پٲٹھۍ تھاو تُہۍ گرس پیٹھ نظر تھاوُن، تاکہ یہٕ گژھ نہٕ پھُٹنہٕ۔ {یہ...: یا، بریک اپ پیٹھ}\n7. تہٕ یُس سبت دۅہہٕ نیران چُھ، تِم تہِ روزن بادشاہ سٕندِس گرس سٍتـ̡ رٲچھ کٔرِتھ۔ {حصہٕ: یا، کمپنیاں: ہیب۔ اتھہٕ}\n8.\\tتہٕ تُہۍ گژھِو بادشاہس اندۍ گٔژھِتھ، پرٮ۪تھ کانہہ نفر پنُن ہتھیار اتھس منز ہیتھ تہٕ یُس یُس حدس اندر یِیہ، سُہ گژھہِ مارُن، تہٕ بادشاہس سٍتـ̡ یێلہِ سُہ نیرِتھ تہٕ یێلہِ سُہ اژان چُھ۔\n9.\\tتہٕ ہتہٕ بٔدۍ کپتانو کٔر سارِنٕے چیزن مُطٲبق یُس یہویادع پادٕرۍ حکم دِیُتمُت اوس، تہٕ تِمو نِیہِ پرٮ۪تھ أکِس نفرس سٍتـ̡ سبت دۅہہٕ یِنہٕ وٲلِس نفرس سٍتـ̡ یِمن سٍتـ̡ یِمن سٍتـ̡ نیرُن اوس، تہٕ یِمو سٍتـ̡ پادٕرۍ یہویاداہس نِش آو۔\n10.\\tتہٕ ہتہٕ بٔدۍ کپتانن دِژ بادشاہ داوُد سٕندِ نیزٕ تہٕ ڈھال، یِم خداوند سٕندِس مندرس مَنٛز ٲسۍ۔\n11.\\tتہٕ رٲچھ دِنہٕ آمُت، پرٮ۪تھ نَفر اوس پنُن ہتھیار اتھس منز ہٮ۪تھ، بادشاہس اندۍ اند، مندرٕ کِس دٔچھنِس کونہٕ پیٹھٕ مندرٕ کِس کھوورِ کونس تام، قربان گاہ تہٕ مندرس نِش۔ {کون: ہیب۔ کندھ}\n12. تہٕ تٔمۍ أوٚن بادشاہ سُنٛد نیٚچُو، تہٕ لوگُن أمِس پٮ۪ٹھ تاج، تہٕ دِتُن أمِس گوٲہی دِنہٕ۔ تہٕ تِمو بنوو سُہ بادشاہ، تہٕ کوٚرُکھ سُہ مسح کرنہٕ۔ تہٕ تِمو کٔر ژرِ پوٚپ تہٕ وونُن، خدایہ رژھ بادشاہ۔ {خدا...: ہیب۔ بادشاہ زندٕ روزُن}\n13. تہٕ ییلہ اتھلیاہن لُکن ہٕندِس رٲچھ کرن والہِ ہُند شور بوز، سُہ آیہِ لُکن نِش خداوند سٕندِس مندرس مَنٛز۔\n14.\\tتہٕ ییلہ تٔمۍ وُچھ، وُچھ بادشاہ أکِس تھمَس نِش کھڑا، یِتھٕ پٲٹھۍ اوس بادشاہ سٕندِ طرفہٕ تہٕ بادشاہ سٕندِ طرفہٕ تہٕ سارِوٕے لوٗکھ گٔیہِ خۅش تہٕ بُنجہِ سٍتـ̡ وٕنـ̡ تہٕ دِژ پَنٕنـ̡ تہٕ دِژ غداری، غداری۔\n15.\\tمگر یہویاداہن دِژ ہتہٕ بدن ہٕندِس کپتانس تہٕ میزبانن ہٕندِس افسرن ہُند حُکُم تہٕ تِمن وونُن زِ سُہ کرُن حدٕ ورٲے نیبر نیرُن، تہٕ یُس أمِس پتہٕ یُس تلوار سٍتـ̡ مارُن آسہِ۔ تکیازِ پادٕرۍ اوس ووٚنمُت، سُہ گژھ نہٕ خداوند سٕندِس گرس مَنٛز مارنہٕ یُن۔\n16. تہٕ تِمو تھوو أمِس پیٹھ اتھہٕ۔ تہٕ سۄ گٔیہِ تَتھ وتہِ یَتھ کِنۍ گُرِ بادشاہ سٕنٛدِس گرس منٛز آیہ: تہٕ تَتہِ گٔیہِ سۄ مارنہٕ۔\n17. تہٕ یہویاداہن کوٚر خداوند تہٕ بادشاہس تہٕ عوامس درمیان اکھ عہد زِ تم گژھن خداوند سٕندِ لوک۔ بادشاہس تہٕ عوامس درمیان تہِ۔\n18.\\tتہٕ سارِوٕے لُکھ گٔیہِ بعل کِس گرس منز تہٕ ژٔٹِتھ ژٔٹِتھ ۔ تٔمۍ سٕندِ قربان گاہ تہٕ تٔمۍ سٕنزٕ شکلہٕ چھِ تِم پوٗرٕ پٲٹھہِ ٹُکرٕ ٹُکرٕ کٔرِتھ، تہٕ مٲرِتھ مَطَن بعلُک پادٕرۍ قربان گاہن برونہہ کُن۔ تہٕ پادٕرۍ کٔر خداوند سٕندِس گرس پیٹھ افسر مقرر۔ {افسر: ہیب۔ دفتَر}\n19.\\tتہٕ تٔمۍ رٔٹۍ ہتہٕ بٔدۍ حُکُمران تہٕ کپتان، تہٕ رٲچھ دِنہٕ وٲلۍ، تہٕ سارِنٕے زمینہٕ کِس لُک۔ تہٕ تِمو أنۍ بادشاہ خداوند سٕندِ گرٕ پیٹھ، تہٕ وٲتۍ رٲچھ دِنہٕ وٲلِس دروازٕ کِنۍ بادشاہ سٕندِس گرس تام۔ تہٕ سُہ بِیوٹھ بادشاہن ہٕندِس تختس پیٹھ۔\n20. تہٕ زمینٕکۍ سارِوٕے لُکھ گٔیہِ خۄش، تہٕ شہر اوس خاموشی سٍتـ̡ تہٕ تِمو مٲرِتھ اتالیاہ تلوار سٍتـ̡ بادشاہ سٕندِس گرس سٍتـ̡ ۔\n21. سَتھ وُہُر اوس یہوش ییلہ تٔمۍ بادشاہت شروع کٔر۔","1. یہو سٕندِس سٔتِمِس ؤریس مَنٛز کٔر یہواش سٕندِس سٔتِمِس ؤریس مَنٛز حکومت کرُن شروع۔ تہٕ ژتٲجی ؤرین کٔر تٔمۍ یروشلمس منٛز حکومت۔ تہٕ تٔمۍ سٕنٛزِ ماجہ ہُنٛد ناو اوس بیرشیبعُک زیبیہ۔\n2. تہٕ یہووشَن کٔر خداوند سٕندِس نظرِ سٍتـ̡ سٲرۍسٕے دۅہہٕ یُس یہویاداہن أمِس ہدایت دِژمُت اوس۔\n3. مگر تھدِ جایہِ آیہ نہٕ نِنہٕ: لوکو ٲسۍ وُنہِ تہِ تھدٮ۪ن جاین پیٹھ قربانی دِوان تہٕ زالان۔\n4. تہٕ یہوشَن ووٚن پادٕرَن زِ یُس خداوند سٕندِس گرس مَنٛز اننہٕ چُھ یِوان، سُہ پونسہٕ یُس پرٮ۪تھ أکِس شخصہٕ سٕندِس دِلس مَنٛز یِوان چُھ، سُہ پٲنسہٕ یُس خداوند سٕندِس گرس مَنٛز اننہٕ خٲطرٕ چُھ، سُہ پٲنسہٕ یُس کُنہِ تہِ انسان سٕندِس دِلس مَنٛز یِوان چُھ،  {وقف چیز: یا، مقدس چیز: ہیب۔ پاکیزہٕ} {یہٕ پرٮ۪تھ کُن...: ہیب۔ تٔمۍ سٕندِ اندازٕ کین روحن ہٕندِ} {cometh...: Heb. انسان سٕندِس دلس پیٹھ چُھ کھسان}\n5.\\tپادٕرۍ نِن تِمن نِش، پرٮ۪تھ کانہہ وٲقف نِن، تہٕ یَتہِ کُنہِ تہِ دَرٕ لبنہٕ یِنہٕ وٲلِس گرس ہٕنزِ پھُٹٕچ مرمت کرٕنۍ۔\n6.\\tمگر یہِ اوس {یُتھ، یُتھ} بادشاہ یہوش سٕندِس تریمہِ تہٕ وُہمہِ ؤریس مَنٛز اوس نہٕ پادٕرۍ گرٕچ خرابی ٹھیک کٔرمٕژ۔ {ترے...: ہیب۔ وُہِم ؤری تہٕ تریم ؤری}\n7.\\tبادشاہ یہوشَن بُلوو یہویاداے پادٕرۍ تہٕ باقٕے پادٕرین تہٕ تِمن وونُن، کیازِ چھِو نہٕ گرٕچ خٕلاف ٹھیک کٔرِتھ؟ وۅنۍ رٔٹِو نہٕ پننہِ واقفیت ہٕندِ پٲنسہٕ، مگر گرٕ چہ خلاف ورزی ہٕندِ خٲطرٕ دِیُن نہٕ۔\n8.\\tتہٕ پادٕرۍ کٔر نہ لُکن ہٕندِ پٲنسہٕ رٔٹِتھ تہٕ نہ گرٕچ خرابی ٹھیک کرنہٕ خٲطرٕ۔\n9.\\tمگر یہویاداہن روٚٹ اکھ صندوق تہٕ اتھ ٹھانس منز اکھ سوراخ تہٕ تھووُن قربان گاہس نِش، یُس خداوند سٕندِس گرس مَنٛز یِوان چُھ، تہٕ پادٕرۍ یِمو دروازٕ تھووُن تِمو سارِوٕے پٲنسہٕ یُس خداوند سٕندِس گرس مَنٛز اننہٕ آو۔ {دروازہ: ہیب۔ تھریشولڈ}\n10.\\tتہٕ یہِ سپُد، ییلہ تِمو وُچھ زِ صندوقس مَنٛز چُھ واریاہ پٲنسہٕ، بادشاہ سُند کاتب تہٕ بٔڈ پادٕرۍ آیہ، تہٕ تِمو تھٲوِکھ تھیلہٕ مَنٛز، تہٕ وونُکھ پٲنسہٕ یُس خداوند سٕندِس گرس مَنٛز لبنہٕ آو۔ {کاتب: یا، سیکرٹری} {پُٹ...: ہیب۔ پابند کٔرِتھ}\n11. تہٕ تِمو دِژ پونسہٕ تِمن ہٕندِس اتھس مَنٛز، یِمو کٲم کٔرِتھ، یِمن ہٕنز نگرٲنی ٲس خداوند سٕندِس گرس پیٹھ، تہٕ تِمو دِژ یہِ چھانن تہٕ معمارن خٲطرٕ، یُس خداوند سٕندِس گرس پیٹھ کٲم کٔرِتھ، {لیڈ...: ہیب۔ اَنُن یہِ برونہہ کُن}\n12. تہٕ معمارن تہٕ کنن ہٕندِس ژٹنہٕ والٮ۪ن تہٕ خداوند سٕندِس گرس ہٕنزِ خٕلاف مرمت کرنہٕ خٲطرٕ تہٕ سارِنٕے سارِنٕے خٲطرٕ یُس گرٕ مرمت کرنہٕ خٲطرٕ دِنہٕ آمُت اوس۔ {اوس...: ہیب۔ برونٹھ کُن}\n13. مگر خداوند سٕندِس گرس خٲطرٕ آیہ نہٕ رۄپہٕ ہٕندِ پیالہٕ، نِفَر، بیسن، بُرٕ، سۄنہٕ ہٕندِ بانہٕ، یا رۄپہٕ ہٕندِ بانہٕ، یُس خداوند سٕندِس گرس مَنٛز اننہٕ آمُت اوس۔\n14.\\tمگر تِمو دِژ سُہ کامہِ سٍتـ̡ تہٕ اَمہ سٍتـ̡ کٔرٕکھ خداوند سٕندِس مکانس مرمت۔\n15.\\tامہِ علاوہ اوس نہٕ تِمو تِمن نفرن سٍتـ̡ حسابہٕ کٔرِتھ، یِمن ہٕندِس اتھس مَنٛز تِمو کامہِ سٍتـ̡ دِنہٕ یِنہٕ وٲلِس پٲنسہٕ دِنہٕ خٲطرٕ دِنہٕ آمٕتۍ، تِکیازِ تِمو ٲسۍ وفاداری سان سودا کران۔\n16.\\tگۅناہ ہُند پونسہٕ آو نہٕ خداوند سٕندِس گرس مَنٛز اننہٕ: سُہ اوس پادٕرین ہُند۔\n17.\\tشامُک بادشاہ حزائیل ووت تہٕ گاتس خلاف لوٚڑ، تہٕ کوٚرُن یُس یروشلم کُن گژھُن۔\n18.\\tتہٕ یہوداہ کِس بادشاہ یہووشاہَن نِش تِم سٲری مقدس چیز یِم یہوشافات، یہورام تہٕ اَحزیاہ تٔمۍ سٕندِس مٲلِس تہٕ یہوداہ کِس بادشاہن وقف کٔرۍمٕتۍ، تہٕ پنٕنۍ مقدس چیز تہٕ سٲرٕے سۄنہٕ یُس خداوند سٕندِس گرٕ کِس خزانس مَنٛز تہٕ بادشاہ سٕندِس گرس مَنٛز لبنہٕ آمُت اوس، تہٕ سوٗزُن شام کِس بادشاہ حزائیلَس نِش۔  تہٕ سُہ دراو یروشلم پیٹھ۔ {گٔیہ...: ہیب۔ گٔیہِ تھوٚد}\n19.\\tتہٕ یُس باقی یُس تٔمۍ کٔرِتھ، کیا تِم چھِنہٕ یہوداہ کین بادشاہن ہٕنزِ تواریخ کِس کتابہِ منز لیکھنہٕ آمٕتۍ؟\n20.\\tتہٕ تٔمۍ سٕندِس نوکر ووٚتھ، تہٕ کٔرٕکھ سٲزِش تہٕ مِلو سٕندِس گَرَس مَنٛز مارُکھ یُس سِلاہس کُن گژھان چھُ۔ {مکانہٕ...: یا، بیتھمیلو}\n21.\\tشیمتھ سُند نیچو جوزاخر تہٕ شومیر سُند نیچو یہوزآباد تہٕ تٔمۍ سٕندٮ۪و خادمَو دِژ أمِس مارٕ تہٕ سُہ موٗد۔ تہٕ تِمو دفن سُہ پننین مٲلن سٍتـ̡ داؤد شہرس مَنٛز۔","1. یہوداہ کِس بادشاہ اہزیاہ سٕندِس نیچوِس یُس یہوُہٕ سٕندِس ترٚیمِس تہٕ وُہمہِ ؤریس مَنٛز کٔر یہوُہٕ سٕندِس نیچو یہوواہَس سٍتـ̡ سامریہِ مَنٛز اسرٲیلِس پیٹھ حکومت کرٕنـ̡ تہٕ کٔرٕن سدہ ؤری حکومت۔ {ترے...: ہیب۔ وُہِم ؤری تہٕ تریم ؤری}\n2. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز بد کار تہٕ نیبت سٕندِس نیچو یربعام سٕندِس گۅناہ سٍتـ̡ کٔرٕن یێمہِ سٍتـ̡ اسرٲیلـ̡ گۅنہٕ گۅنہٕ بنیوو۔ سُہ گوٚو نہٕ تَمہِ نِش نیران۔ {فالو: ہیب۔ پَتہٕ پَکُن}\n3.\\tتہٕ خداوند سُند غصہٕ گۆو اسرٲیلِس سٍتـ̡ دِنہٕ، تہٕ تٔمۍ دِژ تِم شام کِس بادشاہ حزائیل سٕندِس اتھس مَنٛز، تہٕ حزایل سٕندِس نیچوِس بنہداد سٕندِس اتھس مَنٛز۔\n4. تہٕ یہوہاز کٔر خداوند سٕنز منگ، تہٕ خداوند کٔر أمِس سٍتـ̡ ظُلمُت وُچھمُت، کیازِ شامُک بادشاہن اوس تِمن پیٹھ ظلم کٔرمُت۔\n5. (تہٕ خداوند دِیُت اسرٲیلُک نجات دِنہٕ وول تہٕ تِم دِژ شامٕکۍ اَتھٕ تل نِش نٮ۪بر۔ تہٕ بنی اسرٲیلِس گٔیہِ گۄڈنِکہِ پٲٹھـ̡ پَنٕنـ̡ خیمن مَنٛز روزان۔ {یِتھ کٔنۍ زَن گۄڈٕنِک: ہیب۔ راتھ تہٕ تریمہِ دۅہہ پٲٹھۍ}\n6. توتہِ ہیوٚت نہٕ تِمو یربعام سٕندِس گرٕ کِس گۅنہہ نِش دور، یٔمۍ اسرٲیلِس گۅناہ کٔر، {مگر} پٔکِتھ پٔکِتھ تہٕ سامریہ مَنٛز تہِ روٗد باغ۔ {واک: ہیب۔ سُہ چُھ پَکُن} {باقی: Heb. کھڑا}\n7.\\tتٔمۍ تروو لُکن منز یہوحازَس نِش مگر پنژاہ گُرۍ سوار، داہ رتھ تہٕ داہ ساس پیدل ۔ تکیازِ شامٕکۍ بادشاہن اوس تِم تباہ کٔرۍمٕتۍ، تہٕ ٲسٕکھ یِم ژھٹنہٕ کٔرِتھ گردِ ہٕندۍ پٲٹھۍ۔\n8.\\tوۅنۍ چھہ یہوہاز سٕندِ باقی اعمال تہٕ تٔمۍ سٕندِ کٔرِتھ تہٕ تٔمۍ سٕندِ طاقتہٕ سٍتـ̡ یِم نہٕ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n9.\\tتہٕ یہوہاز گۆو پننین مٲلن سٍتـ̡ شوٚنگ۔ تہٕ تِمو کٔر سُہ سامریاہس مَنٛز دفن: تہٕ تٔمۍ سٕندِس نیچوِس یواشَن کٔر أمِس بدلہٕ حکومت۔ {جواش: یہواش تہِ ونان چھِ}\n10. یہوداہ کِس بادشاہ یواش سٕندِس سٔتٕمِس وہرِس مَنٛز کٔر یہوُہاز سُند نیچو یہووش سامریہِ مَنٛز اسرٲیلِس پیٹھ حکومت کرنہٕ خٲطرٕ شروع، تہٕ شُراہ ؤرین کٔرٕن حکومت۔\n11. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس مَنٛز بُرٕ کٔرِتھ۔ سُہ ہیوٚک نہٕ نیبت سٕندِس نیچو یربعام سٕندِس سارِنٕے گۅنہٕ نِش دور، یٔمۍ اسرٲیلِس گۅناہ کٔرِتھ، {مگر} سُہ پوٚک اَتھ مَنٛز۔\n12. تہٕ یوش سٕندِ باقٕے اعمال تہٕ یُس تٔمۍ کٔر تہٕ تٔمۍ سٕندِ طاقتہٕ سٍتـ̡ یُس أمِس یہوداہ کِس بادشاہس سٍتـ̡ امازیہ سٕندِس خٕلاف جنگ کٔر، کیا تِم چُھنہٕ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n13.\\tتہٕ یواش گۆو پننین مٲلن سٍتـ̡ شوٚنگ۔ تہٕ یروبعام بیوٹھ پننِس تختس پیٹھ، تہٕ یواش آو سامریہِ مَنٛز اسرٲیلٕکۍ بادشاہن سٍتـ̡ دفن کرنہٕ۔\n14. وۅنۍ اوس الیشع پننہِ بیمارِ سٍتـ̡ بیمار ییمہ سٍتـ̡ سُہ موٗد۔ تہٕ اسرائیلُک بادشاہ یواش آو أمِس نِش، تہٕ ووٚنُن أمِس بُتھِس پیٹھ تہٕ ووٚنُن، اے میون باپ، میون باب، اسرٲیلُک رتھ تہٕ تٔمِس سٕندِس گُرۍ سوارِ۔\n15. تہٕ الیشاہن ووٚن أمِس کمان تہٕ تیر رٔٹِو۔ تہٕ تٔمۍ نِش کمان تہٕ تیر۔\n16.\\tتہٕ تٔمۍ ووٚن اسرٲیلِکِس بادشاہس پَنُن اَتھٕ کمانَس پیٹھ۔ تہٕ تٔمۍ تھوو پنُن اتھہٕ اتھ پیٹھ، تہٕ الیشاہن تھووُن بادشاہ سٕندِس اتھس پیٹھ اتھہٕ۔ {تھوو پنُن...: ہیب۔ سوارِ خٲطرٕ بناو پنُن اتھہٕ}\n17.\\tتہِ ووٚن مشرقس کُن دٲر کھولو۔ تہٕ تٔمۍ کھول {یہ}۔ امہ پتہ ووٚن الیشاہن گولۍ۔ تہٕ تٔمۍ گوٗلۍ لگٲوۍ۔ تہٕ تٔمۍ ووٚن، خداوند سٕنزِ نجات ہُند تیر، تہٕ شامہٕ نِش نجات ہُند تیر، تکیازِ ژے کرِ افیکس منز شامٕکۍ لُکھ مارُن، یوتام نہٕ تِم کھٮ۪یہِ۔\n18.\\tتہٕ ووٚن تیر رٔٹِو۔ تہٕ تٔمۍ نیو {تِم}۔ تہٕ تٔمۍ ووٚن اسرٲیلِکِس بادشاہس زِ زٔمیٖنس پیٹھ مارُن۔ تہٕ تٔمۍ دِژ تریہ لٹہِ مار، تہٕ روٗد روٗد۔\n19.\\tتہٕ خدایہِ سُند انسان گوٚو أمِس سٍتـ̡ شرارت تہٕ وونُن، ژے پزِ پانژھ یا شیہ لٹہِ مارُن۔ تیلہ آسہ ژے شامس مارُن یوٚت تام ژیہ یہ کھیوٚو، ییلہ زن وۅنۍ ژیہ شامس پیٹھ تریہ لٹہِ حملہ کرُن۔\n20. تہٕ الیشع موٗد تہٕ تِمو دفن کٔرِتھ۔ تہٕ موآبیو ہٕندیو جمٲژ کوٚر ؤری یِنہٕ وِزِ زمینس پیٹھ حملہٕ۔\n21.\\tتہ سپد یہ سپد ییلہ تم اکس انسانس دفن کران ٲسۍ، وچھ تمو اکھ جمٲژ {انسان}۔ تہٕ تِمو ترٛوو یہِ نفر الیشا سٕندِس قبرس مَنٛز، تہٕ ییٚلہِ أمِس نَفر بۄن دِنہٕ آو تہٕ الیشع سٕنزِ أڈجہِ اَتھٕ لاگُن، سُہ گوٚو زندٕ تہٕ کھوٚد پننٮ۪ن کھۅرن پیٹھ۔ {اوس...: ہیب۔ بۄن گٔیہ}\n22.\\tمگر شامُک بادشاہ حزائیل کٔر یہوہاز سٕندِس سارِنٕے دۅہہٕ اسرٲیلس پیٹھ ظلم۔\n23.\\tتہٕ خداوند اوس تِمن سٍتـ̡ مہربان تہٕ تِمن سٍتـ̡ رحم کٔرِتھ تہٕ تِمن ہُند احترام کورُن، تِمن سٍتـ̡ کرُن نہٕ تِمن ہُند احترام، یێلہِ سٍتـ̡ تِمن ہُند معاہدٕ آسنہٕ کِنـ̡ تہٕ کٔرٕن نہٕ تِمن ہٕندِس حٲضِری سٍتـ̡ دِنہٕ۔ {موجودگی: ہیب۔ بُتھ}\n24.\\tتہ شامُک بادشاہ ہزائیل گۆو مُرد۔ تہٕ تٔمۍ سٕنٛدِ نیچوۍ بنہاداد کٔر أمۍ سٕنٛدِ بدلہٕ حکومت۔\n25.\\tتہٕ یہوآہاز سٕندِ نیچو یہووشَن کٔر حزایل سٕندِس نیچوِس بنہداد سٕندِ اتھہٕ نِش دُبارٕ تِم شہر یُس تٔمۍ جنگہٕ سٍتـ̡ پننِس مٲلِس یہواہاز سٕندِ اتھہٕ نِش نِنہٕ اوس آمُت۔ یوآشَن دِژ أمِس تریہ لٹہِ شکست تہٕ کوٚرُن اسرٲیلٕکۍ شہر بازیافت۔ {ٹُک...: ہیب۔ واپس تہٕ نِنہٕ}","1. اسرائیلُک بادشاہ یہوواہاز سٕندِس نیچو یوآش سٕندِس دٔیمِس ؤریس مَنٛز کٔر یہوداہ کِس بادشاہ یواش سُند نیچو امازیاہ سٕنز حکومت۔\n2. سُہ اوس وُہُہ تہٕ پنٛژٕہ وُہُر وُہُر ییلہِ تٔمۍ بادشاہت شروع کٔر، تہٕ یروشلمس مَنٛز کٔرٕن وُہُہن تہٕ کُنوُہن ؤرین ہٕنز حکومت۔ تہٕ تسٕنزِ ماجہ ہُند ناو اوس یروشلمُک یہودان۔\n3. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز صحیح، توتہِ اوس نہٕ پننِس مٲلس داؤد سٕندۍ پٲٹھۍ، تٔمۍ کٔر سارِنٕے چیزن مطٲبق یِتھٕ پٲٹھۍ تٔمۍ سٕندِس مٲلس یوآش کٔر۔\n4. توتہِ آیہ نہ تھدِ جایہ نِنہٕ: توتہِ ٲسۍ لوکو تھزرن پیٹھ قربانی دِوان تہٕ زالُن۔\n5.\\tتہٕ یێلہِ تٔمۍ سٕندِس اتھس منز بادشٲہی ہٕنز تصدیق سپٕد، تٔمۍ مٲرِتھ پَنٕنـ̡ خادم یِمو بادشاہ سُند مول مارمُت اوس۔\n6. مگر قاتلن ہٕندِ بچہٕ مٲرِتھ نہٕ: یُس موسیٰ سٕنزِ شریعت کِس کتابہِ مَنٛز لیکھنہٕ آمُت چُھ، یتھ مَنٛز خداوند چُھ حکم دِتمُت زِ باپ گژھن نہٕ شُرین ہٕندِ خٲطرٕ مارنہٕ یِنہٕ تہٕ نہ بچہٕ یِن باپَن ہٕندِ خٲطرٕ مارنہٕ۔ مگر پریتھ انسان گژھہِ پننہِ گۅنہہ کِنۍ مارنہٕ یُن۔\n7.\\tتٔمۍ مارُن ادوم سٕندِس وادی مَنٛز داہ ساس تہٕ نِیوُن سلہٕ جنگہٕ سٍتـ̡ تہٕ دِتُن از تام اَمیُک ناو جوکتھیل۔ {سیلہ: یا، پتھر}\n8. اَمہِ پَتہٕ سوٗزۍ اَمزیاہَن اِسرٲیلِکِس بادشاہ یہوآہاز سٕندِس نیچوِس یہوآہاز سٕندِس نیچوِس یہوشَس نِش قاصد تہٕ وونُن زِ آؤ، أسۍ وُچھِو اکھ أکِس بُتھِس کُن وُچھان۔\n9.\\tتہٕ اسرائیلُک بادشاہ یہووشَن سوٗز یہوداہ کِس بادشاہ امازیہس نِش یہوداہ کِس بادشاہس نِش وونُن، یُس لبنان مَنٛز اوس، سُہ اوس لبنان کِس دیودارس کُن سوزمُت، تہٕ وونُن زِ پنٕنۍ کورِ دِیُن میٲنِس نیچوِس زنانہٕ خٲطرٕ، تہٕ تتہِ ووت اَکھ جنگلی جانور یُس لبنانس مَنٛز {اوس}، تہٕ لوٚگ کُنہِ۔\n10. ژے چُھہ پٔزۍ پٲٹھـ̡ ادومس مارمُت، تہٕ چُھہ تُہُند دِل تھوٚدُمُت: اَمہ سٍتـ̡ جلال تہٕ گَرِ روزُن، کیازِ چُھہ ژے پَنٕنـ̡ دَرٕج کٔرِتھ، یێلہِ تہٕ ژے پۯاوُن، تہٕ یہوداہ تہٕ ژے سٍتـ̡ پۯاوٕنـ̡ ۔ {گَرَس منٛز: ہیب۔ تۅہہِ گرس منز}\n11.\\tمگر امازیہ بوز نہٕ۔ تێمہِ کِنۍ ووت اسرائیلُک بادشاہ یہوش۔ تہٕ سُہ تہٕ یہوداہُک بادشاہ امازیہ کٔر بیت شیمشس مَنٛز اکھ أکِس بُتھِس کُن نظر، یُس یہوداہ سٍتـ̡ چُھ۔\n12. تہٕ یہوداہ آو اسرٲیلِس برونہہ کُن بدتر کرنہٕ۔ تہٕ تِم ژٔل پرٮ۪تھ نفر پننین خیمن منٛز۔ {پُٹ...: ہیب۔ سمیٹن}\n13.\\tتہٕ اسرائیلُک بادشاہ یہووش نِیوُن یہوداہ ہُک بادشاہ، یہواش سُند نیچو، بیت شیمشس مَنٛز، تہٕ آو یروشلم کِس دروازس پیٹھٕ ژور ہتھ کیوبِٹ۔\n14.\\tتہٕ تٔمۍ نِن سٲرِے سۄنہٕ تہٕ رۄپھ تہٕ سارِنٕے بانہٕ یِم خداوند سٕندِس گرس مَنٛز تہٕ بادشاہ سٕندِس گرس مَنٛز تہٕ یرغمالن مَنٛز لبنہٕ آمٕتۍ ٲسۍ۔\n15.\\tوۅنۍ یُس یہوش سٕندِ باقٕے اعمال یُس تٔمۍ کٔر، تہٕ تٔمۍ سٕندِس طاقتس سٍتـ̡ کِتھہ پٲٹھـ̡ تٔمۍ یہوداہ کِس بادشاہس سٍتـ̡ امازیہ سٍتـ̡ جنگ کٔرِتھ، کیا تِم چھِنہٕ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n16.\\tتہٕ یہواش گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ سُہ آو سامریاہس مَنٛز اسرٲیلِکۍ بادشاہن سٍتـ̡ دفن کرنہٕ۔ تہٕ تٔمۍ سٕنٛدِ نیچوۍ یروبعام کٔر أمۍ سٕنٛدِ بدلہٕ حکومت۔\n17. تہٕ یہوداہ کِس بادشاہ یوآش سُند نیچو امازیاہ روٗد اسرائیلُک بادشاہ یہوآہاز سٕندِ نیچو یہوش سٕندِ مرنہٕ پتہٕ پنٛدہَن ؤرین زندٕ۔\n18.\\tتہٕ امازیاہٕکۍ باقٕے اعمال چھِنہٕ یہوداہ کِس بادشاہن ہٕنزِ تواریخ کِس کتابس مَنٛز لیکھنہٕ آمٕتۍ؟\n19.\\tوۅنۍ کٔر یِمو یروشلمس مَنٛز أمِس خلاف سٲزِش تہٕ سُہ ژوٚل لاچیش کُن۔ مگر تِمو سوٗز أمِس پتہٕ لاچِش تہٕ مارُکھ سُہ تتہِ۔\n20. تہٕ تِمو أنۍ سُہ گُرٮ۪ن پیٹھ تہٕ سُہ آو یروشلمس مَنٛز پننین مٲلن سٍتـ̡ داؤد شہرس مَنٛز دفن کرنہٕ۔\n21.\\tتہٕ یہوداہ کٮ۪و سارِوٕے لوکو رٔٹِتھ عزریاہ، یُس شُراہ وُہُر اوس، تہٕ بنووُکھ سُہ پننِس مٲلِس اَمازیاہ سٕندِ بدلہٕ بادشاہ۔ {عزریہ: عزیاہ تہِ ونان چھِ}\n22.\\tتٔمۍ بنوو ایلاتھ، تہٕ یہوداہ کُن بَنووُن، تمہ پتہٕ گۆو بادشاہ پننین مٲلن سٍتـ̡ شۄنگنہٕ۔\n23.\\tامازیہ سٕندِس پنٛدٲہِمِس ؤریس مَنٛز کٔر یہوداہ کِس بادشاہ یروبعام سٕندِس نیچوِس یُس اسرٲیلِک بادشاہ یُس اِسرٲیلِس سٍتـ̡ سُند نیچو اوس، سامریہ مَنٛز حکومت کرُن شروع تہٕ کٔرٕن ژتٲجی تہٕ اَکہِ ؤری حکومت۔\n24. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس مَنٛز بد کار کٔرِتھ، سُہ ہیوٚت نہٕ نیبت سٕندِس نیچو یربعام سٕندِس سارِنٕے گۅنہہ نِش دور یٔمۍ اسرٲیلِس گۅنہٕ بناوُن۔\n25.\\tتٔمۍ کٔر اسرٲیلُک ساحل حمتھ سٕندِ اژنہٕ پیٹھٕ سمندرس مَنٛز بحال، یُس تٔمۍ پننِس خادم یوناہ سٕندِ اتھہٕ سٍتـ̡ کتھ کٔر، یُس پیغمبر امیتایی سٕندِ نیچو اوس، یُس گتھفرُک {اوس}۔\n26.\\tکیازِ خداوند وُچھ اسرٲیلُک عذاب، {یێلہِ} اوس سٮ۪ٹھاہ تلخ، کیازِ {اَتھ سٍتـ̡ اوس نہٕ کانہہ بند، نہ اوس کانہہ تہِ بٔرِتھ، تہٕ نہ اوس کانہہ مددگار۔\n27. تہٕ خداوند ووٚن نہٕ زِ سُہ کرِ اسرٲیلُک ناو اسمانس تل مِٹاونہٕ، مگر تٔمۍ بچٲو یُس یوآش سُند نیچو یربعام سٕندِ اتھہٕ سٍتـ̡ بچٲو۔\n28.\\tوۅنۍ یِربعام سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕندِ کُنہِ تہِ کٔرِتھ تہٕ تٔمۍ کِتھہ پٲٹھـ̡ جنگ کٔرِتھ تہٕ کِتھہ پٲٹھـ̡ أمِس دمشق تہٕ حمتھ بازیافت کٔرِتھ، یُس یہوداہ سٍتـ̡ اوس، اسرٲیلـ̡ خٲطرٕ، کیا تِم چُھنہٕ اسرٲیلـ̡ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتـ̡؟\n29. تہٕ یربعام اوس پننین مٲلن سٍتـ̡ شوٚنگمُت، حتیٰ کہ اسرائیلٕکۍ بادشاہن سٍتـ̡ تہِ۔ تہٕ زکریا تٔمۍ سٕندِس نیچوِس کٔر أمِس بدلہٕ حکومت۔","1. یربعام کِس سٔتِمِس وُہمہِ ؤریس مَنٛز اوس یہوداہ کِس بادشاہ امازیہ سُند نیچو عزریاہ بادشاہ سپدُن۔ {عزریہ: عزیاہ تہِ ونان چھِ}\n2. سُہ اوس شُراہ وُہُر ییلہ تٔمۍ بادشاہی شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز زٕ پنژاہ ؤری حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس یروشلمُک یکولیاہ۔\n3. تہٕ یُس خداوند سٕندِس نظرس منز صحیح اوس، یُس تٔمۍ سٕندِس مٲلۍ امازیاہ سٕندِ کٔرمٕژ ٲس۔\n4.\\tیہ بچاوُن زِ تھدِ جایہ آیہ نہٕ ہٹاونہٕ: لوکو کٔر قربان تہٕ زالُن وُنہِ تہِ تھزرن جاین پیٹھ۔\n5. تہٕ خداوند دِژ بادشاہس مار، یُتھ زن سُہ مرنہٕ کس دۅہس تام کوڑھ اوس، تہٕ روٗد واریاہن گرن مَنٛز روزان۔ تہٕ بادشاہ سُند نیچو یوتھم اوس گرس پیٹھ، زمینہٕ کین لوکن ہُند فیصلہ کران۔\n6. تہٕ عزریاہ سٕندِ باقٕے اعمال تہٕ یُس تٔمۍ کٔر، کیا تِم چھُنہٕ یہوداہ کِس بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمُت؟\n7.\\tیێلہِ اوس عزریاہ پننین مٲلن سٍتـ̡ شوٚنگمُت۔ تہٕ تِمو کٔر سُہ پننین مٲلن سٍتـ̡ داؤد شہرس مَنٛز دفن: تہٕ تٔمۍ سٕندِس نیچوِس یوتھمن کٔر أمِس بدلہٕ حکومت۔\n8.\\tیہوداہ کِس بادشاہ عزریاہ سٕندِس ٲٹھہمہِ ؤریس مَنٛز کٔر زکریا یَربعام سٕندِس نیچوِس سٕندِس سامریاہس مَنٛز شیٚن ریٚتن ہٕندِس اسرٲیلس پیٹھ حکومت۔\n9. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس مَنٛز بد کار یُس تٔمۍ سٕندِس مٲلِس سٍتـ̡ اوس کوٚرمُت: سُہ ہیوٚت نہٕ نیبت سٕندِس نیچو یربعام سٕندِس گۅنہہ نِش دور، یٔمۍ اسرٲیلِس گۅنہٕ بناوُن۔\n10.\\tتہٕ جابش سٕندِ نیچو شالوم کٔر أمِس خلاف سازش تہٕ لُکن برونہہ کُن مارُن تہٕ مارُن تہٕ کورُن أمِس بدلہٕ بادشاہت۔\n11.\\tتہٕ زکریا سٕندِ باقٕے اعمال چھِ یِم اسرٲیلِکۍ بادشاہن ہٕندِس تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ۔\n12.\\tیہِ اوس خداوند سُند کلام یُس تٔمۍ یہِ یہوِ سٍتـ̡ وونُن زِ تُہند نیچو بِہِتھ ژوٗرمہِ پٔرِس تام اسرٲیلِہ کِس تختس پیٹھ۔ تہٕ یِتھ کٔنۍ گوٚو یہِ سپدُن۔\n13.\\tجابیش سُند نیچو شلوم کٔر یہوداہ کِس بادشاہ عزیاہ سٕندِس نٔوِس تہٕ ترہمہِ ؤریس مَنٛز حکومت شروع۔ تہٕ تٔمۍ کٔر سامریاہس منٛز پورٕ أکس ریتس پیٹھ حکومت۔ {Uzziah: Gr. Ozias} {اکھ پور...: ہیب۔ دۅہن ہند اکھ ریتھ}\n14.\\tمیناہیم سُند نیچو ووت ترزہ پیٹھ، تہٕ آو سامریہ کُن تہٕ صابیش سُند نیچو شلوم مارُن تہٕ مارُن تہٕ کورُن أمِس بدلہٕ بادشاہت۔\n15.\\tتہ باقی شلوم سٕندِ اعمال تہٕ تٔمۍ سٕنزِ سٲزِش یُس تٔمۍ کٔرمٕژ چھِ، وُچھِو تِم چھِ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابس مَنٛز لیکھنہٕ آمٕتۍ۔\n16.\\tامہ پتہ لوٚگ میناہیم طفسہ تہ اتھ منز موجود سارِنٕے تہٕ تِمن ہٕندِس ساحلس پیٹھ ترزہ نشہِ، تکیازِ تِمو کٔر نہٕ أمِس کُن یلہٕ تہٕ تِمو دِژ تِمن سارِنٕے زنانن یِم بچہٕ ٲسۍ۔\n17.\\tعزریاہ سٕندِس نٔوِس تہٕ ترہمہِ ؤریس مَنٛز کٔر یہوداہُک بادشاہ گادی سُند نیچو میناہیم اسرٲیلِس پیٹھ حکومت کرنہٕ خٲطرٕ شروع، {تہٕ کٔرٕن سامریاہس مَنٛز دہن ؤرین حکومت۔\n18. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز بد کار سٍتـ̡ یُس نہٕ سُہ سارِنٕے دۅہہٕ نیبت سٕندِس نیچو یربعام سٕندِس گۅنہہ نِش دور کٔرِتھ، یٔمۍ اسرٲیلِس گۅنہٕ گۅنہٕ کٔرِتھ بنیوو۔\n19.\\t﴿تہٕ ﴿﴾ اَسیرُک بادشاہ پُل آو زمینس خٕلاف: تہٕ میناہیم دِژ پُلس ساس رۄپہٕ رۄپہٕ، یُتھ تٔمۍ سُند اَتھٕ آسہِ أمِس سٍتـ̡ بادشاہی ہٕنز تصدیق کرنہٕ خٲطرٕ۔\n20.\\tتہٕ میناہیم ہیوٚت اسرٲیلُک پونسہٕ، سارِنٕے طاقتور دولتن ہٕندِس پٲنسہٕ، پرٮ۪تھ أکِس شخصس سٍتـ̡ پنٛژاہ شیکل رۄپہٕ رۄپہٕ، یُس اَشوریہ کِس بادشاہس دِنہٕ مۅکھہٕ۔ چنانچہ اشورُک بادشاہ آو واپس تہٕ روٗد نہٕ اتہِ زمینس مَنٛز۔ {exacted: Heb. نیبر نیرُن}\n21.\\tتہٕ میناہیم سٕندِ باقٕے اعمال تہٕ یُس تٔمۍ کٔرۍ، کیا تِم چھِنہٕ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n22.\\tتہٕ میناہیم اوس پننین مٲلن سٍتۍ شوٚنگتھ۔ تہٕ تٔمۍ سٕنٛدِ نیچوۍ پیکاہیاہ کٔر أمِس بدلہٕ حکومت۔\n23.\\tیہوداہ کِس بادشاہ عزریاہ سٕندِس پنٛژٲہِمِس ؤریس مَنٛز کٔر میناہیم سٕندِس نیچوِس سامریاہس مَنٛز اسرٲیلِس پیٹھ حکومت کرُن، {تہٕ کٔرٕن دۄن ؤرِین ہٕنز حکومت}۔\n24. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز یُس بد کار اوس، سُہ ہیوٚت نہٕ نیبت سٕندِس نیچو یربعام سٕندِس گۅنہہ نِش دور، یٔمۍ اسرٲیلِس گۅنہٕ گۅنہٕ بناوو۔\n25.\\tمگر رِمالیہ سٕندِس نیچِوِ پیکاہ یُس تٔمِس سٍتـ̡ سٲزِش کٔرِتھ، تہٕ دِتُن أمِس سٍتـ̡ بادشاہ سٕندِس محلس مَنٛز، ارگوبَس تہٕ آریہس سٍتـ̡ تہٕ أمِس سٍتـ̡ پَنٛژاہ نَفر تہٕ أمِس سٍتـ̡ مارُن سُہ تہٕ کوٚرُن أمِس کُٹھس مَنٛز بادشاہ سٕندِس محلس مَنٛز۔\n26.\\tتہٕ باقی پیکاحیاہ سٕندِ اعمال تہٕ یُس تٔمۍ کٔر، وُچھِو تِم چھِ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ۔\n27.\\tعزریاہ سٕندِس دۄن تہٕ پنژاہِمِس ؤریس مَنٛز، یہوداہ کِس بادشاہ پیکاہ سٕندِس نیچوِس کٔر سامریاہس مَنٛز اسرٲیلِس پیٹھ حکومت کرُن، {تہٕ کٔرٕن وُہن ؤرۍین حکومت۔\n28.\\tتہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز بد کار سٍتـ̡ یُس نہٕ نیبت سٕندِس نیچو یربعام سٕندِس گۅنہہ نِش دور گۆو نہٕ، یٔمۍ اسرٲیلِس گۅنہٕ گۅنہٕ بنوومُت۔\n29.\\tاسرٲیلُک بادشاہ پیکاہ سٕندِس زمانس مَنٛز آو اشورُک بادشاہ تِگلتھپِلیسر، تہٕ کوٚرُن یِجون، اَبلبِتھماخہ، تہٕ جانواہ، تہٕ کیدیش، تہٕ حزور، تہٕ جلعاد تہٕ گلیل، نفتالی ہٕندِس سارِنٕے سرزمینس پیٹھ قبضہٕ تہٕ نِیُن یِم اسریاہس کُن قٲد کٔرِتھ۔\n30.\\tتہٕ ایلاہ سٕندِس نیچوِس ہوشیا کٔر رملیاہ سٕندِس نیچوِس پیکاہ سٍتـ̡ سٲزش تہٕ مارُن تہٕ کورُن أمِس بدلہٕ عزیاہ سٕندِس نیچوِس یوتھم سٕندِس وُہمہِ ؤریس مَنٛز بادشاہت۔\n31.\\tتہٕ پیکاہ سٕندِ باقٕے اعمال تہٕ یُس تٔمۍ کٔرۍ، وُچھِو تِم چھِ اسرٲیلِکۍ بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ۔\n32.\\tپیکا سٕندِس دٔیمِس ؤریس مَنٛز، یُس اسرائیلُک بادشاہ رمیلیاہ سُند نیچو یوتھام، یہوداہ کِس بادشاہ عزیاہ سُند نیچو یوتھام سٕندِس بادشاہس سٍتـ̡ حکومت کرنُک آغاز کوٚر۔\n33.\\tپانژہ وُہُر وُہُر ییلہ تٔمِس بادشاہی شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز شُراہ ؤری حکومت۔ تہٕ تٔمۍ سٕنٛزِ ماجہ ہُنٛد ناو {اوس} جیروشا، یۄس زادوک سٕنٛز کوٗر ٲس۔\n34.\\tتہٕ یُس خداوند سٕندِس نظرس منز صحیح اوس، تٔمۍ کٔر تٔمۍ سٕندِس مٲلہِ عزیاہ سٕندِس سٍتـ̡ کٔرٕنـ̡ ۔\n35.\\tتھدِ جایہ آیہ نہٕ ہٹاونہٕ: لوکو کٔر تھدٮ۪ن جاین پیٹھ تہِ قربانی تہٕ زالنہٕ۔ تٔمۍ بنوو خداوند سٕندِ گرُک تھوٚد دروازٕ۔\n36.\\tوۅنۍ چھہ یوتھم سٕندِ باقی اعمال تہٕ یُس تٔمۍ کٔرۍ، کیا تم چھہِ نہٕ یہوداہ کین بادشاہن ہٕنزِ تواریخ کتابہِ منز لیکھنہٕ آمٕتۍ؟\n37.\\tتِمن دۅہن کٔر خداوند شامُک بادشاہ یہوداہ ریزن تہٕ رملیہ سُند نیچو پیکاہ سٕندِس خلاف سوزُن شروع۔\n38.\\tتہٕ یوتھم شوٚنگتھ پننین مٲلن سٍتـ̡ تہٕ آو پننین مٲلن سٍتـ̡ دفن کرنہٕ، تہٕ تٔمۍ سُند نیچو اوس أمِس بدلہٕ بادشاہی کٔرمٕژ۔","1. پیکا کِس سداہِمِس ؤریس مَنٛز کٔر یہوداہ کِس بادشاہ یوتھم سٕندِ نیچو رِملیاہ احاز سٕندِ نیچو حُکوٗمت کرنہٕ۔\n2. وُہ وُہُر اوس احاز ییلہ تٔمۍ بادشاہی شروع کٔر، تہٕ یروشلمس مَنٛز کٔرٕن شُراہ ؤری حکومت، تہٕ یُس نہٕ خداوند سٕندِس خدایہ سٕندِس نظرس منز صحیح اوس، یُس داؤد سُند مٲل اوس۔\n3. مگر سُہ پوٚک اسرٲیلِکۍ بادشاہن ہٕنزِ وتہِ منز، ہاں، تہٕ بنووُن پنُن نیچو نارس منز، کافرن ہٕندِ مُطٲبق یُس خداوند بنی اسرٲیلِس برونہہ کُن کڈِتھ دِژمُت۔\n4. تہٕ تٔمۍ کٔرٕن تھزرن جاین تہٕ بالن تہٕ پرٮ۪تھ سبز کُلِس تل بخور قربان تہٕ زالُن۔\n5.\\tشامُک بادشاہ ریزن تہٕ رمیلیاہ سُند نیچو پیکاہ آو یروشلم جنگہٕ خٲطرٕ، تہٕ تِمو کوٚر احازُک محاصرٕ، مگر ہیوٚک نہٕ تس پیٹھ قابو پیوان۔\n6.\\tتمہِ وِزِ کٔر شامُک بادشاہ رِزین ایلاث شامس کُن بازیافت تہٕ یہودی کٔرِن ایلاث منزٕ ژٔلِتھ تہٕ شامٕکۍ وٲتِتھ آیہ از تام اَتہِ روزان۔ {ایلاتھ: ہیب۔ ایلوتھ پیٹھ}\n7.\\tیێمہِ سٍتـ̡ سوٗزۍ احازن اَشوریہ کِس بادشاہس تِگلتھپیلیسرس نِش قاصد تہٕ وونُن زِ بہٕ چُھس تُہند خادم تہٕ تُہند نیچو چُھس، یُس میہ خلاف کھڑا سپدان چُھس تہٕ بہٕ چُھس تُہند خادم تہٕ تُہند نیچو۔\n8.\\tتہٕ آحازن رۄپہٕ تہٕ سۄنہٕ یُس خداوند سٕندِس گرس منز تہٕ بادشاہ سٕندِس گرس مَنٛز لبنہٕ آمُت اوس، تہٕ سوُزُن اَسیر کِس بادشاہس خٲطرٕ اکھ تحفہٕ۔\n9.\\tتہٕ اشورُک بادشاہ کٔر أمِس کُن بوزُن، تکیازِ اشورُک بادشاہ آو دمشقس کُن حملہٕ، تہٕ کوٚرُن أمِس لُکھ کیرس کُن قٲد تہٕ کوٚرُن رِزین مٲرِتھ۔ {دمشق: ہیب۔ دمیسیک}\n10.\\tتہٕ بادشاہ احاز گۆو دمشق یُس اسریاک بادشاہ تِگلتھپیلیسر سٍتـ̡ سمکھنہٕ خٲطرٕ، تہٕ وُچھُن اکھ قربان گاہ یُس دمشقس مَنٛز اوس، تہٕ بادشاہ احاز سوزُن پادٕرۍ یوریاہ نِش قربان گاہُک طرز، تہٕ اَمیُک نمونہٕ، اَمہ کِس سارِنٕے کامہِ مُطٲبِق۔ {دمشق: ہیب۔ دمیسیک}\n11.\\tتہٕ اوریاہ پادٕرۍ بنوو دمشق پیٹھٕ بادشاہ احاز سٕندِ سوزنہٕ آمٕژ سارِنٕے مُطٲبق اکھ قربان گاہ: یِتھٕ پٲٹھۍ بَنوو اُوریاہ پادٕرۍ دمشق پیٹھٕ بادشاہ احازس خٕلاف۔\n12. تہٕ ییلہ بادشاہ دمشقس پیٹھٕ آو، بادشاہن وُچھ قربان گاہ: تہٕ بادشاہ آو قربان گاہس کُن تہٕ کوٚرُن اتھ پیٹھ پیش کرنہٕ۔\n13. تہٕ تٔمۍ زٲلِن پنُن دزنہٕ آمُت نذرانہ تہٕ مازٕچ نذرانہ تہٕ ترووُن پنٕنۍ شرابٕچ نذرانہ تہٕ ترووُن قربان گاہس پیٹھ۔ {تٔمۍ سٕنز امن پیشکش: ہیب۔ امنٕچ پیشکش یِم تٔمۍ سٕنز ٲس}\n14. تہٕ تٔمۍ أنِن براسن قربان گاہ تہِ، یُس خداوند سٕندِ برونہہ کُن اوس، قربان گاہ تہٕ خداوند سٕندِس گرس درمِیان تہٕ تھووُن قربان گاہ کِس شمالس کُن۔\n15.\\tتہٕ بادشاہ احازن دِیُت اُوریاہ پادٕرِس حُکُم دِتھ زٲلِتھ دِنہٕ یِنہٕ واجنہِ قربان گاہ تہٕ شامُک مازُک نذرانہ تہٕ بادشاہ سٕنز دزنہٕ آمٕژ قربان تہٕ تٔمۍ سٕندِ ماز ہٕنز نذرانہ تہٕ تِہٕندِس ماز ہٕنز نذرانہ تہٕ تِہٕندِس ماز ہٕنز نذرانہ تہٕ تِہٕندِس ماز ہٕنز نذرانہ تہٕ تِہٕندِس ماز ہٕنز نذرانہ تہٕ تِہٕندِس ماز ہٕنز نذرانہ تہٕ تِہٕندِس ماز ہٕنز نذرانہ تہٕ تِہٕندِس شرابٕچ نذرانہ زٲلِن ۔ تہٕ اَتھ پیٹھ چھُکھ دزنہٕ آمٕژ نذرانہ ہُند سورُے خون، تہٕ قربانی ہُند سورُے خون: تہٕ براسن قربان گاہ آسہِ میانہِ خٲطرٕ پرژھہٕ گٲر کرنہٕ خٲطرٕ۔\n16.\\tیتھے پاٹھۍ کٔر یوریجہ پادٕرۍ یُس بادشاہ احاز سُند حکم دِژمُت اوس۔\n17.\\tتہٕ بادشاہ احازن ژٔٹِتھ اڈن ہٕندِس اندٕر، تہٕ تِمن نِش کٔرِن لاور۔ تہٕ تُلُن سمندرٕ تِمن بۅنہ کنہِ بٔنِتھ تہٕ تھووُن کنن ہٕندِس فرشس پیٹھ۔\n18.\\tتہٕ سبت ہُند پوشہٕ یُس تِمو گرس مَنٛز بنوومُت اوس، تہٕ بادشاہ سٕندِ اژنہٕ سٍتـ̡ آو سُہ خداوند سٕندِ گرٕ پى۪ٹھہٕ اَسیریا کِس بادشاہس سٍتـ̡ پھیرِ۔\n19.\\tوۅنۍ یُس احاز سٕندِ باقٕے اعمال یُس تٔمۍ کٔرۍ، کیا تِم چھِنہٕ یہوداہ کین بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n20.\\tتہٕ احاز گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ تہٕ دفن سپُد پننین مٲلن سٍتـ̡ داؤد شہرس مَنٛز۔ تہٕ حزقیاہ سُند نیچو کٔر أمِس بدلہٕ بادشاہ۔","1. یہوداہُک بادشاہ آحاز سٕندِس بٔہمہِ ؤریس مَنٛز کٔر یہوداہُک بادشاہ ہوشیا یُس ایلاہ سُند نیچو سامریہِ مَنٛز نوَن ؤرین پیٹھ حکومت کرنُک آغاز کوٚر۔\n2. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز بُرٕ کٔرِتھ، مگر تٔمۍ کٔر نہٕ تس برونہہ کُن اسرٲیلِکۍ بادشاہن ہٕندِس پٲٹھۍ۔\n3.\\tأمِس خٕلاف آو شالمانیسر اسریاہُک بادشاہ۔ تہٕ ہوشیہ بنیوو أمۍ سُند نوکر، تہٕ دِتُن أمِس تحفہٕ۔ {دِیُت: ہیب۔ rendered} {presents: or, tribute}\n4.\\tتہٕ اشوریہ کِس بادشاہس لوٚب ہوشیاہس مَنٛز سٲزِش، تکیازِ تٔمۍ اوس مصر کِس بادشاہس نِش قاصد سوزمُت، تہٕ اوسُن نہٕ اَشوریا کِس بادشاہس نِش کانٛہہ تہِ تحفہٕ دِژمُت، یِتھ کٔنۍ تٔمِس ؤری پتہٕ ؤری وادٕ کورمُت، تَمہِ مۄکھٕ کٔرِن سُہ بنٛد تہٕ قٲد خانس مَنٛز۔ {موجود: یا، خراج تحسین }\n5.\\tاَمہِ پَتہٕ آو اَشورِیُک بادشاہ سارِنٕے زمینس منز، تہٕ ووت سامریہ کُن تہٕ کوٚرُن ترٮ۪ن ؤرین ہُند محاصرٕ۔\n6.\\tہوشیہ کِس نٔوِمِس ؤریس مَنٛز رٔٹِتھ اسرٲیہِ ہٕندِس بادشاہس سٍتـ̡ نِتھ نِن اسرٲیلِس کُن اَسریاہس مَنٛز، تہٕ تھووُن ہالہ تہٕ حبورس مَنٛز گوزان کِس دٔریاوَس مَنٛز، تہٕ مَدس کِس شہرَن مَنٛز۔\n7. یێلہِ چُھہ یہِ زِ بنی اِسرٲیلِیو اوس تِمن خدایہِ سٕندِس خداہس سٍتـ̡ گۅناہ کورمُت، یٔمۍ تِم مصر کِس بادشاہ فرعون سٕندِس اتھہٕ نِش نیبر کٔرِتھ تہٕ باقین دیوتاہن سٍتـ̡ خوفزدٕ کورمُت،\n8. تہٕ پکان کافرن ہٕندِس مجسمس منز، یُس خداوند بنی اسرائیل تہٕ اسرٲیلٕکۍ بادشاہن برونہہ کُن کڈمُت اوس، یُس تمو بنٲومُت اوس۔\n9.\\tتہٕ بنی اسرٲیلیو کٔر ژوٗرِ پٲٹھۍتِم کٲم یِم نہٕ خداوند پننِس خداہس خلاف صحیح ٲسۍ، تہٕ تِمو بنٲوِکھ پننین سارنٕے شہرن مَنٛز، چوکیدارن ہٕندِ مینار پیٹھٕ تارٕ دار شہرس تام۔\n10.\\tتہٕ تِمو کٔرِو پرٮ۪تھ تھدِ بالہٕ تہٕ پرٮ۪تھ سبز کُلِس تلہ کُلِس تَل مجسمہٕ تہٕ باغہٕ: {image: Heb. مجسمہٕ}\n11. تہٕ تتہِ دِژ تِمو سارِنٕے تھزرن جاین بخور زالنہٕ، یِتھٕ کٔنۍ یِمو کُنہِ تہٕ کٔرٕن خداوند سٕندِس شرارتس منز اشتعال دِنہٕ خٲطرٕ بد کار کٔرِتھ:\n12.\\tتِکیازِ تِمو کٔر تِمن بُتن ہٕنز خدمت، یِمن مُتلق خداوند اوس تِمن ووٚنمُت زِ تُہۍ کٔرِو نہٕ یہِ کامہِ کٔرِتھ۔\n13. توتہِ کٔر خداوند اسرٲیلِس تہٕ یہوداہ ہس خٕلاف، سارِنٕے پیغمبرن ہٕندِ ذریعہٕ، تہٕ سارِنٕے بُچھن والیو سٍتـ̡ گوٲہی دِژمٕژ، تہٕ میٲنۍ حُکمن ہٕندِس حُکمس مُطٲبق تھاوُن یُس میہ تُہندین باوجن ہُند حُکُم دِیُتمُت اوس، تہٕ یُس میہ پننین بندن پیغمبرن ہٕندِ طرفہٕ توے سوزمُت اوس۔ {by: Heb. اتھہٕ سٍتۍ }\n14. باوجوٗد تہِ ٲسۍ نہٕ تِم بوزان بلکہ کٔرٕکھ پنٕنۍ گردن سخت، یِتھٕ پٲٹھۍ پننین مٲلن ہٕنزِ گردن، یُس نہٕ خداوند پننِس خداہس پیٹھ یقین اوس تھاوان۔\n15. تہٕ تِمو کٔر تٔمۍ سٕندِس قوانین، تہٕ تٔمۍ سُند عہد یُس تٔمۍ پننین مٲلن سٍتـ̡ کورمُت اوس، تہٕ تٔمۍ سٕنزِ گوٲہی یِم تِمن خلاف گوٲہی دِژ ٲس۔ تہٕ تِمو گٔیہِ بےکار تہٕ گٔیہِ تِمن اندۍ پٔکھۍ یِمن ہٕندِس اندۍ پٔکھۍ یِمن ہُند حکم دِنہٕ آمُت اوس، زِ تِم گژھن نہٕ تِمن ہٕندۍ پٲٹھۍ۔\n16.\\tتہٕ تِمو ترٲوِکھ خداوند سٕندِ خدایہ سٕندِ سارِنٕے حُکُم، تہٕ بَنٲوِکھ تِمن ہٕندِس پگلہٕ سٍتـ̡ بَنٲوِتھ تہٕ بَعلٕچ خدمت کٔرٕنـ̡ ۔\n17. تہٕ تِمو کٔرٕکھ پننین نیچوٮ۪ن تہٕ کورِ نارس مَنٛز نیرُن، تہٕ خدایہ سٕندِس نظرس منز کٔرٕکھ پنُن پان بد کٔرِتھ تہٕ کُنُن پان خداوند سٕندِس نظرس منز بُرٕ کرنہٕ خٲطرٕ، یُس أمِس غصہٕ دِنہٕ مۅکھہٕ۔\n18. تێمہِ کِنۍ اوس خداوند اسرٲیلِس سٍتـ̡ سٮ۪ٹھاہ ناراض تہٕ تِم ہٹٲوِن پننہِ نظرِ نِش نِش۔ یہوداہ قبیلہٕ سٍتـ̡ اوس نہٕ کانہہ تہِ باقٕے رودمُت۔\n19.\\tیہوداہ سٕندِس حکمس تہِ تھاوُن نہٕ خداوند سٕندِس خداہس سٍتـ̡ ، بٔلکہِ روٗد اسرٲیلِہ کِس حکمس مَنٛز پکان یُس تِمو بنوومُت اوس۔\n20. تہٕ خداوند کٔر اسرٲیلٕکۍ سارِنٕے بیول رد تہٕ تِمن دِژُن خراب کرن والٮ۪ن ہٕندِس اتھس مَنٛز، یوتام تٔمۍ تِم پننہِ نظرِ نِش دوٗر کٔرۍ۔\n21.\\tتکیازِ تٔمۍ کٔر اسرٲیلِس داؤد سٕندِس گرس نِش کرایہ دِنہٕ۔ تہٕ تِمو بنوو نیبت بادشاہ سُند نیچو یربعام: تہٕ یربعام بنوو اسرٲیلِس خداوند سٕنزِ پیروی نِش کڈنہٕ، تہٕ بنووُن تِمن گۅناہ اکھ بوٚڈ گۅناہ۔\n22.\\tکیازِ بنی اسرائیل کٔر یربعام کین سارنٕے گۅناہ سٍتـ̡ یُس تٔمۍ کٔرۍ۔ تِم گٔیہِ نہٕ تِمن نِش دور۔\n23. یوتام نہٕ خداوند اسرائیل پننہِ نظرِ نِش ہٹٲو، یِتھ کٔنۍ تٔمۍ پننین سارِنٕے خادمَن پیغمبرن ووٚنمُت۔ یتھے پاٹھۍ آو اسرائیل از تام پننہِ سرزمینہ منزہ اسیریاہس کُن نِنہٕ۔\n24.\\tتہٕ اَشورِیُک بادشاہ أنِن بابل پیٹھ، تہٕ کُتھہٕ پیٹھ، تہٕ آوا پیٹھ، تہٕ حمتھ تہٕ سِفارویم پیٹھ، تہٕ تھووُن اسرٲیلٕکۍ بچہٕ بجایہ سامریہ کِس شہرن مَنٛز تہٕ تِمو کٔرِکھ سامریہ ہٕندِس شہرس مَنٛز روزنہٕ۔\n25. تہٕ یِتھے پٲٹھۍ اوس تِمن ہٕندِس روزنہٕ کِس آغازس منز، یِمو نہٕ خداوند سٕندِ سٍتـ̡ کھوژان، تێمہِ کِنۍ سوٗزۍ خداوند تِمن مَنٛز شیر، یِمو مٲرِتھ {کیٚنٛہہ}۔\n26. اَمہِ مۄکھٕ ووت تِمو اَشوریا کِس بادشاہس سٍتـ̡ کتھ کٔرِتھ، یِم قوم ژے ژٔٹِتھ سامریہٕ کِس شہرن مَنٛز تھوومٕژ چھِ، تِم چِھنہٕ زمینہٕ کِس خدایہ سٕندِ طریقہٕ سٍتـ̡ زانان، تێمہِ مۄکھٕ چُھہ تِمن مَنٛز شیر سوٗزِمُت، تہٕ وُچھِتھ چھِ تِم مٲرِتھ، تِکیازِ تِم چھِنہٕ زمینہٕ کِس خداہٕ سٕندِس طٔریٖقہٕ سٍتـ̡ زانان۔\n27. اَمہِ پتہٕ دِیُت اَشورٕکۍ بادشاہن حُکُم، یُس تتہِ نِنہٕ آمُت چھُ۔ تہٕ تِمن گژھن تہٕ روزن تہٕ سُہ ہیچھناوُن تِمن زمینہٕ کِس خدایہ سُند طریقہٕ۔\n28.\\tتمہِ پتہ آو اکھ پادٕرۍ یُس تمو سامریہ نِش نِتھ نِتھ بیتھلس منز روزُن، تہٕ ہیچھناوُن تِمن کِتھہ پٲٹھـ̡ پزِ خداوند سٍتـ̡ خوف کرُن۔\n29. بہرحال، پرٮ۪تھ قومہٕ بنوو پنٕنۍ دیوتا، تہٕ تھدٮ۪ن مقامن ہٕندِس گھرس مَنٛز تھووُن یِم سامری ٲسۍ بنوومٕتۍ، پرٮ۪تھ قومہٕ پننین شہرن مَنٛز یِمن منز تِم روزان ٲسۍ۔\n30. تہٕ بابل کیو مردو بنوو سوکوتھبینوتھ، تہٕ کُتھ کیو مردو بنوو نیرگل، تہٕ حمتھ کیو مردو بنوو آشیما۔\n31.\\tتہٕ اویٹو بنوو نیبھاز تہٕ تارتک، تہٕ سیفارویو زٲلۍ پننین شُرِ سیفارویم سٕندِس دیوتاہن ادرمیلچ تہٕ انامیلیکس نارس منز۔\n32. یێلہِ گٔیہِ تِمو خداوند سٍتـ̡ کھوژان، تہٕ بنووُکھ پانس مَنٛز بٔنِتھ تھدٮ۪ن مقامن ہٕندِس پادٕرۍ، یِمو تِمن ہٕندِ خٲطرٕ تھدٮ۪ن جاین ہٕندِس گرس مَنٛز قربان کٔرۍ۔\n33. تِم ٲسۍ خداوند سٕندِ خوفہٕ سٍتـ̡ کھوژان، تہٕ تِمن قومن ہٕندِس طریقس پٲٹھـ̡ کٔرٕکھ پننین خداہن ہٕنز خدمت۔ {کُس...: یا، کُس تِم تتہِ نِش نِنہٕ آمُت}\n34.\\tاز تام چِھ تِم گۅڈنِکہِ آداب پٲٹھـ̡ کران: تِم چِھہ نہٕ خداوند سٕندِ سٍتـ̡ کھوژان، تہٕ نہ چِھہ تِمن قونونن مُطٲبق، تہٕ تِمن ہٕندِس حکمس مُطٲبِق، یُس خداوند یعقوب سٕندِس بچن ہُند حُکُم دِیُتمُت چُھ، یُس تٔمۍ اسرٲیلُک ناو دِیُت۔\n35. یٔمِس سٍتـ̡ خداوند سٍتـ̡ عہد کورمُت اوس تہٕ تِمن ہُند حکم دِیُتمُت زِ تِمن سٍتـ̡ گژھِ نہٕ دویمین دیوتاہن سٍتـ̡ کھوژُن، تہٕ تِمن سٍتـ̡ کٔرِو نہٕ تِمن سٍتـ̡ نِش نمُن، تہٕ تِمن ہٕنزِ عبادت کٔرِو، تہٕ تِمن ہٕندِ خٲطرٕ کٔ\n36. مگر خداوند یُس تۅہہِ سٮ۪ٹھاہ طاقتہٕ سٍتـ̡ تہٕ نٔر پھٔہلِتھ مصر کہِ سرزمینہٕ منزٕ نیبر کٔرِتھ، تٔمِس سٍتـ̡ کرو تٔمِس سٍتـ̡ تہٕ تٔمِس سٍتـ̡ کٔرِو قربانی۔\n37. تہٕ قوانین، احکام تہٕ قانون، تہٕ حکم، یُس تٔمۍ تۅہہِ خٲطرٕ لیوٗکھمُت چُھ، تُہۍ پزِ ہمیشہٕ خٲطرٕ عمل کرُن۔ تہٕ تُہۍ گژھِ نہٕ باقین دیوتاہن ہُند خوف کٔرِتھ۔\n38. تہٕ یُس عہد میہ ژے سٍتـ̡ کورمُت چُھ، سُہ گژھہِ نہٕ مٔشِد گٔژھِتھ۔ نہ گژھ تۅہہ بیین دیوتاہن کھوژان۔\n39. مگر خداوند پنُن خدا، یُس تُہۍ کھوژِو۔ تہٕ سُہ کَرِ تُہٕندِس سارِنٕے دُشمنن ہٕندِ اتھہٕ نِش نِش۔\n40.\\tمگر تِمو بوز نہٕ، مگر تِمو کٔر پننہِ گۅڈنِچہِ اندازٕ پٲٹھۍ۔\n41.\\tیێلہِ گٔیہِ یِمو قومہٕ خداوند سٍتـ̡ کھوژان، تہٕ کٔرٕکھ پننین شُرین تہٕ شُرین ہٕندِس شُرین ہٕنزِ بُنـ̡ تہٕ تِمن ہٕندِس شُرین ہٕنزِ بُنـ̡ تہٕ یِتھٕ پٲٹھـ̡ تِمن ہٕندِس مٲلِس سٍتـ̡ تہٕ تِمن ہٕندِس مٲلِس س�","1.\\tوۅنۍ سپد یہ سپدُن یُس اسرٲیلِکۍ بادشاہ ایلہ سٕندِس نیچو ہوشیا سٕندِس تریمہِ ؤریس مَنٛز سپدُن، {یہ} یہوداہ کِس بادشاہ آحاز سُند نیچو حزقیاہ کٔر حکومت۔ {حزقیاہ: أمِس چھِ حزقیاس وَننہٕ یِوان}\n2. سُہ اوس وُہُہ تہٕ پٔنژوٗہُر وُہُر ییٚلہِ تٔمۍ حکوٗمت شروع کٔر۔ تہٕ تٔمۍ کٔر یروشلمس مَنٛز کُنوُہن ؤرین حکومت۔ تٔمۍ سٕنزِ ماجہ ہُند ناو تہِ اوس زکریا سٕنز کورِ ابی ۔ {ابی: ابیجہ تہِ ونان چھِ}\n3. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز صحیح، یُس تٔمۍ سٕندِس مٲلہِ سٕندِ داؤد سٕندِ نظرِ مُطٲبق اوس۔\n4.\\tتٔمۍ کٔرِن تھدِ جایہِ ہٹٲوِتھ تہٕ کٔرِن بُتٕرِ ژٔٹِتھ تہٕ ژٔٹِن موسیٰ سٕندِ دٔسۍ بَنوومُت سُہ ناگ ٹُکرٕ ٹُکرٕ کٔرِتھ، تکیازِ تِمن دۅہن اوس بنی اِسرٲیلِیو اَتھ اگرُب زٲلِتھ، تہٕ تٔمۍ وَنُن اَتھ نحشتان۔ {تصویر: ہیب۔ مجسمہٕ} {نہوشتان: یعنی پیتلُک اکھ ٹُکر}\n5. تٔمۍ کٔر اسرٲیلِکِس خدایہِ سٕندِس خداہس پیٹھ بھروسہٕ۔ یێلہِ أمِس پَتہٕ اوس نہٕ یہوداہ کِس سارِنٕے بادشاہن مَنٛز أمِس ہیوٗ کانہہ تہِ، تہٕ نہٕ أمِس برونہہ کُنہِ تہِ۔\n6.\\tتکیازِ سُہ اوس نہٕ خداوند سٕندِس پٲروی نِش دور گومُت، بلکہ کورُن پَنٕنـ̡ حُکمن ہٕندِس حُکمَس مُطٲبِق، یُس خداوند موسىٰ سُند حُکُم دِیُتمُت اوس۔ {پیٹھ...: ہیب۔ تمس پتہٕ}\n7. تہٕ خداوند اوس أمِس سٍتـ̡ ۔ {تہٕ} سُہ کُنہِ تہِ کُنہِ تہِ گٔیہ، تہٕ تٔمۍ کٔر اَسیرِکِس بادشاہس خٕلاف بغاوت، تہٕ کٔرٕن نہٕ أمِس خدمت۔\n8.\\tتٔمۍ دِژ فلسطینی ، غزہ تہٕ اَمہ کِس سرحدس تام، چوکیدارن ہٕندِ مینار پیٹھٕ باڑ لگاونہٕ آمتس شہرس تام۔ {غزہ: ہیب۔ عزا}\n9.\\tتہٕ یہِ سپُد بادشاہ حزقیاہ سٕندِس ژوٗرمِس ؤریس مَنٛز، یُس اسرٲیلِک بادشاہ ایلاہ سٕندِس نیچو ہوشیا سُند سٔتِم ؤری اوس، {یہ} اشورُک بادشاہ شلمانیسر آو سامریاہس خلاف تہٕ کوٚرُن اتھ محاصرٕ۔\n10.\\tتہٕ تریہ ؤری سپدِتھ کٔر تِمو یہِ رٔٹِتھ: حزقیاہ سٕندِس شیٚیِمہِ ؤریس مَنٛز، یعنی اسرٲیلِکۍ بادشاہ ہوشیہ سُند نٔوِم ؤری، سامریہ آو نِنہٕ۔\n11. تہٕ اشورُک بادشاہ نِن اسرٲیلِس اَشورِس کُن، تہٕ تھووُن ہَلہ تہٕ حبورَس مَنٛز گوزان کِس دٔریاوَس مَنٛز، تہٕ مید کِس شہرَن مَنٛز۔\n12.\\tکیازِ تِمو کٔر نہٕ خداوند پنُن خدا سٕنزِ آوازِ ہٕنز فرمانبرداری، بلکہ کٔرٕکھ تٔمۍ سٕندِس عہدٕچ خلاف ورزی تہٕ یُس موسیٰ سٕندِ خدایہِ سٕندِس بندس حکم دِژمُت اوس، تہٕ بوزُن نہٕ تِمن تہٕ تہٕ کٔرِکھ نہٕ تِمن ہٕندِس عہدس سٍتـ̡ خٕلاف۔\n13.\\tبادشاہ حزقیاہ سٕندِس ژۄدٲہِمِس ؤریس مَنٛز آو اسریاہُک بادشاہ سیناکیریب، یہوداہ کین سارنٕے تارن ہٕندِس شہرس خلاف تہٕ کوٚرُن تِمن پیٹھ قبضہٕ۔ {سیناچریب: ہیب۔ سنہریب}\n14. تہٕ یہوداہ کِس بادشاہ حزقیاہ سوٗز اشوریا کِس بادشاہس نِش لاکیشس نِش یہِ ونان زِ مے چُھس ناراض گومُت۔ میہ نش واپس: یُس ژے میہ پیٹھ تھوو، سہ کرٕ بہٕ برداش۔ تہٕ اسریاہٕکۍ بادشاہن کوٚر حزقیاہ یہوداہُک بادشاہ ترے ہتھ ٹیلنٹ رۄپہٕ تہٕ ترہ ٹیلنٹ سۄنہٕ مقرر۔\n15. تہٕ حزقیاہ ہن دِژ سٲرِی رۄپہٕ یُس خداوند سٕندِس گرس تہٕ بادشاہ سٕندِس گرس مَنٛز لبنہٕ آو۔\n16.\\tتمہِ وِزِ ژٔٹِتھ یِم یہوداہ کِس بادشاہ حزقیاہ سٕندِ دٲرِ تہٕ یِم تھَم یِم یہوداہ کِس بادشاہ حزقیاہ سٕندِ دٔسۍ تھٲومٕتۍ، تہٕ دیتُن سُہ اشوریا کِس بادشاہس ۔ {یہ: ہیب۔ تِم}\n17.\\tتہٕ اَشوٗرِیاہٕکۍ بادشاہن سوُزُن ترطان تہٕ ربسارِس تہٕ ربشیح یُس یروشلمس خلاف أکِس بٔڈِس لشکرس سٍتـ̡ بادشاہ حزقیاہ نِش ۔ تہٕ تِم گٔیہِ ہیوٚر تہٕ یروشلیم وٲتِتھ۔ تہٕ ییلہ تم ہیوٚر آیہ، تم آیہٕ تہٕ کھڑا پیٹھمہٕ تالاب کس نالہٕ نِش، یُس {چُھ} فلر سٕندِس کھیت کس شاہراہس منٛز۔ {عظیم: ہیب۔ گوٚب}\n18.\\tییلہ تِمو بادشاہس بُلوو، تِمن نِش دراو ہلکیا سُند نیچو الیاکیم، یُس گرس پیٹھ اوس، تہٕ شیبنا کاتب تہٕ اساف سُند نیچو یوح۔ {کاتب: یا، سیکرٹری}\n19.\\tتہٕ ربشکہ ووٚن تِمَن زِ وُنۍ کٔرِو حزقیاہ سٍتـ̡ کتھ کرنہٕ، یِتھٕ پٲٹھۍ چُھہ عظیم بادشاہ، اَشوریاہُک بادشاہ وَنان۔\n20.\\tتۅہہ چُھہ ونان، (مگر {تِم چھہِ مگر بیکار لفظہٕ،) {مے چُھہ} جنگہٕ خٲطرٕ مشورٕ تہٕ طاقت۔ وۅنۍ چُھکھ ژیہ کٔمس پیٹھ بھروسہ کران زِ ژے کٔر میہ خلاف بغاوت؟ {sayest: or, talkest} {بیکار...: ہیب۔ وُٹھن ہُند لفظ} {میہ چُھ...: یا، مگر مشورٕ تہٕ طاقت چِھ جنگہٕ خٲطرٕ}\n21.\\tوۅنۍ چُھہ توے اتھ زخم دار نِلہٕ سٕندِس لٔرِس پیٹھ بھروسہ کٔرِتھ، یێمہِ سٍتـ̡ یێلہِ کانہہ انسان رٔلِتھ آسہِ، سُہ گژھہِ تٔمِس اتھس منز، تہٕ یێلہِ سٍتـ̡ چُھہ اَتھ سٍتـ̡ اَتھ سٍتـ̡ یێلہِ {ٹرسٹسٹ: ہیب۔ ژے پیٹھ بھروسہ کرُن}\n22. مگر یێلہِ تہِ چُھہ میہ وَنُن زِ أسـ̡ خداوند پننِس خداہس پیٹھ بھروسہ چُھہ کٔرِتھ، یێمہِ سٕندِس تھدِ مقامس تہٕ یێمہِ سٕنزِ قربان گاہ حزقیاہ نِش نِنہٕ چُھ، تہٕ یہوداہ تہٕ یروشلمس ووٚنمُت، تێلہِ کٔرِو یروشلمس مَنٛز یَتھ قربان گاہَس برونہہ کُن عبادت کرنہٕ؟\n23.\\tتێلہِ چُھس بہٕ ژے دُعا کران زِ میٲنِس آقا اَسیرِکِس بادشاہس سٍتـ̡ دِیُن وعدٕ، تہٕ بہٕ دِیہٕ ژے زٕ ساس گُرۍ، اگر ژٕ تِمن پیٹھ سوارِ لاگنس لایق آسہِ۔ {عہد: یا، یرغمال}\n24. تیلہٕ کِتھ کٔنۍ کٔرِکھ ژے میانِس آقا سٕندِس سارِوٕے کھۄتہٕ کم نوکرَن ہٕندِس أکِس کپتان سُند بُتھ پھیُرِتھ، تہٕ رتھَن تہٕ گُرۍ سوارَن ہٕندِ خٲطرٕ کٔرِکھ مصرس پیٹھ پَنُن بھروسہٕ۔\n25. کیا بہٕ چُھس وۅنۍ خداوند سٕندِ بغٲر اتھ جایہِ تباہ کرنہٕ خٲطرٕ وۅتھان ؟ خداوند ووٚن میہ زِ اتھ زمینس خلاف گژھ تہٕ یہ کرو تباہ۔\n26.\\tاَمہِ پَتہٕ ووٚن ہلکیاہ سٕندِس نیچوِس الیاقیم تہٕ شیبنا تہٕ جوہاہَن رَبشکہِ سٍتـ̡ کتھ کرٕن، بہٕ چُھس ژے پننین خادمَن سٍتـ̡ شامی زبانہِ مَنٛز کتھ کٔرِتھ۔ تکیازِ أسۍ چھہِ سمجھان {یہ}: تہٕ یِمن لوکن ہندین کنن منز اسہِ سٍتـ̡ کتھ کرنہٕ یِوان چھِ۔\n27.\\tمگر رَب شَہَن ووٚن تِمَن زِ میٛٲنِس مٲلکَن چھُ میہ پننِس آقا نِش تہٕ ژےٚ یِم لفظ بولنہٕ خٲطرٕ سوزمُت؟ {کیا تٔمۍ چھُنہ} تِمن نفرن نِش سوزمُت یِم دیوارس پیٹھ بِہتھ چھِ، تاکہ تِم ہیکن پنُن گُبر کھٮ۪ن، تہٕ تۅہہِ سٍتۍ پنُن پیشاب چیوٚن؟ {تہند پنُن پیشاب: ہیب۔ تہندٮن کھۅرن ہند آب}\n28.\\tاَمہِ پتہٕ ووت رَب شَکہٕ یہودین ہٕنزِ زبانہِ مَنٛز بَڑِ آوازٕ سٍتـ̡ وَنُن تہٕ وَنُن زِ بٔڈِ بادشاہ سُند کلام بوزو:\n29.\\tبادشاہ چُھ یِتھٕ پٲٹھۍ ونان زِ حزقیاہ گژھِ نہٕ ژےٚ دھوکہٕ دِتھ، تِکیازِ سُہ ہیوٚک نہٕ تۅہہِ پننہِ اتھہٕ نِش نِش بچٲوِتھ:\n30.\\tحزقیاہ گژھہِ نہٕ تۅہہِ خداہس پیٹھ بھروسہٕ کرُن، یہِ ونُن زِ خداوند کرِ اسہِ نجات تہٕ یہِ شہر گژھِ نہٕ اسریاک بادشاہ سٕندِس اتھس مَنٛز دِنہٕ۔\n31.\\tحزقیاہ سُند کُل مہٕ بوزُن، یِتھٕ پٲٹھۍ چُھ اَشوریاہُک بادشاہ وَنُن زِ میانہِ سٍتـ̡ کٔرِو أکِس تحفہٕ سٍتـ̡ مُہادٕ، تہٕ یێلہِ کٔرِو میانہِ نِش نٮ۪بر تہٕ تێلہِ کھیٚیُن پرٮ۪تھ أکِس سٍتـ̡ تٔمۍ سٕندِس آبس سٍتـ̡ چُھہ: {بناوُن...: نتہٕ کٔرِو میٲنۍ عنایت:  ہیب۔ میہ سٍتۍ کرو اکھ برکت} {cistern: or, pit}\n32. یوتام نہٕ بہٕ یِتھ تہٕ ژےٚ پننہِ زمینہِ ہِش زمینہٕ نِتھ، مَکٲے تہٕ شرابٕچ سرزمین، روٹی تہٕ انگورن ہٕنزِ سرزمین، تیل، زیتون تہٕ ماچھ ہٕنز سرزمین، یُتھ تہٕ تُہۍ روزِو زندٕ، تہٕ مٔرِتھ نہٕ، تہٕ حزقیاہ سُند بوزُن نہٕ، یێلہِ سُہ چُھہ تۅہہِ رٲضی کٔرِتھ ونان زِ خداوند کرِ اسہِ بچاو۔ {قائل کٔرتھ: یا، دھوکہ}\n33. کیا قومن ہٕندِس دیوتاہَن چُھ کُنہِ تہِ دِژمُت تٔمۍ سٕندِس سرزمینس پیٹھ اشوریا کِس بادشاہ سٕندِ اتھہٕ نِش نجات دِژمٕژ؟\n34.\\tحمتھ تہٕ ارپادٕکۍ دیوتا کتہِ چھِ؟ سیفروایم، ہینا تہٕ ایواہٕکۍ دیوتا کتہِ چھِ؟ کیا تِمو چھوا سامرییہ میانہِ اتھہٕ نِش نِش واتنوومُت؟\n35.\\tتِم کُس چِھ تِمن ملکن ہٕندِس سارِنٕے دیوتاہَن مَنٛز یِمو پَنُن مُلُک میانہِ اتھہٕ نِش بچٲومُت چھُ، یُس خداوند یروشلم میانہِ اتھہٕ نِش بچاوُن؟\n36.\\tمگر لُکن تھوو خاموش تہٕ تٔمِس کُنہِ تہِ لفظُک جواب دِیُت، تکیازِ بادشاہ سُند حُکُم اوس یہِ زِ أمِس دِیُن نہٕ جواب۔\n37.\\tاَمہِ پَتہٕ آو حِلکیاہ سُند نیچو الیاقیم، یُس گرس پیٹھ اوس، تہٕ شیبنا کاتب تہٕ عیسوی سُند نیچو جوح آو حزقیاہ نِش تہٕ وونُن ربشہ سٕندِ کلام۔","1.\\tتہٕ ییلہ بادشاہ حزقیاہ بوٗز، تٔمۍ کٔر پَنٕنۍ پلو ژٔٹِتھ تہٕ لوٚگ پَنُن پان بۄٹہٕ پلو لٲگِتھ تہٕ ژاو خداوند سٕندِس گرس منز۔\n2.\\tتہٕ تٔمۍ سوُز الیاکیم، یُس گرس پیٹھ اوس، تہٕ شیبنا کاتب تہٕ پادٕرین ہٕندۍ زِٹھۍ، یِم بوری پوشہٕ ؤلِتھ ٲسۍ، یسعیاہ پیغمبر یُس عموز سٕندِس نیچوِس نِش اوس۔\n3. تہٕ تِمو ووٚن أمِس یِتھٕ پٲٹھۍ، حزقیاہ چُھ ونان، یہِ دۅہ چُھ مصیبت تہٕ ملامت تہٕ توہین ہُند دۅہ، تکیازِ بچہٕ چھِ زینہٕ وِزِ یِوان تہٕ زیٚنہٕ خٲطرٕ چُھنہٕ کانہہ طاقت۔ {توہین رسالت: یا، اشتعال انگیز}\n4. یہ ہیکہِ خداوند تُہند خدا رَبشکہٕ سٕندِ سٲری کلام بوزِتھ، یُس اسریاہُک بادشاہ تٔمۍ سٕندِس آقا سٕندِس زندٕ خدایس ملامت کرنہٕ خٲطرٕ سوزمُت چھُ۔ تہٕ کرِ تِمن کلامَن ہٕنز ملامت یُس خداوند تُہندِ خداہِ سٕندِ خداہن بوزمُت چُھ، تێلہِ تُلِو تُلِتھ باقٕے بچن ہٕندِ خٲطرٕ دُعا۔ {دٔچھۍ: ہیب۔ لٔب}\n5.\\tتہٕ بادشاہ حزقیاہ سٕندِ خادم آیہِ یسعیاہ نِش۔\n6. تہٕ یسعیاہ ہن ووٚن تِمَن زِ یِتھٕ پٲٹھـ̡ تُہۍ پننِس مٲلکَس وَنُن، یِتھٕ پٲٹھـ̡ خداوند چُھ ونان زِ یِمن کلامَن سٍتـ̡ ژے بوزمُت چُھ، یِمو سٍتـ̡ اسریاہٕکۍ بادشاہ سٕندِس خادمَو سٍتـ̡ میانہِ کُفر کٔرِمٕژ چھِ۔\n7. وچھ بہٕ أمِس پیٹھ اکھ دھماکہٕ، تہٕ سُہ بوزِ اکھ افواہ تہٕ گژھہِ پننِس سرزمینس منز واپس۔ تہٕ بہٕ کرٕ سُہ تلوار سٍتـ̡ پننِس سرزمینس منز پنہٕ نـ̡ ۔\n8.\\tیِتھٕ رَبشہ آو واپس، تہٕ وُچھُن اشورُک بادشاہ لِبناہس سٍتـ̡ جنگ کران، تکیازِ أمِس اوس بوزمُت زِ سُہ چُھ لاچِش نِش نیران۔\n9.\\tییلہ تٔمۍ ایتھوپیاہُک بادشاہ ترحکہ سُند یہ ونُن بوز، وُچھ سُہ آو توے سٍتـ̡ لڑنہٕ خٲطرٕ، تٔمۍ سوٗزۍ حزقیاہ ہس نِش دُبارٕ قاصد تہٕ وونُن،\n10. یِتھٕ پٲٹھـ̡ کٔرِو تُہۍ یہوداہ کِس بادشاہ حزقیاہ سٍتـ̡ کتھ کٔرِتھ، یہِ ونُن زِ پُنُن خدا یُس تُہٕندِس پٲٹھـ̡ بھروسہ چُھہ کران تہٕ یہِ ؤنِتھ زِ یروشلم گژھہِ نہٕ اسریاک بادشاہ سٕندِس اتھس منز دِنہٕ۔\n11. وُچھ ژے بوزمُت زِ اَشوٗریا کٮ۪و بادشاہو کیا کوٚر سارنٕے زمینن سٍتۍ، یِم پوٗرٕ پٲٹھۍتباہ کٔرِتھ، تہٕ کیا ژٕ یِیہٕ نجات دِنہٕ؟\n12.\\tقومن ہٕندِس دیوتاہن دِژ تِم یِم میانیو مٲلیو تباہ کٔرۍمٕتۍ۔ {as} گوزان، تہٕ ہاران، تہٕ رزیف تہٕ عدن ہٕندۍ شُرۍ یِم تھیلاسرس منز ٲسۍ؟\n13.\\tحمتھُک بادشاہ تہٕ ارپادُک بادشاہ تہٕ سیفرویم شہرُک بادشاہ، ہینا تہٕ ایواہ ہُک بادشاہ کتہِ چھُ؟\n14.\\tتہٕ حزقیاہ روٚٹ رسولن ہٕندِ اتھہٕ سٕنز چِٹھہِ تہٕ پٔرِتھ پٔرِتھ تہٕ حزقیاہ ووت خداوند سٕندِس گرس مَنٛز، تہٕ ووت یہِ خداوند سٕندِس برونہہ کُن۔\n15. تہٕ حزقیاہ کٔر خداوند سٕندِس برونہہ کُن دعا تہٕ وونُن، اے خداوند، یُس کرُبِمَن درمِیان روزان چُھ، تہٕ چُھکھ تُہۍ کُنی زمینہٕ کِس سارِنٕے بادشٲہی ہُند خدا۔ ژے چھُکھ اسمانس تہٕ زمینہٕ بنوومُت۔\n16.\\tاے خداوند، پَنُن کَن کٔرِو نمُن، تہٕ بوزو: اے خداوند، پنٕنۍ أچھ کھولِو تہٕ وُچھِو: تہٕ بوزو سناخریب سٕندِ کلام، یُس أمِس زندٕ خدایہ سٕندِس ملامت کرنہٕ خٲطرٕ سوزمُت چھُ۔\n17. اے خداوند، اسریاہٕکۍ بادشاہو چھِ قومن تہٕ تِہٕنزِ زمینہٕ تباہ کٔرمٕژ،\n18.\\tتہٕ کٔرِکھ پَنٕنـ̡ دیوتا نارس مَنٛز، تِکیازِ تِم ٲسۍ نہٕ کانہہ دیوتا، مگر انسانن ہٕندِس اتھن، لٔکرِ تہٕ کنن ہٕنزِ کٲم، تێمہِ کِنۍ کٔرِکھ تِمو تِم تباہ ۔ {کاسٹ: ہیب۔ دِنہٕ آمُت}\n19. تێمہِ وۆن، اے خداوند، بہٕ چُھس ژے التجا کران زِ تێہہ بچاو اسہِ تٔمۍ سٕندِس اتھہٕ نِش، یُتھ زِ زمینہٕ کین سارنٕے بادشٲہی گژھن زانن زِ تہٕ چُھکھ خداوند خدا، {حتیٰ کہ} تہِ۔\n20. اَمہِ پَتہٕ سوٗز اَموز سُند نیچو یِسعیاہ حزقیاہ نِش یہِ وَنُن زِ یِتھٕ پٲٹھـ̡ چُھ اسرٲیلِیُک خداوند خداوند وَنان۔\n21. یہِ چُھ سُہ لفظ یُس خداوند تٔمِس متعلق بولمُت چُھ۔ صیہون سٕنزِ کورِ کُنوارِ کٔر تۅہہِ حقارت کٔرِتھ، {تہٕ} کٔرٕن ژےٚ حقارت کرنہٕ خٲطرٕ اسُن۔ یروشلمٕچ کورِ چُھ ژےٚ کلہٕ ہلٲومُت۔\n22.\\tژے کٔمِس کُس ملامت تہٕ کفر کورمُت؟ تہٕ کٔمِس خلاف کٔر ژے پننہ آواز تھزرٲومٕژ، تہٕ پنٕنۍ أچھ تھزرس پیٹھ تُلٕن؟ {حتیٰ کہ} اسرائیل کِس مقدس {ایک} خلاف۔\n23.\\tپننیو رسولو سٍتـ̡ چُھہ ژے رب سٕندِس ملامت کٔرِتھ وونُن، بہٕ چُھس پننین رتھن ہٕندِس بٔڈِس سٍتـ̡ پہاڑن ہٕندِس تھزرس تام، لبنان کِس اندس تام تہٕ ژٹنہٕ یِمن ہٕندِس تھدِ کُلِس تہٕ ژٹنہٕ یِمن ہٕندِس کُلِس تہٕ بہٕ ژٔٹِتھ تہٕ تٔمۍ سٕندِس سرحدن ہٕندِس مکانس منز اژُن،  {تہٕ} تٔمۍ سٕندِس کارمل کِس جنگلس منز۔ {از: ہیب۔ اَتھٕ سٍتۍ {تھوٚد...: ہیب۔ تھزر، وغیرہ} {تٔمۍ سٕندِس کارمل: یا، تہٕ تٔمۍ سٕندِس پھلدار میدان}\n24. میہ چھُ عجیب آب کھٔنِتھ چُھمُت، تہٕ پننیو کھۅرَو سٍتۍ چھُ میہ محصور جاین ہٕندۍ سٲری دریاو خشک کٔرۍمٕتۍ۔ {محاصرہٕ: یا، باڑ لگاونہٕ}\n25.\\tژے چھُنہٕ واریاہ کالہٕ برونہہ بوزمُت {کِتھہٕ پٲٹھۍ} مے یہ کورمُت، {تہٕ} قدیم زمانہٕ سٍتـ̡ مے یہ بنوومُت؟ وۅنۍ چھُس میہ یہ وونمت زِ ژے گژھہِ برباد کٔرِتھ شہر برباد کٔرِتھ۔ {زیٹھ...: یا، میہ کِتھہ پاٹھۍ چھہ یہ واریاہ کالہ برونہہ بنوومت، تہ قدیم زمانہ بنوومت؟ میہ کیا وۅنۍ یہ ویران کرنہ خاطرہ، تہ تار لگٲوتھ شہر تباہ کن ڈھیر بناونۍ؟}\n26. تَمہِ کِنۍ ٲسۍ تِہٕنٛدِ بسکیٖن دَر کم طاقتہٕ، تِم گٔیہٕ مایوس تہٕ پریشان۔ تِم ٲسۍ کھہُک گاسہٕ، تہٕ {یِتھٕ کٔنۍ} سبز کُلۍ ، {یِتھٕ کٔن} مکانن پیٹھ گاسہٕ، تہٕ {یِتھ کٔنۍ زَن مکایہ} بڑنہٕ برونہہ۔ {لۅکٹۍ...: ہیب۔ اَتھٕ کِس شارٹ}\n27. مگر بہٕ چُھس تُہند روزن جاے تہٕ تُہند نیرُن، تہٕ تُہند یِنُک تہٕ میانہِ خلاف تُہند غصہٕ زانان۔ {رہائش: یا، بِہتھ}\n28.\\tکیازِ چانۍ غصہ تہٕ تُہند ہنگامہ چُھس میانین کنن منز ووتمُت، اَمہِ مۄکھٕ تھاوٕ بہٕ پنُن ہُک ہُک تہٕ پنُن لگام چانہِ وٕٹھس منز، تہٕ بہٕ کٔرٕ ژے واپس یِتھ وتہِ ژے آو۔\n29.\\tتہٕ یہِ آسہِ تۅہہِ خٲطرٕ اکھ نشانہٕ، یێمہِ ؤریس منز یێلہِ تِتھۍ چیز کھٮ۪وان یُس پانس سٍتـ̡ بَڑان چُھ، تہٕ دۆیمِس ؤریس مَنٛز یُس امی سٍتـ̡ نیران چُھ۔ تہٕ تریمہِ ؤریس مَنٛز کٔرِو تُہۍ ووُن، تہٕ لُٹِتھ تہٕ انگور کٔرِو، تہٕ یِمن ہُند مٮ۪وٕ کھٮ۪وان۔\n30.\\tتہٕ یُس یہوداہ کِس گرس منزٕ ژلنہٕ آمُت چُھ، سُہ گژھہِ بییہِ بۄن کُن موٗل رٔٹِتھ تہٕ ہیوٚر کُن پھل دِنہٕ۔ {باقیات...: ہیب۔ یہوداہ کِس گرٕ نِش فرار گژھُن}\n31.\\tیِکیازِ یروشلم نیبر نیرِ، تہٕ یُس کُنہِ کُنہِ صیہون کُنہِ نیبر نیرِ، خداوند سُند جوش گژھہِ یۅہے کرُن۔ {تِم...: ہیب۔ فرار گژھُن}\n32.\\tیِتھٕ پٲٹھۍ چُھ خداوند اَسیریا کِس بادشاہس مُتلق ونان زِ سُہ گژھِ نہٕ یتھ شہرس مَنٛز یِنہٕ، نہ تتہِ تیر چلاوُن، نہ یِیہِ اتھ برونہہ کُن ڈالہٕ ہیتھ تہٕ نہ کرِ اتھ خلاف کانہہ بٹھہٕ۔\n33. یێلہِ سُہ آو سُہ یێلہِ سٍتـ̡ واپس، تہٕ یێمہِ شہرس مَنٛز ییہِ نہٕ، خداوند چُھ فرماوان۔\n34. تکیازِ بہٕ کرٕ اتھ شہرس بچاونہٕ خٲطرٕ، پننہِ خاطرٕ تہٕ پننِس خادم ڈیوڈ سٕندِ خٲطرٕ۔\n35.\\tتہٕ تمہِ رٲژ سپُد یہِ زِ خداوند سُند فرشتہ دراو تہٕ دِژُن اشورین ہٕندِس خٲمس مَنٛز اکھ ہتھ ژۅداہ تہٕ پانژھ ساس، تہٕ ییلہ تِم صُبحے سُلہِ ؤتھۍ، وُچھ تِم سارِنٕے لاشہٕ۔\n36.\\tیێلہِ گۆو اسریاہُک بادشاہ سیناکریب، تہٕ گۆو واپس تہٕ نینواہ ہس مَنٛز روزُن۔\n37.\\tتہٕ سپُد ییلہ سُہ پننِس دیوتا نِسرخ سٕندِس گرس مَنٛز عبادت کران اوس، تٔمۍ سٕندِس نیچویو لٔج أمِس تلوار سٍتـ̡ تہٕ ژٔلِتھ ژٔلِتھ آرمینیا کِس سرزمینس منز۔ تہٕ تٔمۍ سٕندِ نیچوۍ ایسرہدون کٔر أمس بدلہٕ حکومت۔ {آرمینیا: ہیب۔ ارارات}","1.\\tتِمن دۅہن اوس حزقیاہ بیمار مرُن۔ تہٕ اموز سُند نیچو پیغمبر یسعیاہ آو أمِس نِش، تہٕ وونُن تٔمِس یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ پنُن گرٕ ترتیب دِیُن۔ تکیازِ ژیہ گژھہِ مرُن، تہٕ زندٕ روزِ نہٕ۔ {سیٹ...: ہیب۔ پنٕنِس گرس مُتلق دِیُن دِیُن}\n2. پَتہٕ کٔرٕن پَنُن بُتھ دیوارس کُن، تہٕ کٔرٕن خداہس نِش دُعا دُعا کٔرِتھ وَنُن،\n3. اے خداوند، بہٕ چُھس ژے گُزٲرِتھ زِ بہٕ کِتھہ پٲٹھـ̡ چُھس پٔزۍ پٲٹھـ̡ تہٕ کامل دِلہٕ سٍتـ̡ پٔکِتھ پٲٹھـ̡ تہٕ چُھس تۅہہِ سٍتـ̡ نیکی کٔرمٕژ۔ تہٕ حزقیاہ ووٚتھ دَگ دَگ۔ {سور: ہیب۔ اکھ زبردست روو سٍتۍ}\n4. تہٕ یِسعیاہ سٕندِس درمِس صحنس مَنٛز نیرنہٕ برونہہ آو خداوند سُند کلام أمِس نِش ووتُن، {دربار: یا، شہر}\n5. دُبارٕ پھیُر، تہٕ حزقیاہ وَنُن میانہِ لُکہٕ کِس کپتان، یِتھٕ پٲٹھۍ چُھ خداوند تُہٕندِس مٲلِس سُند خدا، مے چُھہ تُہند دُعا بوزمُت، مے چُھہ تُہٕندِس اوٚش وُچھمُت، وُچھمُت بہٕ چُھہ ژے شفا دِوان: تریمہِ دۅہہ گژھہِ ژے خداوند سٕندِس گرس تام واتُن۔\n6. تہٕ بہٕ کرٕ چانہِ دۅہس منز پندہ ؤری ہُریر۔ تہٕ بہٕ کَرٕ ژےٚ تہٕ یہِ شہرس اَسیریا کِس بادشاہ سٕندِ اتھہٕ نِش بچاو۔ تہٕ بہٕ کَرٕ اتھ شہرس پننہِ خاطرٕ تہٕ پننِس خادم ڈیوڈ سٕندِ خٲطرٕ بچاو۔\n7.\\tتہٕ یسعیاہ ووٚن انجیر ہُند اکھ گانٹھ نِو۔ تہٕ تِمو نِش تہٕ تھووُن پھیپھس پیٹھ، تہٕ سُہ گوٚو ٹھیٖک۔\n8. تہٕ حزقیاہ ہن ووٚن یسعیاہ ہس سٍتـ̡ کیا نشانی آسہِ زِ خداوند کرِ میہ شفا تہٕ بہٕ گژھہٕ تریمہِ دۅہہ خداوند سٕندِس گرس مَنٛز۔\n9. تہٕ یسعیاہ ووٚن زِ یہِ نشانہٕ گژھہِ تۅہہِ خداوند سٕندِ طرفہٕ یُس تٔمۍ کٔرِتھ کٔرِتھ، یُس تٔمۍ کٔرِتھ کٔرِتھ: سایہ گژھہِ دَہ ڈگری برونہہ کُن، یا دَہ ڈگری پَتہٕ؟\n10.\\tتہ حزقیاہ دیت جواب، یہ چھہ ہلکہ کتھ زِ ژھایہ گژھہِ داہ ڈگری بۅنہ کنہِ۔\n11.\\tتہٕ یسعیاہ پیغمبرن کٔر خداوند سٕندِس نِش فریاد تہٕ تٔمۍ اوٚن سایہ داہ ڈگری پتھ کُن، ییمہ سٍتـ̡ یہِ آحاز کِس ڈائلس مَنٛز بۄن گومُت۔ {ڈائل: ہیب۔ ڈگری}\n12.\\tتمہِ وِزِ سوُز بابل کِس بادشاہ بالادان سٕندِ نیچِوِ بیروڈچبالادانن حزقیاہ ہس چِٹھہِ تہٕ اکھ تحفہٕ، تکیازِ تٔمِس اوس بوزمُت زِ حزقیاہ اوس بیمار۔ {بیروڈچبالادان: یا، میروڈچبالادان}\n13. تہٕ حزقیاہ ہن ہٲو تِمن ہٕنز کتھ تہٕ ہٲوِن تِمن سارِنٕے قٕمتی چیز، رۄپہٕ تہٕ سۄن، تہٕ مسالہٕ، تہٕ قیمتی مرہم تہٕ سارِنٕے ہُند گرٕ تہٕ یُس تٔمۍ سٕندِس خزانس مَنٛز لبنہٕ آو، تٔمۍ سٕندِس گرس مَنٛز اوس نہٕ کیٚنٛہہ تہِ، تہٕ تٔمۍ سٕندِس سارِنٕے سلطنتس مَنٛز، یُس نہٕ حزقیاہ ہن ہٲومُت۔ {قیمتی چیز:  یا، مسالہٕ} {آرمر: یا، جواہرات: ہیب۔ جہاز}\n14.\\tاَمہِ پَتہٕ آو یسعیاہ پیغمبر بادشاہ حزقیاہ نِش تہٕ وونُن تٔمِس زِ یِمو نفرو کیا ووٚن؟ تہٕ تِم کتہِ آیہ تۅہہِ نِش؟ تہٕ حزقیاہ ووٚن زِ تِم چھِ دور مُلکہٕ پٮ۪ٹھٕ آمٕتۍ، حتیٰ کہ بابل پیٹھٕ تہِ۔\n15. تہٕ ووٚن تِمو کیا چُھ تُہندِس گرس مَنٛز وُچھمُت؟ تہٕ حزقیاہ ہن دیُت جواب، سٲری {چیز} یُس میٲنس گرس منز چُھہ تِمو وُچھمُت: میانین خزانن منز چُھ نہٕ کانہہ تہِ چیز یُس میہ ہٲومُت چُھہ نہٕ۔\n16. تہٕ یسعیاہ ہن ووٚن حزقیاہ سُند کلام بوزو۔\n17. وُچھِو دۅہ یِنہٕ زِ تُہٕندِس گَرَس مَنٛز یُس {چُھ} تہٕ یُس تہندِس مٲلِس از تام ذخیرٕ کٔرِتھ چُھ، سُہ گژھہِ بابل مَنٛز نِنہٕ یُن: خداوند چُھ فرماوان زِ کُنہِ تہِ گژھہِ نہٕ باقٕے روزُن۔\n18.\\tتہٕ تُہٕندِس نیچوِس سٍتـ̡ یُس ژے نِش پٲدٕ سپدِ، یُس ژے پٲدٕ کرِ، تِم نِن نِنہٕ۔ تہٕ تِم گژھن بابل کِس بادشاہ سٕندِس محلس مَنٛز خواجہ سرا آسن۔\n19.\\tاَمہِ پَتہٕ ووٚن حزقیاہ یسعیاہ سٍتـ̡ یُس خداوند سُند کلام چُھہ یُس ژے کتھ کٔرمٕژ چُھ۔ تہٕ تٔمۍ ووٚن، {کیا یہ} چھُنہٕ {اصل}، اگر میانین دۅہن منز امن تہٕ سچائی آسہِ؟ {کیا یہ...: یا کیا امن تہٕ سچائی آسہٕ نہٕ وغیرہ}\n20.\\tتہٕ حزقیاہ سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕندِس سارِوٕے طاقتہٕ سٍتـ̡ تہٕ کِتھہ پٲٹھـ̡ بنوو اکھ تالاب تہٕ نالہٕ تہٕ شہرس مَنٛز آب أنِن، کیا تِم چُھنہٕ یہوداہ کِس بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n21. تہٕ حزقیاہ گۆو پننین مٲلن سٍتـ̡ شوٚنگتھ، تہٕ تٔمۍ سُند نیچو منسیٰ کٔر أمِس بدلہٕ بادشاہت۔","1. منسیٰ اوس باہ وُہُر ییلہ تٔمۍ حکومت شروع کٔر، تہٕ یروشلمس مَنٛز کٔرٕن پنژاہ تہٕ پانژاہن ؤرین ہٕنز حکومت۔ تہٕ تٔمۍ سٕنٛزِ ماجہ ہُنٛد ناو اوس حفزیبہ۔\n2. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس مَنٛز بد کار یُس کافرن ہٕنزِ بدکاری پتہٕ کٔر، یُس خداوند بنی اِسرٲیلِس برونہہ کُن دِژمُت اوس۔\n3. تکیازِ تٔمۍ کٔر تِم تھدِ جایہِ یِم حزقیاہ تٔمۍ سٕندِس مٲلہِ تباہ کٔرۍمٕتۍ۔ تہٕ تٔمۍ بنوو بعل خٲطرٕ قربان گاہ تہٕ بنووُن اکھ باغ، یِتھ کٔنۍ زن اسرائیلُک بادشاہ احاب بنوو۔ تہٕ کٔرٕن جنتٕکۍ سارِنٕے لشکرن ہٕنز پوجا تہٕ تِہنز خدمت۔\n4. تہٕ تٔمۍ بنوو خداوند سٕندِس گرس مَنٛز قربان گاہ، یَتھ مُتلق خداوند ووٚن، یروشلمس مَنٛز تھاوٕ بہٕ پنُن ناو۔\n5. تہٕ تٔمۍ بنوو خداوند سٕندِس گرٕ کِس دۄن آنگنن مَنٛز جنتٕہ کِس سارنٕے فوجہٕ خٲطرٕ قربان گاہٕ۔\n6. تہٕ تٔمۍ کٔر پنُن نیچو نارس مٔنزۍ نیرُن، تہٕ زمانہٕ وُچھن، تہٕ طلسمُک استعمال کٔرُن تہٕ واقف روحن تہٕ جادوگرن سٍتـ̡ سٍتـ̡ بێیہِ سٍتـ̡ سٍتـ̡ بد کاری کٔرِتھ۔\n7. تہٕ تٔمۍ کٔر گرس مَنٛز بنوومُت باغُک اکھ مجسمہٕ، یُس خداوند داؤدس تہٕ تٔمۍ سٕندِس نیچوِس سلیمانس ووٚنمُت، یتھ گرس مَنٛز، تہٕ یروشلمس مَنٛز، یُس مے اسرائیلٕکۍ تمام قبیلو منزٕ ژٲرمُت چُھ، بہٕ تھاوٕ پنُن ناو ہمیشہٕ خٲطرٕ:\n8. بہٕ کٔرٕ نہٕ اسرٲیلٕکۍ قدم تتھ زمینہٕ منزٕ نیبر یُس میہ تِہندین مٲلن دِژمُت اوس۔ صرف تیلہِ ییلہ تِم تِمن سارِنٕے مُطٲبِق عمل کرنٕچ کٲم کرنٕچ یُس میہ تِمن حُکُم دِژمُت چُھ، تہٕ تِمن سارِنٕے قونونس مُطٲبق یُس میانہِ خادم موسیٰ ہن تمن حکم دِتمُت چھُ۔\n9.\\tمگر تِمو بوز نہٕ: تہٕ منسیاہن کٔر تِمن قومن کھوتہٕ زیادٕ بُرٕ کٔرِتھ یِم خداوند بنی اسرٲیلِس برونہہ کنہِ تباہ کٔرۍ۔\n10.\\tتہٕ خداوند کٔر پننین بندن ہٕندِ طرفہٕ پیغمبرن ہٕندِ طرفہٕ وَنُن،\n11.\\tکیازِ یہوداہ کِس بادشاہ منسیٰ کٔر یِم مکروہ کٔرۍمٕتۍ، {تہٕ} کٔرٕن سارِوٕے کھۄتہٕ زیادٕ بدکار کٲم یِم أمِس برونہہ ٲس، تہٕ یہوداہ تہِ بنٲومُت پننیو بُتن سٍتـ̡ گۅناہ کرنہٕ۔\n12. تێمہِ کِنۍ چُھہ یێتھ پٲٹھـ̡ یێلہِ یێلہِ تہٕ یہوداہ سٍتـ̡ یێلہِ یێلہِ تہٕ یہوداہ سٍتـ̡ بُردی ہٕندِس سٍتـ̡ دِنہٕ آمُت، یێلہِ یێلہِ تہٕ یێمہِ سٍتـ̡ یہِ بوزِ، تٔمِس دۅشوٕے کَن گٔژھِتھ گٔژھِ۔\n13.\\tتہٕ بہٕ کرٕ یروشلمس پیٹھ سامریہِ ہُند سِلس، تہٕ اَحاب سٕندِس گرس سٍتـ̡ پھٔہلِتھ تہٕ بہٕ کرٕ یروشلمس یِتھٕ پٲٹھۍ {اَکھ انسان} اکھ ڈِش صاف کٔرِتھ، تہٕ {یہ} الٹا کٔرِتھ۔ {وائپنگ...: ہیب۔ سُہ چھُ صاف کٔرِتھ اتھ بُتھِس پیٹھ پھیران}\n14. تہٕ بہٕ تراوٕ پنُن وراثتُک باقی، تہٕ تِمن دُشمن ہٕندِس اتھس مَنٛز حوالہٕ۔ تہٕ تِم بنن پننین سارِنٕے دُشمنن ہُند شِکار تہٕ غنیمت۔\n15.\\tکیازِ یِمو کٔر یُس میانہِ نظرِ منز بد کار اوس، تہٕ یُس دۅہہ تہندِ مٲلۍ مصرہٕ منزٕ نیرِتھ دِنہٕ آمُت، از تام تہِ چُھس میہ شرارت دِژمُت۔\n16.\\tامہِ علاوٕ اوس منسیٰ سُند بے گناہ خوُن تروومُت، یوتام تٔمۍ یروشلم اَکہِ اندٕ پیٹھٕ بییِس اندس تام بٔرِتھ۔ پنہٕ نِس گۅنہٕ سٍتـ̡ ییمہِ سٍتـ̡ تٔمۍ یہوداہ گۅناہ کٔرِتھ، یُس خداوند سٕندِس نظرس منز بُرٕ اوس ۔ {پیٹھ...: ہیب۔ ٲسس پیٹھ ٲسس تام}\n17.\\tوۅنۍ چُھہ مانسیہ سٕندِ باقٕے اعمال تہٕ یُس تٔمۍ سُند گۅناہ کورمُت، کیا تِم چھِنہٕ یہوداہ کین بادشاہن ہٕنزِ تواریخ کِس کتابہِ منز لیکھنہٕ آمٕتۍ؟\n18.\\tتہٕ منسی گۆو پننِس مٲلِس سٍتـ̡ شوٚنگتھ تہٕ سُہ آو پننِس مکانہ کِس باغس مَنٛز، عزہ کِس باغس مَنٛز دفن کرنہٕ۔\n19.\\tامون اوس وُہُہ وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز دۄن ؤرین ہٕنز حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس مشوٗلمیتھ، یۄس جوتبہ کِس ہاروز سٕنز کورِ ٲس۔\n20. تہٕ یُس خداوند سٕندِس نظرس منز بد کار اوس، یِتھ کٔنۍ تٔمۍ سٕندِس مٲلِس مناسی ہٕندِس نظرس منز بد کار اوس۔\n21. تہٕ سُہ پوٚک سٲرۍسٕے وتہِ یُس تٔمۍ سُند مول اژان اوس، تہٕ تِمن بُتن ہٕنز خدمت کٔرٕن تہٕ تِمن ہٕنز پوجا کٔرٕن:\n22. تہٕ تٔمۍ ترٲو پننین آباؤ اجدادن ہُند خداوند خدا، تہٕ ووت نہٕ خداوند سٕنزِ وتہِ پٲٹھۍ۔\n23.\\tتہٕ آمون سٕندٮ۪و نوکرو کٔر أمِس خٕلاف سٲزِش، تہٕ کوٚرُکھ بادشاہ پننِس گرس مَنٛز مٲرِتھ۔\n24.\\tتہٕ زمینہٕ کیو لوکو مارۍ تِم سٲری یِمو بادشاہ آمونس خلاف سٲزش ٲس کٔرمٕژ۔ تہٕ زمینہٕ کیو لوکو بنوو یوسیاہ سٕندِ بدلہٕ پنُن نیچو بادشاہ۔\n25.\\tوۅنۍ یِم امون سٕندِ باقٕے اعمال یِم تٔمۍ کٔرۍ، کیا تِم چھِنہٕ یہوداہ کِس بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n26.\\tتہٕ سُہ آو عزا کِس باغس مَنٛز پننِس قبرس مَنٛز دفن کرنہٕ۔ تہٕ تٔمۍ سُند نیچو یوسیاہ کٔر أمِس بدلہٕ بادشاہ۔ {جوسیاہ: Gr. Josias}","1. یوسیاہ اوس ٲٹھ وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز اکترہ ؤری حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس جدیدہ، یۄس بوسکتھ کِس عدیاہ سٕنز کوٗر ٲس۔\n2. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرِ سٍتـ̡ صحیح، تہٕ پٔکِن پننِس مٲلِس داؤد سٕندِس سارِنٕے وتہِ پٲٹھۍ، تہٕ دٔچھُن تہٕ کھوورِ کُن پھیرُن نہٕ۔\n3. تہٕ یہِ سپُد بادشاہ جوسیاہ سٕندِس اردٲہمہِ ؤریس مَنٛز، {یہِ} بادشاہن سوزُن شافان سُند نیچو، میشُلام سُند نیچو، کاتب سُند نیچو، خداوند سٕندِس گرس کُن وونُن،\n4.\\tہلکیاہَس نِش گژھِو اعلیٰ پادٕرۍ سٕندِس گَرَس مَنٛز یُس رۄپہٕ رۅپہٕ رٔٹِتھ یُس دروازٕ رٲچھ کرن والیو لُکن ہٕندِس گرس مَنٛز اننہٕ آمُت چھُ، یُس دروازٕ رٲچھ کرن والیو لُکن ہٕندِس مَنٛز جمع کٔرِمُت چھُ: {دروازٕ: عبری۔ تھریشولڈ}\n5. تہٕ تِم دِن یہِ کٲم کرَن والٮ۪ن ہٕندِس اتھس مَنٛز، یُس خداوند سٕندِس گرس پیٹھ نظر تھاوان چُھ، تہٕ تِم دِن یہِ کٲم کرَن والٮ۪ن یُس خداوند سٕندِس گرس مَنٛز {چُھ} چُھ، یُس گرٕ سٕندِس گرس مَنٛز چُھ، تِمن دِیُن گرٕچ خٕلاف ٹھیک کرنہٕ خٲطرٕ،\n6. چھانن، معمارن تہٕ معمارن تہٕ معمارن خٲطرٕ، تہٕ مکانچ مرمت خٲطرٕ لٔکر تہٕ کٔنہٕ ہینہٕ۔\n7.\\tبہٕ اوس نہٕ تِمن سٍتۍ کانہہ حساب لگاونہٕ آمُت یُس تِمن ہٕندِس اتھس منز دِنہٕ آمُت اوس، تکیازِ تِمو ٲسۍ وفاداری سان سودا کران۔\n8.\\tتہٕ ہلکیاہ، اعلیٰ پادٕرین ووٚن شافان کاتبَس زِ مے لوٚب شریعتٕچ کتاب خداوند سٕندِس گرس منز۔ تہٕ ہلکیاہن دِژ کتاب شافنس تہٕ تٔمۍ پٔر سُہ ۔\n9.\\tتہٕ شافان کاتب آو بادشاہس نِش، تہٕ کوٚرُن بادشاہس دُبارٕ کلام تہٕ وونُن، تہٕ چُھکھ تۅہہِ خادمو سُہ پونسہٕ جمع کٔرِتھ یُس گرس منز لبنہٕ آمُت اوس، تہٕ چُھکھ تِمن ہٕندِس اتھس منز دِژمُت یُس کٲم کران چُھ، یِمن ہٕندِس گرس پیٹھ نظر تھاوان چُھ۔ {جمع: ہیب۔ پگھلُن}\n10.\\tتہٕ شافان کاتب ہٲو بادشاہس ہٲوِتھ وونُن، حلکیا پادٕرۍ چھے مے اکھ کتاب دِژمٕژ۔ تہٕ شافانن پٔر یہ بادشاہس برونہہ کنہِ۔\n11.\\tتہٕ سپُد یہِ سپدُن، ییٚلہِ بادشاہن شریعت کِس کتابہِ ہٕندۍ کلام بوٗزۍ، تٔمۍ کٔر پَنٕنۍ پلو ژٔٹِتھ۔\n12.\\tتہٕ بادشاہن دِیُت حِلکیاہ پادٕرۍ تہٕ شافان سُند نیچو احیکام، تہٕ میخایا سُند نیچو اچبور تہٕ شافان کاتب تہٕ عساحیاہ بادشاہ سٕندِس نوکر سُند حُکُم دِتھ وونُن {آچبور: یا، عبدون} {میکایہ: یا، میکاہ}\n13. گژھو، میانہِ خٲطرٕ، تہٕ لُکن ہٕندِ خٲطرٕ، تہٕ سارِنٕے یہوداہٕ سٕندِ خٲطرٕ، یُس کتابہِ ہٕندِس کلامس مُتلق پرژھہِ: یُس اسہِ سٍتـ̡ دِنہٕ آمُت چُھ، کیازِ سانٮ۪و مٲلو چُھنہٕ امہِ کتابہِ ہٕندِس کلامس بوزمُت، یُس اسہِ متعلق لیکھنہٕ آمُت چُھ، تِمن سارِنٕے مُطٲبق کرُن یُس اسہِ متعلق لیکھنہٕ آمُت چُھ۔\n14.\\tیِتھٕ کٔنۍ گٔیہِ حلقیہ پادٕر، تہٕ احیکام، تہٕ اَچبور، تہٕ شافان تہٕ اساہیاہ گٔیہِ حُلدہ نَبَر نِش، یُس تِکواہ سُند نیچو شَلوم سٕنزِ زنانہٕ ٲس، یُس ہرہاس سُند نیچو اوس، یُس المارِ ہُند رٲچھ کَرن وول اوس۔ (وۅنۍ ٲس سۅ یروشلمس منز کالجس منز روزان؛) تہٕ تمو کٔر أمس سۭتۍ کتھ باتھ۔ {وارڈروب: ہیب۔ لباس} {منز...: یا، دوٚیمس حصس منز}\n15. تہٕ تٔمۍ ووٚن تِمَن زِ یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند وَنُن یُس تُہۍ میانہِ نِش سوزمُت چھُ،\n16. یِتھٕ پٲٹھـ̡ چُھہ خداوند فرماوان زِ یێمہِ جایہِ تہٕ یێمہِ ہٕندِس بسکینس سٍتـ̡ بُردی ہٕندِس سٍتـ̡ یُس یہوداہ کِس بادشاہن پٔرِمُت چُھ:\n17. کیازِ تِمو چُھ میہ ترٲومُت، تہٕ باقین دیوتاہن خٲطرٕ چُھکھ بخور زٲلمُت، یُتھ زن تِم پنہٕ نِس اَتھٕ سٍتـ̡ سارِنٕے کامہِ سٍتـ̡ مے شرارت ہٕندِس سٍتـ̡ دِنہٕ یِن۔ تَمہِ کِنۍ گژھہِ میون غصہٕ یَتھ جایہِ دِنہٕ، تہٕ یِیہِ نہٕ ژھٹنہٕ۔\n18.\\tمگر یہوداہ کِس بادشاہس یُس تۅہہِ خداوند سٕندِس سٍتـ̡ پرژھہٕ گٲر کرنہٕ خٲطرٕ سوزمُت چُھ، یِتھٕ پٲٹھـ̡ چُھہ تٔمِس وَنُن، یِتھٕ پٲٹھـ̡ چُھہ اسرٲیلُک خداوند خدا، یِتھٕ پٲٹھـ̡ چُھہ تِم لفظ یُس ژے بوزمُت چُھ،\n19. کیازِ تُہند دِل اوس نرم، تہٕ ژے کٔر خداوند سٕندِس برونہہ کُن پنُن پان عاجز، یێلہِ ژے بوز یێلہِ مے یَتھ جایہِ تہٕ اَتھ منز روزن والٮ۪ن خلاف کتھ کٔرٕن، یێلہِ تِم گژھن ویران تہٕ لعنت، تہٕ ژٔٹِھکھ پنٕنۍ پلو ژٔٹِتھ تہٕ میانہِ برونہہ کُن رووُن۔ میہ تہِ چُھ بوزمُت، خداوند چُھ فرماوان۔\n20. تێلہِ وُچھِو بہٕ ژے پننین مٲلن نِش جمع کٔرِتھ، تہٕ ژٕ یِیہٕ امن سان پننہِ قبرِ مَنٛز جمع کرنہٕ۔ تہٕ چانہِ أچھ وُچھن نہٕ سٲرِی بُرٕ یُس بہٕ یَتھ جایہِ اَننہٕ یِوان۔ تہٕ تِمو اوٚن بادشاہ سُند لفظ۔","1. تہٕ بادشاہن سوٗز، تہٕ تِمو کٔر یہوداہ تہٕ یروشلمٕکۍ سٲری بزرگ أمِس نِش جمع۔\n2. تہٕ بادشاہ ووت خداوند سٕندِس گرس مَنٛز، تہٕ یہوداہٕکۍ سٲری مرد تہٕ یروشلمٕکۍ سٲری بسکیٖن، تہٕ پادٕر، تہٕ پیغمبرن تہٕ سارِنٕے لوک، لۄکٕٹۍ تہٕ بٔڈۍ، تہٕ تٔمۍ پٔرِن تِہندین کنن مَنٛز عہد کِس کتابہِ ہٕندۍ سٲری لفظ یُس خداوند سٕندِس گرس مَنٛز لبنہٕ آو۔ {دۄشوے...: ہیب۔ لۅکٹۍ پیٹھہ عظیم تہِ}\n3. تہٕ بادشاہ اوس أکِس تھمَس نِش کھڑا تہٕ کوٚرُن خداوند سٕندِ برونہہ کُن اکھ عہد زِ سُہ کرِ خداوند سٕندِ پَتہٕ پَکُن، تہٕ تٔمۍ سٕندِس حُکمن تہٕ گوٲہی تہٕ تٔمۍ سٕندِس قوانینس پورٕ دِلہٕ سٍتـ̡ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ پٲٹھـ̡ تھاونہٕ خٲطرٕ، یُس اتھ کتابہِ مَنٛز لیکھنہٕ آمُت اوس۔ تہٕ سٲری لوٗکھ گٔیہِ معاہدس پیٹھ کھڑا۔\n4. تہٕ بادشاہن دِیُت حِلکیاہ، بٔڈ پادٕر، تہٕ دۆیمِس درجٕکۍ پادٕرۍ تہٕ دروازٕ رٲچھ کرن والٮ۪ن حُکُم زِ تِم کٔرِن خداوند سٕندِ مندرٕ منزٕ تِم سٲری بانہٕ یِم بعل خٲطرٕ، باغہٕ خٲطرٕ تہٕ اسمانٕکۍ سارِنٕے لشکرن خٲطرٕ بناونہٕ آمٕتۍ ٲسۍ، تہٕ تِم زٲلِن یروشلم ورٲے کِدرون کِس میدانس مَنٛز۔  تہٕ تِمن ہُند سوٗر نِیُن بیتھلس تام۔\n5. تہٕ تٔمۍ کٔر بت پرست پادٕرۍ، یِمن یہوداہ کٮ۪و بادشاہو یہوداہ کِس شہرن تہٕ یروشلمس اندۍ پکھۍ جاین بخور زالنُک حکم اوس دِتمُت۔ تِم تہِ یِمو بعلس تام، آفتابس تہٕ زونہِ خٲطرٕ، سیارن تہٕ آسمانن ہٕندِس سارِنٕے لشکرس خٲطرٕ بخور زٲلِتھ۔ {پُٹ...: ہیب۔ بند کرُن} {بت پرست...: ہیب۔ Chemarim} {سیارٕ: یا، باہ نشانہٕ یا، برج }\n6. تہٕ تٔمۍ أنِن خداوند سٕندِ گرٕ پیٹھٕ یُس یروشلم بغٲر کِدرون کِس نالہٕ کِس کُنہِ\n7.\\tتہٕ تٔمۍ کٔر سڈومیٹن ہٕندِس گرس پھُٹراوُن، یُس خداوند سٕندِس گرس سٍتـ̡ اوس، یێتہِ زنانہٕ باغہٕ خٲطرٕ پھانسی دِوان ٲس۔ {ہینگنگس: ہیب۔ مکانہٕ}\n8.\\tتہٕ تٔمۍ أنۍ تمام پادٕرۍ یہوداہ شہرو منزٕ نٮ۪بر تہٕ تِمن تھدٮ۪ن جاین ناپاک کٔرِتھ یِمن منز پادٕریو بخور زالنہٕ اوس آمُت، تہٕ یِمن دروازن ہٕنزِ تھدِ جایہِ پھُٹرٲوِن یُس شہرُک حاکم یشوع سٕندِس دروازس منز اژنہٕ وِزِ اوس، یُس شہر کِس دروازس پیٹھ أکِس شخصہٕ سٕندِس کھوورِ اتھس پیٹھ اوس۔\n9. بہر حال تھدِ مقامن ہٕندِ پادٕرۍ وٲتۍ نہٕ یروشلمس مَنٛز خداوند سٕندِس قربان گاہس تام، مگر تِمو کھیوٚو پننین باین مَنٛز خمیرٕ روٚس روٹی۔\n10.\\tتہٕ تٔمۍ کٔر توفیتھ ناپاک یُس حنوم کین بچن ہٕنزِ وادی منز چُھ، یُس نہٕ کانہہ تہِ انسان پننِس نیچوِس یا کورِ نارس منزہ مولیخس تام واتناوُن۔\n11. تہٕ تٔمۍ نِن تِم گُرِ یِم یہوداہ کٮ۪و بادشاہو آفتابس دِژمٕتۍ، خداوند سٕندِس گرس منز اژنہٕ وِزِ، یُس مضافاتس مَنٛز اوس، تہٕ زٲلِن آفتابٕکۍ رتھ نارٕ سٍتـ̡۔ {چیمبرلین: یا، خواجہ سرا، یا، افسر}\n12.\\tتہٕ یِم قربان گاہ یُس یہوداہ کِس بادشاہو بنوومُت اوس، تہٕ یِم قربان گاہ یُس منسیہن خداوند سٕندِس گرٕ کِس دۅن آنگنن مَنٛز بنوومُت اوس، تِمن دِژ بادشاہن تہٕ تِمن ہٕنزِ گردِ دِژٕن نالہٕ کِس نالہِ مَنٛز۔ {بریک...: یا، تتہِ پیٹھہ ژل}\n13.\\tتہٕ یِم تھدِ جایہِ یِم یروشلمس برونہہ کُن ٲسۍ، یِم دچھنہِ طرفہٕ بد عنوانی ہٕندِس پہاڑس پیٹھ ٲسۍ، یُس سُلیمانن اسرٲیلِکۍ بادشاہن اشتوریتھ سٕندِ خٲطرٕ زِدونین ہُند مکروہ تہٕ کیموش سٕندِ خٲطرٕ موآبین ہٕنز مکروہ تہٕ ملکوم سٕندِ خٲطرٕ عمون سٕندِس بچن ہُند مکروہ بنوومُت اوس، بادشاہن کٔر ناپاک ۔ {پہاڑ...: یعنی زیتونُک پہاڑ}\n14.\\tتہٕ تٔمۍ کٔرِن مجسمہٕ ٹُکرٕ ٹُکرٕ تہٕ ژٔٹِتھ کٔرِن باغہٕ تہٕ تِمن ہٕنزِ جایہ بٔرِتھ انسانن ہٕنزِ أڈجہِ۔ {تصویر: ہیب۔ مجسمہٕ}\n15.\\tامہِ علاوٕ یُس قربان گاہ یُس بیتھلس مَنٛز اوس، {تہٕ} سُہ تھدِ جاے یُس نیبت سٕندِس نیچو یروبعام یٔمۍ اسرٲیلِس گۅنہٕ بنوومُت اوس، سُہ قربان گاہ تہٕ تھدِ جاے یُس تٔمۍ ژٔٹِتھ تہٕ تھدِ جاے زٲلِتھ تہٕ زٲلِن باغ۔\n16. تہٕ یُتھ یوسیاہ ہن پانس پھیُر، تٔمۍ کٔر تِمن قبرن ہٕنز جاسوسی یِم پہاڑس مَنٛز ٲس، تہٕ سوزُن قبرو منزٕ أڈجہِ کٔڈِتھ تہٕ قربان گاہس پیٹھ زٲلِتھ تہٕ کٔرٕن خداوند سٕندِ کلامٕ مطٲبق یُس خدایہِ سٕندِ انسانن اعلان کورمُت اوس، یُس یِمن کلامَن ہُند اعلان کوٚر۔\n17.\\tامہ پتہ وۆن میہ کیا عنوان {چھہ} یُس میہ وچھان چھہ؟ تہٕ شہرٕکۍ مردو ووٚن أمِس {یہ} خدایہِ سٕندِ انسان سُند قبر، یُس یہوداہ پیٹھہٕ آمُت اوس، تہٕ یِمن چیزن ہُند اعلان کورُکھ یُس ژے بیت ایل کِس قربان گاہس خلاف کورمُت۔\n18.\\tتہٕ ووٚن أمِس کُنہِ کُنہِ کُنہِ سٍتـ کانہہ تہِ انسان گژھہِ نہ اڈجہ ہلاونہ۔ چنانچہ تمو ترٲو تسٕنزِ أڈجہِ کُنی، پیغمبر سٕنزِ أڈجہِ سٍتـ̡ یُس سامریہٕ منزٕ نیران اوس۔ {بونس: ہیب۔ بون ٹو ایسکیپ}\n19.\\tتہٕ یِم سارِنٕے تھدِ مقامن ہٕندِس سٍتـ̡ یِم سامریہ کِس شہرس مَنٛز ٲسۍ، یِم اسرٲیلٕکۍ بادشاہو {خدایہ} شرارت دِنہٕ خٲطرٕ بنوومٕتۍ، یوسیاہ نِش نِش تہٕ کٔرٕن تِمن سارِنٕے اعمال مُطٲبق یِم تٔمۍ سٕندِ بیتھلس مَنٛز کٔرۍمٕتۍ۔\n20.\\tتہٕ تٔمۍ مٲرِتھ تھدٮ۪ن مقامن ہٕندِ سارِنٕے پادٕرۍ یِم قربان گاہن پیٹھ ٲسۍ، تہٕ تمن پیٹھ زٲلِن انسانن ہٕنزِ أڈجہِ، تہٕ دِژُن یروشلم واپس۔ {سلیو: یا، قربان}\n21. تہٕ بادشاہن دِیُت سارنٕے لُکن ہُند حُکُم تہٕ وونُن زِ پاسور تھاوُن خداوند پنُن خدایہ، یِتھ کٔنۍ زَن یہِ اتھ عہد کِس کتابہِ مَنٛز لیکھنہٕ آمُت چھُ۔\n22.\\tیقینا اوس نہٕ یُتھ فسح منعقد، یُس اسرٲیلُک فیصلہ کٔرِتھ اوس تہٕ نہ اسرٲیلٕکۍ بادشاہن ہٕندِس سارِنٕے دۅہَس مَنٛز، تہٕ یہوداہ کِس بادشاہن ہٕندِس سارِنٕے دۅہَس مَنٛز۔\n23. مگر بادشاہ یوسیاہ سٕندِس اردٲہمہِ ؤریس مَنٛز، {یَتھ مَنٛز} یہِ فسح یروشلمس مَنٛز خداوند سٕندِ خٲطرٕ منعقد کرنہٕ آو۔\n24.\\tامہِ علاوٕ کٔر یُس یہوداہ کِس سرزمینس تہٕ یروشلمس مَنٛز جاسوسی کرنہٕ آمٕژ ٲس، یُس شریعت ہٕندِس کلامس مَنٛز لیکھنہٕ آمُت اوس، یُس حِلکیا پادٕرۍ خداوند سٕندِس گرس مَنٛز لبنہٕ آمُت اوس۔ {تصویر: یا، ٹیرافیم}\n25.\\tتہٕ أمِس برونہہ اوس نہٕ کانہہ بادشاہ یُس موسیٰ سٕندِ سارِنٕے شریعتہٕ مُطٲبق پنہٕ نِس دِلہٕ سٍتـ̡ تہٕ پوٗرٕ طاقتہٕ سٍتـ̡ خداوند سٕندِس کُن پھیرِ۔ نہ اوس تس پتہٕ تتہِ کانہہ تہِ پٲدٕ سپدان۔\n26. باوجوٗد تہِ ہیوٚت نہٕ خداوند پنہٕ نِس سٮ۪ٹھاہ غصہٕ سٍتـ̡ یێمہِ سٍتـ̡ یہوداہَس سٍتـ̡ شرارت دِنہٕ آمُت، تِکیازِ تٔمِس سٍتـ̡ یِمو سٍتـ̡ مَنسِہ سٍتـ̡ تٔمِس سٍتـ̡ اشتعال دِنہٕ آمُت اوس۔ {اشتعال: ہیب۔ غصہٕ}\n27. تہٕ خداوند ووٚن زِ بہٕ ہٹٲو یہوداہ تہِ پننہِ نظرِ نِش نِش، یِتھ کٔنۍ مے اسرٲیلِس ہٹٲومُت، تہٕ یُس شہر یروشلم یُس میہ ژٲرمُت چُھ، تہٕ یُس گرٕ میہ وونمُت چُھ، میون ناو آسہِ تتہِ۔\n28.\\tوۅنۍ یُس یوسیاہ سٕندِ باقٕے اعمال تہٕ تٔمۍ سٕندِ کٔرۍمٕتۍ، کیا تِم چھِنہٕ یہوداہ کِس بادشاہن ہٕنزِ تواریخ کِس کتابہِ مَنٛز لیکھنہٕ آمٕتۍ؟\n29.\\tپننِس زمانس منز گو مصرُک بادشاہ فرعونیچو اسریاہٕکِس بادشاہس خلاف دریائے فرات کُن تہٕ بادشاہ یوسیاہ گۆو أمِس خلاف۔ تہٕ تٔمۍ مور سُہ میگیڈوس منٛز، ییٚلہ تٔمۍ أمس وُچھمُت۔\n30.\\tتہٕ تٔمۍ سٕندِس خادمَو نِش نِیہِ سُہ میگیڈو سٕندِس أکِس رتھَس مَنٛز تہٕ أنِتھ یُس یورشلیم تہٕ دفن کٔرِکھ سُہ پننِس قبرس مَنٛز۔ تہٕ زمینہٕ کیو لوکو نیو یوسیاہ سُند نیچو یہواحاز، تہٕ کوٚرُن أمِس مسح تہٕ بنووُن پننِس مٲلہِ سٕندِ بدلہٕ بادشاہ۔\n31.\\tیہواہاز اوس وُہُہ تریہ وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر۔ تہٕ تٔمۍ کٔر یروشلمس مَنٛز تریہ ریتھ حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس ہموتل، یۄس لبناہٕچ یرمیاہ سٕنز کوٗر ٲس۔ {یہواہاز: شلم تہِ ونان چھِ}\n32. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز یُس بد کار اوس، یُس تٔمۍ سٕندِس مٲلِس ماجہ ہٕندِ کٔرمٕژ ٲس۔\n33.\\tتہٕ فرعونچوہن تھووُن سُہ حمتھ کِس سرزمینس منز ربلہ کِس علاقس مَنٛز، یُتھ نہٕ سُہ یروشلمس مَنٛز حکومت کرِ۔ تہٕ زمینس تھووُن ہتھ ٹیلنٹ رۄپہٕ تہٕ سۄنہٕ سُند ٹیلنٹ خراج تحسین پیش کرنہٕ۔ {یہ...: یا، تکیازِ تٔمۍ ٲس حکومت کٔرمٕژ} {تھو د...: ہیب۔ زمینس پیٹھ کرو جرمانہٕ}\n34. تہٕ فرعونچوہن بنوو یوسیاہ سُند نیچو یوسیاہ سٕندِس مٲلِس کمرس مَنٛز، تہٕ بنووُن تٔمۍ سُند ناو یہویاقیم تہٕ نیُن یہوآہاز تہٕ سُہ آو مصر تہٕ تتہِ موٗد۔\n35. تہٕ یہویاکیمن دِژ فرعونس رۄپہٕ تہٕ سۄن۔ مگر تٔمۍ لوٚگ فرعون سٕندِس حُکمس مُطٲبق پٲنسہٕ دِنہٕ خٲطرٕ زمینس پیٹھ ٹیکس: تٔمۍ ہیوٚت زمینہٕ کین لوکن ہٕندِ رۄپہٕ تہٕ سۄنہٕ تہٕ پرٮ۪تھ أکِس سٕندِس ٹیکسہٕ مطٲبق، فرعونیچوہس دِنہٕ خٲطرٕ۔\n36.\\tیہوُہ وُہُر وُہُر ییلہ تٔمۍ حکومت کرٕنۍ شروع کٔر۔ تہٕ تٔمۍ کٔر یروشلمس منٛز کاہ ؤرین حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس زبودہ، یۄس رومہ کِس پدیہ سٕنز کوٗر ٲس۔\n37. تہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز یُس بد کار اوس، یُس تٔمۍ سٕندِس مٲلِس ماجہ ہٕندِ کٔرمٕژ ٲس۔","1. پننین دوہن منز آو بابلُک بادشاہ نبوکدنضر تہٕ یہوہیکیم بنیوو تٔمِس تریہ ؤری تٔمِس نوکر۔\n2. تہٕ خداوند سوٗزۍ أمِس خٕلاف کلدین ہٕندِ جمٲژ تہٕ شامٕکۍ جمٲژ تہٕ موآبین ہٕندِ تہٕ عمون سٕندِ اولاد ہٕندِ جمٲژ تہٕ سوٗزِن یہوداہَس خلاف یُس خداوند سٕندِ کلامَس مُطٲبق تباہ کرنہٕ خٲطرٕ، یُس تٔمۍ پننین خدمتگارن پیغمبرن ہٕندِ طرفہٕ کتھ کٔر۔ {by: Heb. اتھہٕ سٍتۍ }\n3. یقینا خداوند سٕندِس حُکمس پیٹھ آو یہوداہ سٕندِس حُکمس سٍتـ̡ یُس تٔمۍ سٕندِس کُنہِ\n4.\\tتہٕ یُس معصوم خونس سٍتـ̡ یُس تٔمۍ سُند بہتُن اوس، تکیازِ تٔمۍ اوس یروشلمس معصوم خونس سٍتـ̡ بٔرِتھ۔ یُس نہٕ رب معافی دِیہِ۔\n5.\\tوۅنۍ چھہ یہوداہ کین بادشاہن ہنزِ تواریخ کتابہِ منز لیکھنہ آمت تہ یہ چھہ نہ یہوداہ کین بادشاہن ہنزِ تواریخ کتابہِ منز لیکھنہ آمت؟\n6.\\tیێمہِ سٍتـ̡ گۆو یہویاقیم پننین مٲلن سٍتـ̡ شوٚنگتھ: تہٕ یہویاکین کٔر تٔمۍ سٕندِ بدلہٕ بادشاہ۔\n7. تہٕ مصرُک بادشاہ آو نہٕ بییہِ پننہِ زمینہٕ منزٕ نیبر، تکیازِ بابل کِس بادشاہن اوس دریائے مصر پیٹھٕ دریائے فرات تام سُہ سورُے نِمُت یُس مصر کِس بادشاہس سٍتـ̡ وابستہٕ اوس۔\n8.\\tیہویاچین اوس ارداہ وُہُر ییلہ تٔمۍ حکومت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس منز تریہ ریتن حکومت۔ تہٕ تسٕنزِ ماجہ ہُند ناو اوس نہوشتا، یۄس یروشلم کِس ایلناتھن سٕنز کوٗر ٲس۔ {یہویاچن: یتھ جیکونیاہ تہٕ کونیاہ تہِ ونان چھِ}\n9.\\tتہٕ تٔمۍ کٔر خداوند سٕندِس نظرس منز یُس بد کار اوس، یُس تٔمۍ سٕندِس مٲلہِ سٕندِ کٔرمٕژ ٲس۔\n10. تمہِ وِزِ آو بابل کِس بادشاہ نبوکدنضر سٕندِ خادم یروشلمس خلاف تہٕ شہرس آو محاصرٕ کرنہٕ۔ {اوس...: ہیب۔ محاصرس منٛز آو\n11. تہٕ بابلُک بادشاہ نبوکدنضر آو شہرس خلاف تہٕ تٔمۍ سٕندٮ۪و خدمتگارو کوٚر اتھ محاصرٕ۔\n12.\\tتہٕ یہوداہُک بادشاہ یہوُدہُک بادشاہ گۆو بابل کِس بادشاہس نِش، سُہ تہٕ أمۍ سٕنزِ ماجہ تہٕ تٔمۍ سٕندِس نوکرَن تہٕ تٔمۍ سٕندِس شہزادن تہٕ تٔمۍ سٕندِس افسرس نِش نِش تہٕ بابل کِس بادشاہن نِش نیُن تہٕ بابل کِس بادشاہن نِش نیُن تہٕ بابل کِس بادشاہن نِش نیُن سُہ پننہِ حکومتہٕ کِس ٲٹھمِس ؤریس مَنٛز۔ {افسر: یا، خواجہ سرا} {تٔمۍ سُند دورِ حکومت: نبوکدنضر سُند ٲٹھم ؤری}\n13. تہٕ تٔمۍ نِش نِش خداوند سٕندِ گرٕکۍ سٲری خزانہٕ تہٕ بادشاہ سٕندِ گرٕکۍ خزانہٕ، تہٕ ژٔٹِن سٲرِی سۄنہٕ بانہٕ یِم اسرٲیلِکۍ سلیمان بادشاہن خداوند سٕندِس مندرس مَنٛز بنٲومٕتۍ ٲسۍ، یِتھہٕ کٔنۍ خداوند سٕندِس مندرس مَنٛز بنوومُت اوس۔\n14.\\tتہٕ تٔمۍ نِش نِش سورے یروشلم، تہٕ سارِنٕے شہزادہٕ، تہٕ سارِنٕے بہادر نفر، دَہ ساس قٲد، تہٕ سارِنٕے کٲرۍگر تہٕ لوہار نِن: کانہہ تہِ روٗد نہٕ، مگر زمینہٕ کین غریبن ہٕندِس لُکن علاوٕ۔\n15. تہٕ تٔمۍ نِیہِ یہویاچِن بابل تہٕ بادشاہ سٕنز موج، تہٕ بادشاہ سٕنزِ زنانہٕ، تہٕ تٔمۍ سٕندِس افسرس تہٕ زمینہٕ کِس طاقتور، یِمو نِیہِ سُہ یروشلم پیٹھٕ بابل قٲد کرنہٕ۔ {افسر: یا، خواجہ سرا}\n16.\\tتہٕ سارِنٕے طاقتور نفر، ستھ ساس، تہٕ ساس کاریگر تہٕ لوہار، سٲری ٲسۍ جنگہٕ خٲطرٕ موزون، حتیٰ کہ تِم تہِ بابل ہُند بادشاہ بابل قٲد کٔرِتھ۔\n17.\\tتہٕ بابل کِس بادشاہن بنوو متانیاہ پننہِ بدلہٕ پننِس مٲلہِ سُند بوے بادشاہ، تہٕ بدلٲوِن تٔمۍ سُند ناو صدقیاہ۔\n18.\\tصدیقیاہ اوس وُہُہ وُہُر ییلہ تٔمِس بادشاہی شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز کاہ وُہُر حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس ہموتل، یۄس لبناہٕچ یرمیاہ سٕنز کوٗر ٲس۔\n19.\\tتہٕ یُس خداوند سٕندِس نظرس منز بُرٕ اوس یُس یہویاکیمن کٔرمُت اوس۔\n20. کیازِ خداوند سٕندِ غصہٕ سٍتـ̡ سپد یروشلمس تہٕ یہوداہَس مَنٛز سپُد، یوتام تٔمۍ تِم پننہِ حٲضِری نِش کٔڑِتھ کٔرِتھ کٔرِتھ زِ صدیقیاہ کٔر بابل کِس بادشاہس خلاف بغاوت۔","1.\\tتہٕ سپُد تٔمۍ سٕندِس دورِ حکومتہٕ کِس نٔوِمِس ؤریس منز، دٔہمہِ ریتس مَنٛز، دٔہمہِ دۅہہٕ مَنٛز، {یہ} بابل ہُک بادشاہ نبوکدنضر آو تہٕ تٔمۍ سُند سارِوٕے لشکر آو یروشلمس خلاف تہٕ اتھ خلاف لٔگ۔ تہٕ تمو بنٲو اتھ اندۍ پٔکۍ قلعہٕ۔\n2. تہٕ بادشاہ صدقیاہ سٕندِس کٔہمہِ ؤریس تام آو شہرس محاصرٕ کرنہٕ۔\n3. تہٕ ژورمہِ ریتہٕ کِس نٔوِمہِ دۅہہٕ ووت شہرس مَنٛز قحط، تہٕ زمینہٕ کین لوٗکن ہٕندِ خٲطرٕ اوس نہٕ کانہہ روٹ۔\n4.\\tتہٕ شہر آو پھُٹنہٕ، تہٕ سارِنٕے جنگی مرد ژٔلِتھ رٲژ دۄن دیوارن درمیان دروازٕ کِنۍ یُس {چُھ} بادشاہ سٕندِس باغس نِش اوس: (وۅنۍ ٲسۍ کلدی {ٲس} اندۍ پکھۍ شہرس خلاف:) تہٕ {بادشاہ} گٔیہِ میدانس کُن وتہِ۔\n5. تہٕ کلدین ہٕندِ لشکر لوٚگ بادشاہس پتہٕ تہٕ یریحہ کِس مٲدانس مَنٛز لوٚگ أمِس پٲٹھۍ، تہٕ تٔمۍ سُند سورُے لشکر گٔیہِ أمِس نِش بکھرِتھ۔\n6.\\tیێمہِ سٍتـ̡ نِیوو بادشاہ تہٕ أنِتھ بابل کِس بادشاہس نِش ربلہ نِش۔ تہٕ تمو دیت تس پیٹھ فیصلہٕ۔ {دِیُت...: ہیب۔ أمِس سٍتۍ کٔر فیصلہٕ}\n7. تہٕ تِمو مارِکھ سُہ سٕندِس نظرن برونہہ کُن، تہٕ کٔرِکھ سدقیاہ سٕنزِ أچھ تہٕ کٔرِکھ سُہ پیتلٕچ زنجیر تہٕ نِیُن بابل کُن۔ {پُٹ...: ہیب۔ انہِ کٔرِتھ بٔنِتھ\n8. تہٕ پوٗنٛژمہِ ریتس منز، یُس بابل کِس بادشاہ نبوکدنضر سُند کُنوُہِم ؤری چُھ، یُس بابل کِس بادشاہ سُند کُنوُہِم ؤری چُھ، یُس رٲچھ کُن کپتان نیبوزاردان آو یروشلمس منز: {کپتان...: یا، چیف مارشل}\n9. تہٕ تٔمۍ زٲلِتھ خداوند سُند گر، تہٕ بادشاہ سُند گر، تہٕ یروشلمٕکۍ سارِنٕے مکانہٕ، تہٕ پرٮ۪تھ أکِس بٔڈِس مکانس زٲلِتھ دِنہٕ۔\n10.\\tتہٕ چالڈین ہُند سٲری لشکر، یُس رٲچھ کِس کپتانس سٍتـ̡ اوس، یُس یروشلم کِس دیوارس اندۍ پٔکھۍ پھُٹرٲوِتھ۔\n11.\\tوۅنۍ گٔیہِ باقٕے لُکھ شہرس مَنٛز باقٕے لُکھ تہٕ یِم ژٔلِتھ بابل کِس بادشاہس نِش ژٔلِتھ گٔیہِ، یِمن ہٕندِس ہجومَس ہٕندِس باقیاتس سٍتـ̡ نِبوزارادَن نِش نِنہٕ۔ {مفرور: ہیب۔ پٔرِتھ گٔیہِ}\n12.\\tمگر رٲچھ کُن کپتان تروو زمینہٕ کین غریبن ہٕندِس باغس تہٕ کاشتکار بننہٕ خٲطرٕ۔\n13. تہٕ خداوند سٕندِس گرس مَنٛز پیتلٕکۍ تھَم تہٕ بُنیاد تہٕ بٔرِس سمندرٕ یُس خداوند سٕندِس گرس مَنٛز اوس، تہٕ یِمن ہُند پیتل بابل نِتھ پھُٹرٲوِتھ۔\n14.\\tتہٕ بانہٕ، بیلچہٕ، تہٕ نِش تہٕ چمچ، تہٕ پیتلٕکۍ سارِنٕے بانہٕ یِمو سٍتـ̡ تِم خدمت کران ٲسۍ۔\n15.\\tتہٕ نار تہٕ پیالہٕ، {تہٕ} تِتھۍ چیز یِم سۄنہٕ سٕندِ، {منز} سۄنہٕ تہٕ رۄپھٕ، {منز} رۄپھٕ، رٲچھ دارن نِش نِنہٕ۔\n16.\\tزٕ تھم، اکھ سمندر، تہٕ تِم بنیادٕ یِم سُلیمانن خداوند سٕندِ گرٕ خٲطرٕ بنٲومٕتۍ ٲسۍ۔ یمن سارِنٕے بانن ہُند پیتل اوس نہ وزن۔ {اکھ...: ہیب۔ اکھ سمندر}\n17.\\tأکِس تھمُک تھزر اوس ارداہ کیوبِٹ، تہٕ اتھ پیٹھ اوس چیپٹر {اوس} پیتل: تہٕ چیپٹرُک تھزر اوس تریہ کیوبٹ۔ تہٕ گُلہٕ ہٕنز کٲم، تہٕ اندۍ چپِس پیٹھ دٲر تہٕ یِمن ہٕندۍ پٲٹھۍ، دۆیم تھم تہٕ گُلہٕ کامہِ سٍتۍ۔\n18.\\tتہٕ رٲچھ کٔرِتھ کٔرِن سرایاہ، بٔڈ پادٕر، تہٕ دوٚیِم پادٕرۍ زِفانیاہ تہٕ دٲرِ ہٕندِس ترٚے رٲچھ کَرن وٲلۍ: {دروازٕ: عبری۔ تھریشولڈ}\n19.\\tتہٕ شہرٕ منزٕ نِش نِیو تٔمۍ اکھ افسر یُس جنگی نفرن ہٕندِس حٲضِرس پیٹھ مقرر کرنہٕ آمُت اوس، تہٕ یِمو منزٕ پانژھ نفر یِم بادشاہ سٕندِس حٲضِرس منز ٲسۍ، یِم شہرس منز لبنہٕ آمٕتۍ ٲسۍ، تہٕ میزبانُک اہم کاتب، یٔمۍ زمینہٕ کین لوٗکن جمع کٔرۍ، تہٕ شہرس منز لبنہٕ آمٕتۍ زمینہٕ کین لوکن ہٕندِ تریہ شٹھ نفر جمع کٔرۍ۔  {افسر: یا، خواجہ سرا} {ٲسۍ منز...: ہیب۔ بادشاہ سُند بُتھ وُچھمُت} {پرنسپل...: یا، کپتان سُند کاتب}\n20.\\tتہٕ نبوزاردان کپتانن نِش یِم نِتھ بابل کِس بادشاہس نِش ربلاہس نِش۔\n21.\\tتہٕ بابل کِس بادشاہن دِژ تِمن ہُند مارُن تہٕ مارُن تِم رِبلہ کِس زمینس مَنٛز۔ چنانچہ یہوداہ آو تِہٕنزِ زمینہٕ منزٕ نِنہٕ۔\n22.\\tتہٕ یِم لُکھ یہوداہ کِس سرزمینس مَنٛز روٗدۍ، یِمن بابل کِس بادشاہ نبوکدنضرن ترٲومُت اوس، تِمن پیٹھ تہِ بنوو تِمن پیٹھ یُس شافان سُند نیچو احیکم سُند نیچو گدلیاہ سُند نیچو حُکُمران اوس۔\n23.\\tییلہ فوجن ہٕندِس سارِنٕے کپتان، تِمو تہٕ تِہندیو نفرو بوٗز زِ بابل کِس بادشاہن چُھ گدلیاہ گورنر بنوومُت، تتہِ آو گدلیاہ نِش مِزپاہ، حتیٰ کہ نیتھانیا سُند نیچو اسماعیل، تہٕ کیرۂ سُند نیچو جوحانان، تہٕ تنہومیت نیتوفثی سُند نیچو سریاہ تہٕ ماخاتھی سُند نیچو جازنیاہ آو ۔  تم تہٕ تہند نفر۔\n24.\\tتہٕ گیڈالیاہَن کٔر تِمن تہٕ تِہندین نفرن سٍتـ̡ قسم، تہٕ وونُن تِمن سٍتـ̡ چالدین ہٕندِس خادم بننہٕ سٍتـ̡ مہٕ خوفہٕ: زمینس مَنٛز روزُن تہٕ بابل کِس بادشاہس سٕنز خدمت۔ تہٕ یہ گژھہِ ژیہ ٹھیٖک۔\n25.\\tمگر سپُد سٔتِمِس رٮ۪تس مَنٛز زِ نیتھانیا سُند نیچو اسماعیل آو تہٕ أمِس سٍتـ̡ دَہ نفر تہٕ دِتُن گدلیاہ تہٕ یہودی تہٕ کلدی یِم أمِس سٍتـ̡ مزپاہَس مَنٛز ٲسۍ۔ {شاہی: ہیب۔ بادشٲہی ہُند}\n26.\\tتہٕ سارِوٕے لُکھ لُکھ تہٕ لشکر ہٕندِ کپتان گٔیہِ وۅتھٕ تہٕ آۓ مصرس کُن، تکیازِ تِم ٲسۍ کلدین نِش کھوژان۔\n27. تہٕ یہِ سپُد یہوداہ کِس بادشاہ یہوویاچن سٕندِ قٲد گژھنہٕ کِس سَتِمہِ تہٕ ترہمہِ ؤریس مَنٛز، بٔہمہِ رٮ۪تہٕ کِس سٔتِمہِ تہٕ وُہمہِ دۅہہٕ کِس سٔتِمِس دۅہہٕ سٍتـ̡ تُلُن بابل کِس بادشاہ ایویلمیروداخ یَتھ ؤریس مَنٛز تُلُن یہوداہ کِس بادشاہ یہوواہُک کلہٕ قٲد خانہٕ منزٕ تُلُن۔\n28.\\tتہٕ تٔمۍ کٔر أمِس سٍتـ̡ مہربانی سان کتھ تہٕ تھووُن پنُن تخت تمن بادشاہن ہٕندِس تختس پیٹھ، یُس أمس سٍتـ̡ بابلس مَنٛز اوس۔ {مہربانی...: ہیب۔ أمِس سۭتۍ اصل چیز}\n29.\\tتہٕ بدلٲوِن قٲدٕکۍ پَلَو، تہٕ سُہ اوس سارِنٕے دۅہن أمِس برونہہ کنہِ لگاتار روٹی کھیوان۔\n30.\\tتہٕ تٔمۍ سُند الاؤنس اوس بادشاہ سٕندِ طرفہٕ دِنہٕ یِنہٕ وول لگاتار الاؤنس دِنہٕ یِوان، یُس تٔمۍ سٕنزِ زندگی ہٕندِس سارِنٕے دۅہس خٲطرٕ روزانہٕ دِنہٕ یوان اوس۔"];
